INSERT INTO `stretchy_report` VALUES (1,'Client Listing','Table',NULL,'Client','select\nconcat(repeat(\"..\",\n   ((LENGTH(ounder.`hierarchy`) - LENGTH(REPLACE(ounder.`hierarchy`, \'.\', \'\')) - 1))), ounder.`name`) as \"Office/Branch\",\n c.account_no as \"Client Account No.\",\nc.display_name as \"Name\",\nr.enum_message_property as \"Status\",\nc.activation_date as \"Activation\", c.external_id as \"External Id\"\nfrom m_office o\njoin m_office ounder on ounder.hierarchy like concat(o.hierarchy, \'%\')\nand ounder.hierarchy like concat(\'${currentUserHierarchy}\', \'%\')\njoin m_client c on c.office_id = ounder.id\nleft join r_enum_value r on r.enum_name = \'status_enum\' and r.enum_id = c.status_enum\nwhere o.id = ${officeId}\norder by ounder.hierarchy, c.account_no','Individual Client Report\r\n\r\nLists the small number of defined fields on the client table.  Would expect to copy this \n\nreport and add any \'one to one\' additional data for specific tenant needs.\r\n\r\nCan be run for any size MFI but you\'d expect it only to be run within a branch for \n\nlarger ones.  Depending on how many columns are displayed, there is probably is a limit of about 20/50k clients returned for html display (export to excel doesn\'t \n\nhave that client browser/memory impact).',1,1,0);
INSERT INTO `stretchy_report` VALUES (2,'Client Loans Listing','Table',NULL,'Client','select\nconcat(repeat(\"..\",\n   ((LENGTH(ounder.`hierarchy`) - LENGTH(REPLACE(ounder.`hierarchy`, \'.\', \'\')) - 1))), ounder.`name`) as \"Office/Branch\", c.account_no as \"Client Account No.\",\nc.display_name as \"Name\",\nr.enum_message_property as \"Client Status\",\nlo.display_name as \"Loan Officer\", l.account_no as \"Loan Account No.\", l.external_id as \"External Id\", p.name as Loan, st.enum_message_property as \"Status\",\nf.`name` as Fund, purp.code_value as \"Loan Purpose\",\nifnull(cur.display_symbol, l.currency_code) as Currency,\nl.principal_amount, l.arrearstolerance_amount as \"Arrears Tolerance Amount\",\nl.number_of_repayments as \"Expected No. Repayments\",\nl.annual_nominal_interest_rate as \" Annual Nominal Interest Rate\",\nl.nominal_interest_rate_per_period as \"Nominal Interest Rate Per Period\",\nipf.enum_message_property as \"Interest Rate Frequency\",\nim.enum_message_property as \"Interest Method\",\nicp.enum_message_property as \"Interest Calculated in Period\",\nl.term_frequency as \"Term Frequency\",\ntf.enum_message_property as \"Term Frequency Period\",\nl.repay_every as \"Repayment Frequency\",\nrf.enum_message_property as \"Repayment Frequency Period\",\nam.enum_message_property as \"Amortization\",\nl.total_charges_due_at_disbursement_derived as \"Total Charges Due At Disbursement\",\ndate(l.submittedon_date) as Submitted, date(l.approvedon_date) Approved, l.expected_disbursedon_date As \"Expected Disbursal\",\ndate(l.expected_firstrepaymenton_date) as \"Expected First Repayment\",\ndate(l.interest_calculated_from_date) as \"Interest Calculated From\" ,\ndate(l.disbursedon_date) as Disbursed,\ndate(l.expected_maturedon_date) \"Expected Maturity\",\ndate(l.maturedon_date) as \"Matured On\", date(l.closedon_date) as Closed,\ndate(l.rejectedon_date) as Rejected, date(l.rescheduledon_date) as Rescheduled,\ndate(l.withdrawnon_date) as Withdrawn, date(l.writtenoffon_date) \"Written Off\"\nfrom m_office o\njoin m_office ounder on ounder.hierarchy like concat(o.hierarchy, \'%\')\nand ounder.hierarchy like concat(\'${currentUserHierarchy}\', \'%\')\njoin m_client c on c.office_id = ounder.id\nleft join r_enum_value r on r.enum_name = \'status_enum\'\n and r.enum_id = c.status_enum\nleft join m_loan l on l.client_id = c.id\nleft join m_staff lo on lo.id = l.loan_officer_id\nleft join m_product_loan p on p.id = l.product_id\nleft join m_fund f on f.id = l.fund_id\nleft join r_enum_value st on st.enum_name = \"loan_status_id\" and st.enum_id = l.loan_status_id\nleft join r_enum_value ipf on ipf.enum_name = \"interest_period_frequency_enum\"\n and ipf.enum_id = l.interest_period_frequency_enum\nleft join r_enum_value im on im.enum_name = \"interest_method_enum\"\n and im.enum_id = l.interest_method_enum\nleft join r_enum_value tf on tf.enum_name = \"term_period_frequency_enum\"\n and tf.enum_id = l.term_period_frequency_enum\nleft join r_enum_value icp on icp.enum_name = \"interest_calculated_in_period_enum\"\n and icp.enum_id = l.interest_calculated_in_period_enum\nleft join r_enum_value rf on rf.enum_name = \"repayment_period_frequency_enum\"\n and rf.enum_id = l.repayment_period_frequency_enum\nleft join r_enum_value am on am.enum_name = \"amortization_method_enum\"\n and am.enum_id = l.amortization_method_enum\nleft join m_code_value purp on purp.id = l.loanpurpose_cv_id\nleft join m_currency cur on cur.code = l.currency_code\nwhere o.id = ${officeId}\nand (l.currency_code = \"${currencyId}\" or \"-1\" = \"${currencyId}\")\nand (l.product_id = \"${loanProductId}\" or \"-1\" = \"${loanProductId}\")\nand (ifnull(l.loan_officer_id, -10) = \"${loanOfficerId}\" or \"-1\" = \"${loanOfficerId}\")\nand (ifnull(l.fund_id, -10) = ${fundId} or -1 = ${fundId})\nand (ifnull(l.loanpurpose_cv_id, -10) = ${loanPurposeId} or -1 = ${loanPurposeId})\norder by ounder.hierarchy, 2 , l.id','Individual Client Report\r\n\r\nPretty \n\nwide report that lists the basic details of client loans.  \r\n\r\nCan be run for any size MFI but you\'d expect it only to be run within a branch for larger ones.  \n\nThere is probably is a limit of about 20/50k clients returned for html display (export to excel doesn\'t have that client browser/memory impact).',1,1,0);
INSERT INTO `stretchy_report` VALUES (5,'Loans Awaiting Disbursal','Table',NULL,'Loan','SELECT \r\nconcat(repeat(\"..\",   \r\n   ((LENGTH(ounder.`hierarchy`) - LENGTH(REPLACE(ounder.`hierarchy`, \'.\', \'\')) - 1))), ounder.`name`) as \"Office/Branch\",\r\nc.account_no as \"Client Account No\", c.display_name as \"Name\", l.account_no as \"Loan Account No.\", pl.`name` as \"Product\", \r\nf.`name` as Fund, ifnull(cur.display_symbol, l.currency_code) as Currency,  \r\nl.principal_amount as Principal,  \r\nl.term_frequency as \"Term Frequency\",\n\n\r\ntf.enum_message_property as \"Term Frequency Period\",\r\nl.annual_nominal_interest_rate as \" Annual Nominal Interest Rate\",\r\ndate(l.approvedon_date) \"Approved\",\r\ndatediff(l.expected_disbursedon_date, curdate()) as \"Days to Disbursal\",\r\ndate(l.expected_disbursedon_date) \"Expected Disbursal\",\r\npurp.code_value as \"Loan Purpose\",\r\n lo.display_name as \"Loan Officer\"\r\nfrom m_office o \r\njoin m_office ounder on ounder.hierarchy like concat(o.hierarchy, \'%\')\r\nand ounder.hierarchy like concat(\'${currentUserHierarchy}\', \'%\')\r\njoin m_client c on c.office_id = ounder.id\r\njoin m_loan l on l.client_id = c.id\r\njoin m_product_loan pl on pl.id = l.product_id\r\nleft join m_staff lo on lo.id = l.loan_officer_id\r\nleft join m_currency cur on cur.code = l.currency_code\r\nleft join m_fund f on f.id = l.fund_id\r\nleft join m_code_value purp on purp.id = l.loanpurpose_cv_id\r\nleft join r_enum_value tf on tf.enum_name = \"term_period_frequency_enum\" and tf.enum_id = l.term_period_frequency_enum\r\nwhere o.id = ${officeId}\r\nand (l.currency_code = \"${currencyId}\" or \"-1\" = \"${currencyId}\")\r\nand (l.product_id = \"${loanProductId}\" or \"-1\" = \"${loanProductId}\")\r\nand (ifnull(l.loan_officer_id, -10) = \"${loanOfficerId}\" or \"-1\" = \"${loanOfficerId}\")\r\nand (ifnull(l.fund_id, -10) = ${fundId} or -1 = ${fundId})\r\nand (ifnull(l.loanpurpose_cv_id, -10) = ${loanPurposeId} or -1 = ${loanPurposeId})\r\nand l.loan_status_id = 200\r\norder by ounder.hierarchy, datediff(l.expected_disbursedon_date, curdate()),  c.account_no','Individual Client Report',1,1,0);
INSERT INTO `stretchy_report` VALUES (6,'Loans Awaiting Disbursal Summary','Table',NULL,'Loan','SELECT \r\nconcat(repeat(\"..\",   \r\n   ((LENGTH(ounder.`hierarchy`) - LENGTH(REPLACE(ounder.`hierarchy`, \'.\', \'\')) - 1))), ounder.`name`) as \"Office/Branch\",\r\npl.`name` as \"Product\", \r\nifnull(cur.display_symbol, l.currency_code) as Currency,  f.`name` as Fund,\r\nsum(l.principal_amount) as Principal\r\nfrom m_office o \r\njoin m_office ounder on ounder.hierarchy like concat(o.hierarchy, \'%\')\r\nand ounder.hierarchy like concat(\'${currentUserHierarchy}\', \'%\')\r\njoin m_client c on c.office_id = ounder.id\r\njoin m_loan l on l.client_id = c.id\r\njoin m_product_loan pl on pl.id = l.product_id\r\nleft join m_staff lo on lo.id = l.loan_officer_id\r\nleft join m_currency cur on cur.code = l.currency_code\r\nleft join m_fund f on f.id = l.fund_id\r\nleft join m_code_value purp on purp.id = l.loanpurpose_cv_id\r\nwhere o.id = ${officeId}\r\nand (l.currency_code = \"${currencyId}\" or \"-1\" = \"${currencyId}\")\r\nand (l.product_id = \"${loanProductId}\" or \"-1\" = \"${loanProductId}\")\r\nand (ifnull(l.loan_officer_id, -10) = \"${loanOfficerId}\" or \"-1\" = \"${loanOfficerId}\")\r\nand (ifnull(l.fund_id, -10) = ${fundId} or -1 = ${fundId})\r\nand (ifnull(l.loanpurpose_cv_id, -10) = ${loanPurposeId} or -1 = ${loanPurposeId})\r\nand l.loan_status_id = 200\r\ngroup by ounder.hierarchy, ounder.name, pl.`name`, l.currency_code,  f.`name`\r\norder by ounder.hierarchy, ounder.name, pl.`name`, l.currency_code,  f.`name`','Individual Client Report',1,1,0);
INSERT INTO `stretchy_report` VALUES (7,'Loans Awaiting Disbursal Summary by Month','Table',NULL,'Loan','SELECT \r\nconcat(repeat(\"..\",   ((LENGTH(ounder.`hierarchy`) - LENGTH(REPLACE(ounder.`hierarchy`, \'.\', \'\')) - 1))), ounder.`name`) as \"Office/Branch\",\r\npl.`name` as \"Product\", \r\nifnull(cur.display_symbol, l.currency_code) as Currency,  \r\nyear(l.expected_disbursedon_date) as \"Year\", \r\nmonthname(l.expected_disbursedon_date) as \"Month\",\r\nsum(l.principal_amount) as Principal\r\nfrom m_office o \r\njoin m_office ounder on ounder.hierarchy like concat(o.hierarchy, \'%\')\r\nand ounder.hierarchy like concat(\'${currentUserHierarchy}\', \'%\')\r\njoin m_client c on c.office_id = ounder.id\r\njoin m_loan l on l.client_id = c.id\r\njoin m_product_loan pl on pl.id = l.product_id\r\nleft join m_staff lo on lo.id = l.loan_officer_id\r\nleft join m_currency cur on cur.code = l.currency_code\r\nleft join m_fund f on f.id = l.fund_id\r\nleft join m_code_value purp on purp.id = l.loanpurpose_cv_id\r\nwhere o.id = ${officeId}\r\nand (l.currency_code = \"${currencyId}\" or \"-1\" = \"${currencyId}\")\r\nand (l.product_id = \"${loanProductId}\" or \"-1\" = \"${loanProductId}\")\r\nand (ifnull(l.loan_officer_id, -10) = \"${loanOfficerId}\" or \"-1\" = \"${loanOfficerId}\")\r\nand (ifnull(l.fund_id, -10) = ${fundId} or -1 = ${fundId})\r\nand (ifnull(l.loanpurpose_cv_id, -10) = ${loanPurposeId} or -1 = ${loanPurposeId})\r\nand l.loan_status_id = 200\r\ngroup by ounder.hierarchy, pl.`name`, l.currency_code, year(l.expected_disbursedon_date), month(l.expected_disbursedon_date)\r\norder by ounder.hierarchy, pl.`name`, l.currency_code, year(l.expected_disbursedon_date), month(l.expected_disbursedon_date)','Individual Client Report',1,1,0);
INSERT INTO `stretchy_report` VALUES (8,'Loans Pending Approval','Table',NULL,'Loan','SELECT \r\nconcat(repeat(\"..\",   \r\n   ((LENGTH(ounder.`hierarchy`) - LENGTH(REPLACE(ounder.`hierarchy`, \'.\', \'\')) - 1))), ounder.`name`) as \"Office/Branch\",\r\nc.account_no as \"Client Account No.\", c.display_name as \"Client Name\", \r\nifnull(cur.display_symbol, l.currency_code) as Currency,  pl.`name` as \"Product\", \r\nl.account_no as \"Loan Account No.\", \r\nl.principal_amount as \"Loan Amount\", \r\nl.term_frequency as \"Term Frequency\",\n\n\r\ntf.enum_message_property as \"Term Frequency Period\",\r\nl.annual_nominal_interest_rate as \" Annual \n\nNominal Interest Rate\", \r\ndatediff(curdate(), l.submittedon_date) \"Days Pending Approval\", \r\npurp.code_value as \"Loan Purpose\",\r\nlo.display_name as \"Loan Officer\"\r\nfrom m_office o \r\njoin m_office ounder on ounder.hierarchy like concat(o.hierarchy, \'%\')\r\nand ounder.hierarchy like concat(\'${currentUserHierarchy}\', \'%\')\r\njoin m_client c on c.office_id = ounder.id\r\njoin m_loan l on l.client_id = c.id\r\njoin m_product_loan pl on pl.id = l.product_id\r\nleft join m_staff lo on lo.id = l.loan_officer_id\r\nleft join m_currency cur on cur.code = l.currency_code\r\nleft join m_code_value purp on purp.id = l.loanpurpose_cv_id\r\nleft join r_enum_value tf on tf.enum_name = \"term_period_frequency_enum\" and tf.enum_id = l.term_period_frequency_enum\r\nwhere o.id = ${officeId}\r\nand (l.currency_code = \"${currencyId}\" or \"-1\" = \"${currencyId}\")\r\nand (l.product_id = \"${loanProductId}\" or \"-1\" = \"${loanProductId}\")\r\nand (ifnull(l.loan_officer_id, -10) = \"${loanOfficerId}\" or \"-1\" = \"${loanOfficerId}\")\r\nand (ifnull(l.loanpurpose_cv_id, -10) = ${loanPurposeId} or -1 = ${loanPurposeId})\r\nand l.loan_status_id = 100 /*Submitted and awaiting approval */\r\norder by ounder.hierarchy, l.submittedon_date,  l.account_no','Individual Client Report',1,1,0);
INSERT INTO `stretchy_report` VALUES (11,'Active Loans - Summary','Table',NULL,'Loan','select concat(repeat(\"..\",   \r\n   ((LENGTH(mo.`hierarchy`) - LENGTH(REPLACE(mo.`hierarchy`, \'.\', \'\')) - 1))), mo.`name`) as \"Office/Branch\", x.currency as Currency,\r\n x.client_count as \"No. of Clients\", x.active_loan_count as \"No. Active Loans\", x. loans_in_arrears_count as \"No. of Loans in Arrears\",\r\nx.principal as \"Total Loans Disbursed\", x.principal_repaid as \"Principal Repaid\", x.principal_outstanding as \"Principal Outstanding\", x.principal_overdue as \"Principal Overdue\",\r\nx.interest as \"Total Interest\", x.interest_repaid as \"Interest Repaid\", x.interest_outstanding as \"Interest Outstanding\", x.interest_overdue as \"Interest Overdue\",\r\nx.fees as \"Total Fees\", x.fees_repaid as \"Fees Repaid\", x.fees_outstanding as \"Fees Outstanding\", x.fees_overdue as \"Fees Overdue\",\r\nx.penalties as \"Total Penalties\", x.penalties_repaid as \"Penalties Repaid\", x.penalties_outstanding as \"Penalties Outstanding\", x.penalties_overdue as \"Penalties Overdue\",\r\n\r\n	(case\r\n	when ${parType} = 1 then\r\n    cast(round((x.principal_overdue * 100) / x.principal_outstanding, 2) as char)\r\n	when ${parType} = 2 then\r\n    cast(round(((x.principal_overdue + x.interest_overdue) * 100) / (x.principal_outstanding + x.interest_outstanding), 2) as char)\r\n	when ${parType} = 3 then\r\n    cast(round(((x.principal_overdue + x.interest_overdue + x.fees_overdue) * 100) / (x.principal_outstanding + x.interest_outstanding + x.fees_outstanding), 2) as char)\r\n	when ${parType} = 4 then\r\n    cast(round(((x.principal_overdue + x.interest_overdue + x.fees_overdue + x.penalties_overdue) * 100) / (x.principal_outstanding + x.interest_outstanding + x.fees_outstanding + x.penalties_overdue), 2) as char)\r\n	else \"invalid PAR Type\"\r\n	end) as \"Portfolio at Risk %\"\r\n from m_office mo\r\njoin \r\n(select ounder.id as branch,\r\nifnull(cur.display_symbol, l.currency_code) as currency,\r\ncount(distinct(c.id)) as client_count, \r\ncount(distinct(l.id)) as  active_loan_count,\r\ncount(distinct(if(laa.loan_id is not null,  l.id, null)  )) as loans_in_arrears_count,\r\n\r\nsum(l.principal_disbursed_derived) as principal,\r\nsum(l.principal_repaid_derived) as principal_repaid,\r\nsum(l.principal_outstanding_derived) as principal_outstanding,\r\nsum(laa.principal_overdue_derived) as principal_overdue,\r\n\r\nsum(l.interest_charged_derived) as interest,\r\nsum(l.interest_repaid_derived) as interest_repaid,\r\nsum(l.interest_outstanding_derived) as interest_outstanding,\r\nsum(laa.interest_overdue_derived) as interest_overdue,\r\n\r\nsum(l.fee_charges_charged_derived) as fees,\r\nsum(l.fee_charges_repaid_derived) as fees_repaid,\r\nsum(l.fee_charges_outstanding_derived)  as fees_outstanding,\r\nsum(laa.fee_charges_overdue_derived) as fees_overdue,\r\n\r\nsum(l.penalty_charges_charged_derived) as penalties,\r\nsum(l.penalty_charges_repaid_derived) as penalties_repaid,\r\nsum(l.penalty_charges_outstanding_derived) as penalties_outstanding,\r\nsum(laa.penalty_charges_overdue_derived) as penalties_overdue\r\n\r\nfrom m_office o \r\njoin m_office ounder on ounder.hierarchy like concat(o.hierarchy, \'%\')\r\nand ounder.hierarchy like concat(\'${currentUserHierarchy}\', \'%\')\r\njoin m_client c on c.office_id = ounder.id\r\njoin m_loan l on l.client_id = c.id\r\nleft join m_loan_arrears_aging laa on laa.loan_id = l.id\r\nleft join m_currency cur on cur.code = l.currency_code\r\n\r\nwhere o.id = ${officeId}\r\nand (l.currency_code = \"${currencyId}\" or \"-1\" = \"${currencyId}\")\r\nand (l.product_id = \"${loanProductId}\" or \"-1\" = \"${loanProductId}\")\r\nand (ifnull(l.loan_officer_id, -10) = \"${loanOfficerId}\" or \"-1\" = \"${loanOfficerId}\")\r\nand (ifnull(l.fund_id, -10) = ${fundId} or -1 = ${fundId})\r\nand (ifnull(l.loanpurpose_cv_id, -10) = ${loanPurposeId} or -1 = ${loanPurposeId})\r\nand l.loan_status_id = 300\r\ngroup by ounder.id, l.currency_code) x on x.branch = mo.id\r\norder by mo.hierarchy, x.Currency',NULL,1,1,0);
INSERT INTO `stretchy_report` VALUES (12,'Active Loans - Details','Table',NULL,'Loan','select concat(repeat(\"..\",   \r\n   ((LENGTH(ounder.`hierarchy`) - LENGTH(REPLACE(ounder.`hierarchy`, \'.\', \'\')) - 1))), ounder.`name`) as \"Office/Branch\",\r\nifnull(cur.display_symbol, l.currency_code) as Currency,\r\nlo.display_name as \"Loan Officer\", \r\nc.display_name as \"Client\", l.account_no as \"Loan Account No.\", pl.`name` as \"Product\", \r\nf.`name` as Fund,  \r\nl.principal_amount as \"Loan Amount\", \r\nl.annual_nominal_interest_rate as \" Annual Nominal Interest Rate\", \r\ndate(l.disbursedon_date) as \"Disbursed Date\", \r\ndate(l.expected_maturedon_date) as \"Expected Matured On\",\r\n\r\nl.principal_repaid_derived as \"Principal Repaid\",\r\nl.principal_outstanding_derived as \"Principal Outstanding\",\r\nlaa.principal_overdue_derived as \"Principal Overdue\",\r\n\r\nl.interest_repaid_derived as \"Interest Repaid\",\r\nl.interest_outstanding_derived as \"Interest Outstanding\",\r\nlaa.interest_overdue_derived as \"Interest Overdue\",\r\n\r\nl.fee_charges_repaid_derived as \"Fees Repaid\",\r\nl.fee_charges_outstanding_derived  as \"Fees Outstanding\",\r\nlaa.fee_charges_overdue_derived as \"Fees Overdue\",\r\n\r\nl.penalty_charges_repaid_derived as \"Penalties Repaid\",\r\nl.penalty_charges_outstanding_derived as \"Penalties Outstanding\",\r\npenalty_charges_overdue_derived as \"Penalties Overdue\"\r\n\r\nfrom m_office o \r\njoin m_office ounder on ounder.hierarchy like concat(o.hierarchy, \'%\')\r\nand ounder.hierarchy like concat(\'${currentUserHierarchy}\', \'%\')\r\njoin m_client c on c.office_id = ounder.id\r\njoin m_loan l on l.client_id = c.id\r\njoin m_product_loan pl on pl.id = l.product_id\r\nleft join m_staff lo on lo.id = l.loan_officer_id\r\nleft join m_currency cur on cur.code = l.currency_code\r\nleft join m_fund f on f.id = l.fund_id\r\nleft join m_loan_arrears_aging laa on laa.loan_id = l.id\r\nwhere o.id = ${officeId}\r\nand (l.currency_code = \"${currencyId}\" or \"-1\" = \"${currencyId}\")\r\nand (l.product_id = \"${loanProductId}\" or \"-1\" = \"${loanProductId}\")\r\nand (ifnull(l.loan_officer_id, -10) = \"${loanOfficerId}\" or \"-1\" = \"${loanOfficerId}\")\r\nand (ifnull(l.fund_id, -10) = ${fundId} or -1 = ${fundId})\r\nand (ifnull(l.loanpurpose_cv_id, -10) = ${loanPurposeId} or -1 = ${loanPurposeId})\r\nand l.loan_status_id = 300\r\ngroup by l.id\r\norder by ounder.hierarchy, l.currency_code, c.account_no, l.account_no','Individual Client \n\nReport',1,1,0);
INSERT INTO `stretchy_report` VALUES (13,'Obligation Met Loans Details','Table',NULL,'Loan','select concat(repeat(\"..\",   \r\n   ((LENGTH(ounder.`hierarchy`) - LENGTH(REPLACE(ounder.`hierarchy`, \'.\', \'\')) - 1))), ounder.`name`) as \"Office/Branch\",\r\nifnull(cur.display_symbol, l.currency_code) as Currency,\r\nc.account_no as \"Client Account No.\", c.display_name as \"Client\",\r\nl.account_no as \"Loan Account No.\", pl.`name` as \"Product\", \r\nf.`name` as Fund,  \r\nl.principal_amount as \"Loan Amount\", \r\nl.total_repayment_derived  as \"Total Repaid\", \r\nl.annual_nominal_interest_rate as \" Annual Nominal Interest Rate\", \r\ndate(l.disbursedon_date) as \"Disbursed\", \r\ndate(l.closedon_date) as \"Closed\",\r\n\r\nl.principal_repaid_derived as \"Principal Repaid\",\r\nl.interest_repaid_derived as \"Interest Repaid\",\r\nl.fee_charges_repaid_derived as \"Fees Repaid\",\r\nl.penalty_charges_repaid_derived as \"Penalties Repaid\",\r\nlo.display_name as \"Loan Officer\"\r\n\r\nfrom m_office o \r\njoin m_office ounder on ounder.hierarchy like concat(o.hierarchy, \'%\')\r\nand ounder.hierarchy like concat(\'${currentUserHierarchy}\', \'%\')\r\njoin m_client c on c.office_id = ounder.id\r\njoin m_loan l on l.client_id = c.id\r\njoin m_product_loan pl on pl.id = l.product_id\r\nleft join m_staff lo on lo.id = l.loan_officer_id\r\nleft join m_currency cur on cur.code = l.currency_code\r\nleft join m_fund f on f.id = l.fund_id\r\nwhere o.id = ${officeId}\r\nand (l.currency_code = \"${currencyId}\" or \"-1\" = \"${currencyId}\")\r\nand (l.product_id = \"${loanProductId}\" or \"-1\" = \"${loanProductId}\")\r\nand (ifnull(l.loan_officer_id, -10) = \"${loanOfficerId}\" or \"-1\" = \"${loanOfficerId}\")\r\nand (ifnull(l.fund_id, -10) = ${fundId} or -1 = ${fundId})\r\nand (ifnull(l.loanpurpose_cv_id, -10) = ${loanPurposeId} or -1 = ${loanPurposeId})\r\nand (case\r\n	when ${obligDateType} = 1 then\r\n    l.closedon_date between \'${startDate}\' and \'${endDate}\'\r\n	when ${obligDateType} = 2 then\r\n    l.disbursedon_date between \'${startDate}\' and \'${endDate}\'\r\n	else 1 = 1\r\n	end)\r\nand l.loan_status_id = 600\r\ngroup by l.id\r\norder by ounder.hierarchy, l.currency_code, c.account_no, l.account_no','Individual Client \n\nReport',1,1,0);
INSERT INTO `stretchy_report` VALUES (14,'Obligation Met Loans Summary','Table',NULL,'Loan','select concat(repeat(\"..\",   \r\n   ((LENGTH(ounder.`hierarchy`) - LENGTH(REPLACE(ounder.`hierarchy`, \'.\', \'\')) - 1))), ounder.`name`) as \"Office/Branch\",\r\nifnull(cur.display_symbol, l.currency_code) as Currency,\r\ncount(distinct(c.id)) as \"No. of Clients\",\r\ncount(distinct(l.id)) as \"No. of Loans\",\r\nsum(l.principal_amount) as \"Total Loan Amount\", \r\nsum(l.principal_repaid_derived) as \"Total Principal Repaid\",\r\nsum(l.interest_repaid_derived) as \"Total Interest Repaid\",\r\nsum(l.fee_charges_repaid_derived) as \"Total Fees Repaid\",\r\nsum(l.penalty_charges_repaid_derived) as \"Total Penalties Repaid\",\r\nsum(l.interest_waived_derived) as \"Total Interest Waived\",\r\nsum(l.fee_charges_waived_derived) as \"Total Fees Waived\",\r\nsum(l.penalty_charges_waived_derived) as \"Total Penalties Waived\"\r\n\r\nfrom m_office o \r\njoin m_office ounder on ounder.hierarchy like concat(o.hierarchy, \'%\')\r\nand ounder.hierarchy like concat(\'${currentUserHierarchy}\', \'%\')\r\njoin m_client c on c.office_id = ounder.id\r\njoin m_loan l on l.client_id = c.id\r\njoin m_product_loan pl on pl.id = l.product_id\r\nleft join m_staff lo on lo.id = l.loan_officer_id\r\nleft join m_currency cur on cur.code = l.currency_code\r\nleft join m_fund f on f.id = l.fund_id\r\nwhere o.id = ${officeId}\r\nand (l.currency_code = \"${currencyId}\" or \"-1\" = \"${currencyId}\")\r\nand (l.product_id = \"${loanProductId}\" or \"-1\" = \"${loanProductId}\")\r\nand (ifnull(l.loan_officer_id, -10) = \"${loanOfficerId}\" or \"-1\" = \"${loanOfficerId}\")\r\nand (ifnull(l.fund_id, -10) = ${fundId} or -1 = ${fundId})\r\nand (ifnull(l.loanpurpose_cv_id, -10) = ${loanPurposeId} or -1 = ${loanPurposeId})\r\nand (case\r\n	when ${obligDateType} = 1 then\r\n    l.closedon_date between \'${startDate}\' and \'${endDate}\'\r\n	when ${obligDateType} = 2 then\r\n    l.disbursedon_date between \'${startDate}\' and \'${endDate}\'\r\n	else 1 = 1\r\n	end)\r\nand l.loan_status_id = 600\r\ngroup by ounder.hierarchy, l.currency_code\r\norder by ounder.hierarchy, l.currency_code','Individual Client \n\nReport',1,1,0);
INSERT INTO `stretchy_report` VALUES (15,'Portfolio at Risk','Table',NULL,'Loan','select x.Currency, x.`Principal Outstanding`, x.`Principal Overdue`, x.`Interest Outstanding`, x.`Interest Overdue`, \r\nx.`Fees Outstanding`, x.`Fees Overdue`, x.`Penalties Outstanding`, x.`Penalties Overdue`,\r\n\r\n	(case\r\n	when ${parType} = 1 then\r\n    cast(round((x.`Principal Overdue` * 100) / x.`Principal Outstanding`, 2) as char)\r\n	when ${parType} = 2 then\r\n    cast(round(((x.`Principal Overdue` + x.`Interest Overdue`) * 100) / (x.`Principal Outstanding` + x.`Interest Outstanding`), 2) as char)\r\n	when ${parType} = 3 then\r\n    cast(round(((x.`Principal Overdue` + x.`Interest Overdue` + x.`Fees Overdue`) * 100) / (x.`Principal Outstanding` + x.`Interest Outstanding` + x.`Fees Outstanding`), 2) as char)\r\n	when ${parType} = 4 then\r\n    cast(round(((x.`Principal Overdue` + x.`Interest Overdue` + x.`Fees Overdue` + x.`Penalties Overdue`) * 100) / (x.`Principal Outstanding` + x.`Interest Outstanding` + x.`Fees Outstanding` + x.`Penalties Overdue`), 2) as char)\r\n	else \"invalid PAR Type\"\r\n	end) as \"Portfolio at Risk %\"\r\n from \r\n(select  ifnull(cur.display_symbol, l.currency_code) as Currency,  \r\nsum(l.principal_outstanding_derived) as \"Principal Outstanding\",\r\nsum(laa.principal_overdue_derived) as \"Principal Overdue\",\r\n\r\nsum(l.interest_outstanding_derived) as \"Interest Outstanding\",\r\nsum(laa.interest_overdue_derived) as \"Interest Overdue\",\r\n\r\nsum(l.fee_charges_outstanding_derived)  as \"Fees Outstanding\",\r\nsum(laa.fee_charges_overdue_derived) as \"Fees Overdue\",\r\n\r\nsum(penalty_charges_outstanding_derived) as \"Penalties Outstanding\",\r\nsum(laa.penalty_charges_overdue_derived) as \"Penalties Overdue\"\r\n\r\nfrom m_office o \r\njoin m_office ounder on ounder.hierarchy like concat(o.hierarchy, \'%\')\r\nand ounder.hierarchy like concat(\'${currentUserHierarchy}\', \'%\')\r\njoin m_client c on c.office_id = ounder.id\r\njoin  m_loan l on l.client_id = c.id\r\nleft join m_staff lo on lo.id = l.loan_officer_id\r\nleft join m_currency cur on cur.code = l.currency_code\r\nleft join m_fund f on f.id = l.fund_id\r\nleft join m_code_value purp on purp.id = l.loanpurpose_cv_id\r\nleft join m_product_loan p on p.id = l.product_id\r\nleft join m_loan_arrears_aging laa on laa.loan_id = l.id\r\nwhere o.id = ${officeId}\r\nand (l.currency_code = \"${currencyId}\" or \"-1\" = \"${currencyId}\")\r\nand (l.product_id = \"${loanProductId}\" or \"-1\" = \"${loanProductId}\")\r\nand (ifnull(l.loan_officer_id, -10) = \"${loanOfficerId}\" or \"-1\" = \"${loanOfficerId}\")\r\nand (ifnull(l.fund_id, -10) = ${fundId} or -1 = ${fundId})\r\nand (ifnull(l.loanpurpose_cv_id, -10) = ${loanPurposeId} or -1 = ${loanPurposeId})\r\nand l.loan_status_id = 300\r\ngroup by l.currency_code\r\norder by l.currency_code) x','Covers all loans.\r\n\r\nFor larger MFIs … we should add some derived fields on loan (or a 1:1 loan related table like mifos 2.x does)\r\nPrinciple, Interest, Fees, Penalties Outstanding and Overdue (possibly waived and written off too)',1,1,0);
INSERT INTO `stretchy_report` VALUES (16,'Portfolio at Risk by Branch','Table',NULL,'Loan','select concat(repeat(\"..\",   \r\n   ((LENGTH(mo.`hierarchy`) - LENGTH(REPLACE(mo.`hierarchy`, \'.\', \'\')) - 1))), mo.`name`) as \"Office/Branch\",\r\nx.Currency, x.`Principal Outstanding`, x.`Principal Overdue`, x.`Interest Outstanding`, x.`Interest Overdue`, \r\nx.`Fees Outstanding`, x.`Fees Overdue`, x.`Penalties Outstanding`, x.`Penalties Overdue`,\r\n\r\n	(case\r\n	when ${parType} = 1 then\r\n    cast(round((x.`Principal Overdue` * 100) / x.`Principal Outstanding`, 2) as char)\r\n	when ${parType} = 2 then\r\n    cast(round(((x.`Principal Overdue` + x.`Interest Overdue`) * 100) / (x.`Principal Outstanding` + x.`Interest Outstanding`), 2) as char)\r\n	when ${parType} = 3 then\r\n    cast(round(((x.`Principal Overdue` + x.`Interest Overdue` + x.`Fees Overdue`) * 100) / (x.`Principal Outstanding` + x.`Interest Outstanding` + x.`Fees Outstanding`), 2) as char)\r\n	when ${parType} = 4 then\r\n    cast(round(((x.`Principal Overdue` + x.`Interest Overdue` + x.`Fees Overdue` + x.`Penalties Overdue`) * 100) / (x.`Principal Outstanding` + x.`Interest Outstanding` + x.`Fees Outstanding` + x.`Penalties Overdue`), 2) as char)\r\n	else \"invalid PAR Type\"\r\n	end) as \"Portfolio at Risk %\"\r\n from m_office mo\r\njoin \r\n(select  ounder.id as \"branch\", ifnull(cur.display_symbol, l.currency_code) as Currency,  \r\n\r\nsum(l.principal_outstanding_derived) as \"Principal Outstanding\",\r\nsum(laa.principal_overdue_derived) as \"Principal Overdue\",\r\n\r\nsum(l.interest_outstanding_derived) as \"Interest Outstanding\",\r\nsum(laa.interest_overdue_derived) as \"Interest Overdue\",\r\n\r\nsum(l.fee_charges_outstanding_derived)  as \"Fees Outstanding\",\r\nsum(laa.fee_charges_overdue_derived) as \"Fees Overdue\",\r\n\r\nsum(penalty_charges_outstanding_derived) as \"Penalties Outstanding\",\r\nsum(laa.penalty_charges_overdue_derived) as \"Penalties Overdue\"\r\n\r\nfrom m_office o \r\njoin m_office ounder on ounder.hierarchy like concat(o.hierarchy, \'%\')\r\nand ounder.hierarchy like concat(\'${currentUserHierarchy}\', \'%\')\r\njoin m_client c on c.office_id = ounder.id\r\njoin  m_loan l on l.client_id = c.id\r\nleft join m_staff lo on lo.id = l.loan_officer_id\r\nleft join m_currency cur on cur.code = l.currency_code\r\nleft join m_fund f on f.id = l.fund_id\r\nleft join m_code_value purp on purp.id = l.loanpurpose_cv_id\r\nleft join m_product_loan p on p.id = l.product_id\r\nleft join m_loan_arrears_aging laa on laa.loan_id = l.id\r\nwhere o.id = ${officeId}\r\nand (l.currency_code = \"${currencyId}\" or \"-1\" = \"${currencyId}\")\r\nand (l.product_id = \"${loanProductId}\" or \"-1\" = \"${loanProductId}\")\r\nand (ifnull(l.loan_officer_id, -10) = \"${loanOfficerId}\" or \"-1\" = \"${loanOfficerId}\")\r\nand (ifnull(l.fund_id, -10) = ${fundId} or -1 = ${fundId})\r\nand (ifnull(l.loanpurpose_cv_id, -10) = ${loanPurposeId} or -1 = ${loanPurposeId})\r\nand l.loan_status_id = 300\r\ngroup by ounder.id, l.currency_code) x on x.branch = mo.id\r\norder by mo.hierarchy, x.Currency','Covers all loans.\r\n\r\nFor larger MFIs … we should add some derived fields on loan (or a 1:1 loan related table like mifos 2.x does)\r\nPrinciple, Interest, Fees, Penalties Outstanding and Overdue (possibly waived and written off too)',1,1,0);
INSERT INTO `stretchy_report` VALUES (20,'Funds Disbursed Between Dates Summary','Table',NULL,'Fund','select ifnull(f.`name`, \'-\') as Fund,  ifnull(cur.display_symbol, l.currency_code) as Currency, \r\nround(sum(l.principal_amount), 4) as disbursed_amount\r\nfrom m_office ounder \r\njoin m_client c on c.office_id = ounder.id\r\njoin m_loan l on l.client_id = c.id\r\njoin m_currency cur on cur.`code` = l.currency_code\r\nleft join m_fund f on f.id = l.fund_id\r\nwhere disbursedon_date between \'${startDate}\' and \'${endDate}\'\r\nand (ifnull(l.fund_id, -10) = ${fundId} or -1 = ${fundId})\r\nand (l.currency_code = \'${currencyId}\' or \'-1\' = \'${currencyId}\')\r\nand ounder.hierarchy like concat(\'${currentUserHierarchy}\', \'%\')\r\ngroup by ifnull(f.`name`, \'-\') , ifnull(cur.display_symbol, l.currency_code)\r\norder by ifnull(f.`name`, \'-\') , ifnull(cur.display_symbol, l.currency_code)',NULL,1,1,0);
INSERT INTO `stretchy_report` VALUES (21,'Funds Disbursed Between Dates Summary by Office','Table',NULL,'Fund','select \r\nconcat(repeat(\"..\",   \r\n   ((LENGTH(ounder.`hierarchy`) - LENGTH(REPLACE(ounder.`hierarchy`, \'.\', \'\')) - 1))), ounder.`name`) as \"Office/Branch\",\r\n \n\nifnull(f.`name`, \'-\') as Fund,  ifnull(cur.display_symbol, l.currency_code) as Currency, round(sum(l.principal_amount), 4) as disbursed_amount\r\nfrom m_office o\r\n\n\njoin m_office ounder on ounder.hierarchy like concat(o.hierarchy, \'%\')\r\nand ounder.hierarchy like concat(\'${currentUserHierarchy}\', \'%\')\r\njoin m_client c \n\non c.office_id = ounder.id\r\njoin m_loan l on l.client_id = c.id\r\njoin m_currency cur on cur.`code` = l.currency_code\r\nleft join m_fund f on f.id = l.fund_id\r\n\n\nwhere disbursedon_date between \'${startDate}\' and \'${endDate}\'\r\nand o.id = ${officeId}\r\nand (ifnull(l.fund_id, -10) = ${fundId} or -1 = ${fundId})\r\nand \n\n(l.currency_code = \'${currencyId}\' or \'-1\' = \'${currencyId}\')\r\ngroup by ounder.`name`,  ifnull(f.`name`, \'-\') , ifnull(cur.display_symbol, \n\nl.currency_code)\r\norder by ounder.`name`,  ifnull(f.`name`, \'-\') , ifnull(cur.display_symbol, l.currency_code)',NULL,1,1,0);
INSERT INTO `stretchy_report` VALUES (51,'Written-Off Loans','Table',NULL,'Loan','SELECT \r\nconcat(repeat(\"..\",   \r\n   ((LENGTH(ounder.`hierarchy`) - LENGTH(REPLACE(ounder.`hierarchy`, \'.\', \'\')) - 1))), ounder.`name`) as \"Office/Branch\",\r\nifnull(cur.display_symbol, ml.currency_code) as Currency,  \r\nc.account_no as \"Client Account No.\",\r\nc.display_name AS \'Client Name\',\r\nml.account_no AS \'Loan Account No.\',\r\nmpl.name AS \'Product Name\',\r\nml.disbursedon_date AS \'Disbursed Date\',\r\nlt.transaction_date AS \'Written Off date\',\r\nml.principal_amount as \"Loan Amount\",\r\nifnull(lt.principal_portion_derived, 0) AS \'Written-Off Principal\',\r\nifnull(lt.interest_portion_derived, 0) AS \'Written-Off Interest\',\r\nifnull(lt.fee_charges_portion_derived,0) AS \'Written-Off Fees\',\r\nifnull(lt.penalty_charges_portion_derived,0) AS \'Written-Off Penalties\',\r\nn.note AS \'Reason For Write-Off\',\r\nIFNULL(ms.display_name,\'-\') AS \'Loan Officer Name\'\r\nFROM m_office o\r\nJOIN m_office ounder ON ounder.hierarchy like concat(o.hierarchy, \'%\')\r\nAND ounder.hierarchy like CONCAT(\'${currentUserHierarchy}\', \'%\')\r\nJOIN m_client c ON c.office_id = ounder.id\r\nJOIN m_loan ml ON ml.client_id = c.id\r\nJOIN m_product_loan mpl ON mpl.id=ml.product_id\r\nLEFT JOIN m_staff ms ON ms.id=ml.loan_officer_id\r\nJOIN m_loan_transaction lt ON lt.loan_id = ml.id\r\nLEFT JOIN m_note n ON n.loan_transaction_id = lt.id\r\nLEFT JOIN m_currency cur on cur.code = ml.currency_code\r\nWHERE lt.transaction_type_enum = 6 /*write-off */\r\nAND lt.is_reversed is false \r\nAND ml.loan_status_id=601\r\nAND o.id=${officeId}\r\nAND (mpl.id=${loanProductId} OR ${loanProductId}=-1)\r\nAND lt.transaction_date BETWEEN \'${startDate}\' AND \'${endDate}\'\r\nAND (ml.currency_code = \"${currencyId}\" or \"-1\" = \"${currencyId}\") \r\nORDER BY ounder.hierarchy, ifnull(cur.display_symbol, ml.currency_code), ml.account_no','Individual Lending Report. Written Off Loans',1,1,0);
INSERT INTO `stretchy_report` VALUES (52,'Aging Detail','Table',NULL,'Loan','\r\nSELECT \r\nconcat(repeat(\"..\",   \r\n   ((LENGTH(ounder.`hierarchy`) - LENGTH(REPLACE(ounder.`hierarchy`, \'.\', \'\')) - 1))), ounder.`name`) as \"Office/Branch\",\r\nifnull(cur.display_symbol, ml.currency_code) as Currency,  \r\nmc.account_no as \"Client Account No.\",\r\n 	mc.display_name AS \"Client Name\",\r\n 	ml.account_no AS \"Account Number\",\r\n 	ml.principal_amount AS \"Loan Amount\",\r\n ml.principal_disbursed_derived AS \"Original Principal\",\r\n ml.interest_charged_derived AS \"Original Interest\",\r\n ml.principal_repaid_derived AS \"Principal Paid\",\r\n ml.interest_repaid_derived AS \"Interest Paid\",\r\n laa.principal_overdue_derived AS \"Principal Overdue\",\r\n laa.interest_overdue_derived AS \"Interest Overdue\",\r\nDATEDIFF(CURDATE(), laa.overdue_since_date_derived) as \"Days in Arrears\",\r\n\r\n 	IF(DATEDIFF(CURDATE(), laa.overdue_since_date_derived)<7, \'<1\', \r\n 	IF(DATEDIFF(CURDATE(), laa.overdue_since_date_derived)<8, \' 1\', \r\n 	IF(DATEDIFF(CURDATE(), laa.overdue_since_date_derived)<15,  \'2\', \r\n 	IF(DATEDIFF(CURDATE(), laa.overdue_since_date_derived)<22, \' 3\', \r\n 	IF(DATEDIFF(CURDATE(), laa.overdue_since_date_derived)<29, \' 4\', \r\n 	IF(DATEDIFF(CURDATE(), laa.overdue_since_date_derived)<36, \' 5\', \r\n 	IF(DATEDIFF(CURDATE(), laa.overdue_since_date_derived)<43, \' 6\', \r\n 	IF(DATEDIFF(CURDATE(), laa.overdue_since_date_derived)<50, \' 7\', \r\n 	IF(DATEDIFF(CURDATE(), laa.overdue_since_date_derived)<57, \' 8\', \r\n 	IF(DATEDIFF(CURDATE(), laa.overdue_since_date_derived)<64, \' 9\', \r\n 	IF(DATEDIFF(CURDATE(), laa.overdue_since_date_derived)<71, \'10\', \r\n 	IF(DATEDIFF(CURDATE(), laa.overdue_since_date_derived)<78, \'11\', \r\n 	IF(DATEDIFF(CURDATE(), laa.overdue_since_date_derived)<85, \'12\', \'12+\')))))))))))) )AS \"Weeks In Arrears Band\",\r\n\r\n		IF(DATEDIFF(CURDATE(),  laa.overdue_since_date_derived)<31, \'0 - 30\', \r\n		IF(DATEDIFF(CURDATE(),  laa.overdue_since_date_derived)<61, \'30 - 60\', \r\n		IF(DATEDIFF(CURDATE(),  laa.overdue_since_date_derived)<91, \'60 - 90\', \r\n		IF(DATEDIFF(CURDATE(),  laa.overdue_since_date_derived)<181, \'90 - 180\', \r\n		IF(DATEDIFF(CURDATE(),  laa.overdue_since_date_derived)<361, \'180 - 360\', \r\n				 \'> 360\'))))) AS \"Days in Arrears Band\"\r\n\r\n	FROM m_office mo \r\n    JOIN m_office ounder ON ounder.hierarchy like concat(mo.hierarchy, \'%\')\r\n	        AND ounder.hierarchy like CONCAT(\'${currentUserHierarchy}\', \'%\')\r\n    INNER JOIN m_client mc ON mc.office_id=ounder.id\r\n	    INNER JOIN m_loan ml ON ml.client_id = mc.id\r\n	    INNER JOIN r_enum_value rev ON rev.enum_id=ml.loan_status_id AND rev.enum_name = \'loan_status_id\'\r\n    INNER JOIN m_loan_arrears_aging laa ON laa.loan_id=ml.id\r\n    left join m_currency cur on cur.code = ml.currency_code\r\n	WHERE ml.loan_status_id=300\r\n    AND mo.id=${officeId}\r\nORDER BY ounder.hierarchy, ifnull(cur.display_symbol, ml.currency_code), ml.account_no\r\n','Loan arrears aging (Weeks)',1,1,0);
INSERT INTO `stretchy_report` VALUES (53,'Aging Summary (Arrears in Weeks)','Table',NULL,'Loan','SELECT \r\n  IFNULL(periods.currencyName, periods.currency) as currency, \r\n  periods.period_no \'Weeks In Arrears (Up To)\', \r\n  IFNULL(ars.loanId, 0) \'No Of Loans\', \r\n  IFNULL(ars.principal,0.0) \'Original Principal\', \r\n  IFNULL(ars.interest,0.0) \'Original Interest\', \r\n  IFNULL(ars.prinPaid,0.0) \'Principal Paid\', \r\n  IFNULL(ars.intPaid,0.0) \'Interest Paid\', \r\n  IFNULL(ars.prinOverdue,0.0) \'Principal Overdue\', \r\n  IFNULL(ars.intOverdue,0.0)\'Interest Overdue\'\r\nFROM \r\n	/* full table of aging periods/currencies used combo to ensure each line represented */\r\n  (SELECT curs.code as currency, curs.name as currencyName, pers.* from\r\n	(SELECT \'On Schedule\' period_no,1 pid UNION\r\n		SELECT \'1\',2 UNION\r\n		SELECT \'2\',3 UNION\r\n		SELECT \'3\',4 UNION\r\n		SELECT \'4\',5 UNION\r\n		SELECT \'5\',6 UNION\r\n		SELECT \'6\',7 UNION\r\n		SELECT \'7\',8 UNION\r\n		SELECT \'8\',9 UNION\r\n		SELECT \'9\',10 UNION\r\n		SELECT \'10\',11 UNION\r\n		SELECT \'11\',12 UNION\r\n		SELECT \'12\',13 UNION\r\n		SELECT \'12+\',14) pers,\r\n	(SELECT distinctrow moc.code, moc.name\r\n  	FROM m_office mo2\r\n   	INNER JOIN m_office ounder2 ON ounder2.hierarchy \r\n				LIKE CONCAT(mo2.hierarchy, \'%\')\r\nAND ounder2.hierarchy like CONCAT(\'${currentUserHierarchy}\', \'%\')\r\n   	INNER JOIN m_client mc2 ON mc2.office_id=ounder2.id\r\n   	INNER JOIN m_loan ml2 ON ml2.client_id = mc2.id\r\n	INNER JOIN m_organisation_currency moc ON moc.code = ml2.currency_code\r\n	WHERE ml2.loan_status_id=300 /* active */\r\n	AND mo2.id=${officeId}\r\nAND (ml2.currency_code = \"${currencyId}\" or \"-1\" = \"${currencyId}\")) curs) periods\r\n\r\n\r\nLEFT JOIN /* table of aging periods per currency with gaps if no applicable loans */\r\n(SELECT \r\n  	z.currency, z.arrPeriod, \r\n	COUNT(z.loanId) as loanId, SUM(z.principal) as principal, SUM(z.interest) as interest, \r\n	SUM(z.prinPaid) as prinPaid, SUM(z.intPaid) as intPaid, \r\n	SUM(z.prinOverdue) as prinOverdue, SUM(z.intOverdue) as intOverdue\r\nFROM\r\n	/*derived table just used to get arrPeriod value (was much slower to\r\n	duplicate calc of minOverdueDate in inner query)\r\nmight not be now with derived fields but didn’t check */\r\n	(SELECT x.loanId, x.currency, x.principal, x.interest, x.prinPaid, x.intPaid, x.prinOverdue, x.intOverdue,\r\n		IF(DATEDIFF(CURDATE(), minOverdueDate)<1, \'On Schedule\', \r\n		IF(DATEDIFF(CURDATE(), minOverdueDate)<8, \'1\', \r\n		IF(DATEDIFF(CURDATE(), minOverdueDate)<15, \'2\', \r\n		IF(DATEDIFF(CURDATE(), minOverdueDate)<22, \'3\', \r\n		IF(DATEDIFF(CURDATE(), minOverdueDate)<29, \'4\', \r\n		IF(DATEDIFF(CURDATE(), minOverdueDate)<36, \'5\', \r\n		IF(DATEDIFF(CURDATE(), minOverdueDate)<43, \'6\', \r\n		IF(DATEDIFF(CURDATE(), minOverdueDate)<50, \'7\', \r\n		IF(DATEDIFF(CURDATE(), minOverdueDate)<57, \'8\', \r\n		IF(DATEDIFF(CURDATE(), minOverdueDate)<64, \'9\', \r\n		IF(DATEDIFF(CURDATE(), minOverdueDate)<71, \'10\', \r\n		IF(DATEDIFF(CURDATE(), minOverdueDate)<78, \'11\', \r\n		IF(DATEDIFF(CURDATE(), minOverdueDate)<85, \'12\',\r\n				 \'12+\'))))))))))))) AS arrPeriod\r\n\r\n	FROM /* get the individual loan details */\r\n		(SELECT ml.id AS loanId, ml.currency_code as currency,\r\n   			ml.principal_disbursed_derived as principal, \r\n			   ml.interest_charged_derived as interest, \r\n   			ml.principal_repaid_derived as prinPaid, \r\n			   ml.interest_repaid_derived intPaid,\r\n\r\n			   laa.principal_overdue_derived as prinOverdue,\r\n			   laa.interest_overdue_derived as intOverdue,\r\n\r\n			   IFNULL(laa.overdue_since_date_derived, curdate()) as minOverdueDate\r\n			  \r\n  		FROM m_office mo\r\n   		INNER JOIN m_office ounder ON ounder.hierarchy \r\n				LIKE CONCAT(mo.hierarchy, \'%\')\r\nAND ounder.hierarchy like CONCAT(\'${currentUserHierarchy}\', \'%\')\r\n   		INNER JOIN m_client mc ON mc.office_id=ounder.id\r\n   		INNER JOIN m_loan ml ON ml.client_id = mc.id\r\n		   LEFT JOIN m_loan_arrears_aging laa on laa.loan_id = ml.id\r\n		WHERE ml.loan_status_id=300 /* active */\r\n     		AND mo.id=${officeId}\r\n     AND (ml.currency_code = \"${currencyId}\" or \"-1\" = \"${currencyId}\")\r\n  		GROUP BY ml.id) x\r\n	) z \r\nGROUP BY z.currency, z.arrPeriod ) ars ON ars.arrPeriod=periods.period_no and ars.currency = periods.currency\r\nORDER BY periods.currency, periods.pid','Loan amount in arrears by branch',1,1,0);
INSERT INTO `stretchy_report` VALUES (54,'Rescheduled Loans','Table',NULL,'Loan','SELECT \r\nconcat(repeat(\"..\",   \r\n   ((LENGTH(ounder.`hierarchy`) - LENGTH(REPLACE(ounder.`hierarchy`, \'.\', \'\')) - 1))), ounder.`name`) as \"Office/Branch\",\r\nifnull(cur.display_symbol, ml.currency_code) as Currency,  \r\nc.account_no as \"Client Account No.\",\r\nc.display_name AS \'Client Name\',\r\nml.account_no AS \'Loan Account No.\',\r\nmpl.name AS \'Product Name\',\r\nml.disbursedon_date AS \'Disbursed Date\',\r\nlt.transaction_date AS \'Written Off date\',\r\nml.principal_amount as \"Loan Amount\",\r\nifnull(lt.principal_portion_derived, 0) AS \'Rescheduled Principal\',\r\nifnull(lt.interest_portion_derived, 0) AS \'Rescheduled Interest\',\r\nifnull(lt.fee_charges_portion_derived,0) AS \'Rescheduled Fees\',\r\nifnull(lt.penalty_charges_portion_derived,0) AS \'Rescheduled Penalties\',\r\nn.note AS \'Reason For Rescheduling\',\r\nIFNULL(ms.display_name,\'-\') AS \'Loan Officer Name\'\r\nFROM m_office o\r\nJOIN m_office ounder ON ounder.hierarchy like concat(o.hierarchy, \'%\')\r\nAND ounder.hierarchy like CONCAT(\'${currentUserHierarchy}\', \'%\')\r\nJOIN m_client c ON c.office_id = ounder.id\r\nJOIN m_loan ml ON ml.client_id = c.id\r\nJOIN m_product_loan mpl ON mpl.id=ml.product_id\r\nLEFT JOIN m_staff ms ON ms.id=ml.loan_officer_id\r\nJOIN m_loan_transaction lt ON lt.loan_id = ml.id\r\nLEFT JOIN m_note n ON n.loan_transaction_id = lt.id\r\nLEFT JOIN m_currency cur on cur.code = ml.currency_code\r\nWHERE lt.transaction_type_enum = 7 /*marked for rescheduling */\r\nAND lt.is_reversed is false \r\nAND ml.loan_status_id=602\r\nAND o.id=${officeId}\r\nAND (mpl.id=${loanProductId} OR ${loanProductId}=-1)\r\nAND lt.transaction_date BETWEEN \'${startDate}\' AND \'${endDate}\'\r\nAND (ml.currency_code = \"${currencyId}\" or \"-1\" = \"${currencyId}\")\r\nORDER BY ounder.hierarchy, ifnull(cur.display_symbol, ml.currency_code), ml.account_no','Individual Lending Report. Rescheduled Loans.  The ability to reschedule (or mark that you have rescheduled the loan elsewhere) is a legacy of the older Mifos product.  Needed for migration.',1,1,0);
INSERT INTO `stretchy_report` VALUES (55,'Active Loans Passed Final Maturity','Table',NULL,'Loan','select concat(repeat(\"..\",   \r\n   ((LENGTH(ounder.`hierarchy`) - LENGTH(REPLACE(ounder.`hierarchy`, \'.\', \'\')) - 1))), ounder.`name`) as \"Office/Branch\",\r\nifnull(cur.display_symbol, l.currency_code) as Currency,\r\nlo.display_name as \"Loan Officer\", \r\nc.display_name as \"Client\", l.account_no as \"Loan Account No.\", pl.`name` as \"Product\", \r\nf.`name` as Fund,  \r\nl.principal_amount as \"Loan Amount\", \r\nl.annual_nominal_interest_rate as \" Annual Nominal Interest Rate\", \r\ndate(l.disbursedon_date) as \"Disbursed Date\", \r\ndate(l.expected_maturedon_date) as \"Expected Matured On\",\r\n\r\nl.principal_repaid_derived as \"Principal Repaid\",\r\nl.principal_outstanding_derived as \"Principal Outstanding\",\r\nlaa.principal_overdue_derived as \"Principal Overdue\",\r\n\r\nl.interest_repaid_derived as \"Interest Repaid\",\r\nl.interest_outstanding_derived as \"Interest Outstanding\",\r\nlaa.interest_overdue_derived as \"Interest Overdue\",\r\n\r\nl.fee_charges_repaid_derived as \"Fees Repaid\",\r\nl.fee_charges_outstanding_derived  as \"Fees Outstanding\",\r\nlaa.fee_charges_overdue_derived as \"Fees Overdue\",\r\n\r\nl.penalty_charges_repaid_derived as \"Penalties Repaid\",\r\nl.penalty_charges_outstanding_derived as \"Penalties Outstanding\",\r\nlaa.penalty_charges_overdue_derived as \"Penalties Overdue\"\r\n\r\nfrom m_office o \r\njoin m_office ounder on ounder.hierarchy like concat(o.hierarchy, \'%\')\r\nand ounder.hierarchy like concat(\'${currentUserHierarchy}\', \'%\')\r\njoin m_client c on c.office_id = ounder.id\r\njoin m_loan l on l.client_id = c.id\r\njoin m_product_loan pl on pl.id = l.product_id\r\nleft join m_staff lo on lo.id = l.loan_officer_id\r\nleft join m_currency cur on cur.code = l.currency_code\r\nleft join m_fund f on f.id = l.fund_id\r\nleft join m_loan_arrears_aging laa on laa.loan_id = l.id\r\nwhere o.id = ${officeId}\r\nand (l.currency_code = \"${currencyId}\" or \"-1\" = \"${currencyId}\")\r\nand (l.product_id = \"${loanProductId}\" or \"-1\" = \"${loanProductId}\")\r\nand (ifnull(l.loan_officer_id, -10) = \"${loanOfficerId}\" or \"-1\" = \"${loanOfficerId}\")\r\nand (ifnull(l.fund_id, -10) = ${fundId} or -1 = ${fundId})\r\nand (ifnull(l.loanpurpose_cv_id, -10) = ${loanPurposeId} or -1 = ${loanPurposeId})\r\nand l.loan_status_id = 300\r\nand l.expected_maturedon_date < curdate()\r\ngroup by l.id\r\norder by ounder.hierarchy, l.currency_code, c.account_no, l.account_no','Individual Client \n\nReport',1,1,0);
INSERT INTO `stretchy_report` VALUES (56,'Active Loans Passed Final Maturity Summary','Table',NULL,'Loan','select concat(repeat(\"..\",   \r\n   ((LENGTH(mo.`hierarchy`) - LENGTH(REPLACE(mo.`hierarchy`, \'.\', \'\')) - 1))), mo.`name`) as \"Office/Branch\", x.currency as Currency,\r\n x.client_count as \"No. of Clients\", x.active_loan_count as \"No. Active Loans\", x. arrears_loan_count as \"No. of Loans in Arrears\",\r\nx.principal as \"Total Loans Disbursed\", x.principal_repaid as \"Principal Repaid\", x.principal_outstanding as \"Principal Outstanding\", x.principal_overdue as \"Principal Overdue\",\r\nx.interest as \"Total Interest\", x.interest_repaid as \"Interest Repaid\", x.interest_outstanding as \"Interest Outstanding\", x.interest_overdue as \"Interest Overdue\",\r\nx.fees as \"Total Fees\", x.fees_repaid as \"Fees Repaid\", x.fees_outstanding as \"Fees Outstanding\", x.fees_overdue as \"Fees Overdue\",\r\nx.penalties as \"Total Penalties\", x.penalties_repaid as \"Penalties Repaid\", x.penalties_outstanding as \"Penalties Outstanding\", x.penalties_overdue as \"Penalties Overdue\",\r\n\r\n	(case\r\n	when ${parType} = 1 then\r\n    cast(round((x.principal_overdue * 100) / x.principal_outstanding, 2) as char)\r\n	when ${parType} = 2 then\r\n    cast(round(((x.principal_overdue + x.interest_overdue) * 100) / (x.principal_outstanding + x.interest_outstanding), 2) as char)\r\n	when ${parType} = 3 then\r\n    cast(round(((x.principal_overdue + x.interest_overdue + x.fees_overdue) * 100) / (x.principal_outstanding + x.interest_outstanding + x.fees_outstanding), 2) as char)\r\n	when ${parType} = 4 then\r\n    cast(round(((x.principal_overdue + x.interest_overdue + x.fees_overdue + x.penalties_overdue) * 100) / (x.principal_outstanding + x.interest_outstanding + x.fees_outstanding + x.penalties_overdue), 2) as char)\r\n	else \"invalid PAR Type\"\r\n	end) as \"Portfolio at Risk %\"\r\n from m_office mo\r\njoin \r\n(select ounder.id as branch,\r\nifnull(cur.display_symbol, l.currency_code) as currency,\r\ncount(distinct(c.id)) as client_count, \r\ncount(distinct(l.id)) as  active_loan_count,\r\ncount(distinct(laa.loan_id)  ) as arrears_loan_count,\r\n\r\nsum(l.principal_disbursed_derived) as principal,\r\nsum(l.principal_repaid_derived) as principal_repaid,\r\nsum(l.principal_outstanding_derived) as principal_outstanding,\r\nsum(ifnull(laa.principal_overdue_derived,0)) as principal_overdue,\r\n\r\nsum(l.interest_charged_derived) as interest,\r\nsum(l.interest_repaid_derived) as interest_repaid,\r\nsum(l.interest_outstanding_derived) as interest_outstanding,\r\nsum(ifnull(laa.interest_overdue_derived,0)) as interest_overdue,\r\n\r\nsum(l.fee_charges_charged_derived) as fees,\r\nsum(l.fee_charges_repaid_derived) as fees_repaid,\r\nsum(l.fee_charges_outstanding_derived)  as fees_outstanding,\r\nsum(ifnull(laa.fee_charges_overdue_derived,0)) as fees_overdue,\r\n\r\nsum(l.penalty_charges_charged_derived) as penalties,\r\nsum(l.penalty_charges_repaid_derived) as penalties_repaid,\r\nsum(l.penalty_charges_outstanding_derived) as penalties_outstanding,\r\nsum(ifnull(laa.penalty_charges_overdue_derived,0)) as penalties_overdue\r\n\r\nfrom m_office o \r\njoin m_office ounder on ounder.hierarchy like concat(o.hierarchy, \'%\')\r\nand ounder.hierarchy like concat(\'${currentUserHierarchy}\', \'%\')\r\njoin m_client c on c.office_id = ounder.id\r\njoin m_loan l on l.client_id = c.id\r\nleft join m_currency cur on cur.code = l.currency_code\r\nleft join m_loan_arrears_aging laa on laa.loan_id = l.id\r\n\r\nwhere o.id = ${officeId}\r\nand (l.currency_code = \"${currencyId}\" or \"-1\" = \"${currencyId}\")\r\nand (l.product_id = \"${loanProductId}\" or \"-1\" = \"${loanProductId}\")\r\nand (ifnull(l.loan_officer_id, -10) = \"${loanOfficerId}\" or \"-1\" = \"${loanOfficerId}\")\r\nand (ifnull(l.fund_id, -10) = ${fundId} or -1 = ${fundId})\r\nand (ifnull(l.loanpurpose_cv_id, -10) = ${loanPurposeId} or -1 = ${loanPurposeId})\r\nand l.loan_status_id = 300\r\nand l.expected_maturedon_date < curdate()\r\ngroup by ounder.id, l.currency_code) x on x.branch = mo.id\r\norder by mo.hierarchy, x.Currency',NULL,1,1,0);
INSERT INTO `stretchy_report` VALUES (57,'Active Loans in last installment','Table',NULL,'Loan','select concat(repeat(\"..\",   \r\n   ((LENGTH(lastInstallment.`hierarchy`) - LENGTH(REPLACE(lastInstallment.`hierarchy`, \'.\', \'\')) - 1))), lastInstallment.branch) as \"Office/Branch\",\r\nlastInstallment.Currency,\r\nlastInstallment.`Loan Officer`, \r\nlastInstallment.`Client Account No`, lastInstallment.`Client`, \r\nlastInstallment.`Loan Account No`, lastInstallment.`Product`, \r\nlastInstallment.`Fund`,  lastInstallment.`Loan Amount`, \r\nlastInstallment.`Annual Nominal Interest Rate`, \r\nlastInstallment.`Disbursed`, lastInstallment.`Expected Matured On` ,\r\n\r\nl.principal_repaid_derived as \"Principal Repaid\",\r\nl.principal_outstanding_derived as \"Principal Outstanding\",\r\nlaa.principal_overdue_derived as \"Principal Overdue\",\r\n\r\nl.interest_repaid_derived as \"Interest Repaid\",\r\nl.interest_outstanding_derived as \"Interest Outstanding\",\r\nlaa.interest_overdue_derived as \"Interest Overdue\",\r\n\r\nl.fee_charges_repaid_derived as \"Fees Repaid\",\r\nl.fee_charges_outstanding_derived  as \"Fees Outstanding\",\r\nlaa.fee_charges_overdue_derived as \"Fees Overdue\",\r\n\r\nl.penalty_charges_repaid_derived as \"Penalties Repaid\",\r\nl.penalty_charges_outstanding_derived as \"Penalties Outstanding\",\r\nlaa.penalty_charges_overdue_derived as \"Penalties Overdue\"\r\n\r\nfrom \r\n(select l.id as loanId, l.number_of_repayments, min(r.installment), \r\nounder.id, ounder.hierarchy, ounder.`name` as branch, \r\nifnull(cur.display_symbol, l.currency_code) as Currency,\r\nlo.display_name as \"Loan Officer\", c.account_no as \"Client Account No\",\r\nc.display_name as \"Client\", l.account_no as \"Loan Account No\", pl.`name` as \"Product\", \r\nf.`name` as Fund,  l.principal_amount as \"Loan Amount\", \r\nl.annual_nominal_interest_rate as \"Annual Nominal Interest Rate\", \r\ndate(l.disbursedon_date) as \"Disbursed\", date(l.expected_maturedon_date) as \"Expected Matured On\"\r\nfrom m_office o \r\njoin m_office ounder on ounder.hierarchy like concat(o.hierarchy, \'%\')\r\nand ounder.hierarchy like concat(\'${currentUserHierarchy}\', \'%\')\r\njoin m_client c on c.office_id = ounder.id\r\njoin m_loan l on l.client_id = c.id\r\njoin m_product_loan pl on pl.id = l.product_id\r\nleft join m_staff lo on lo.id = l.loan_officer_id\r\nleft join m_currency cur on cur.code = l.currency_code\r\nleft join m_fund f on f.id = l.fund_id\r\nleft join m_loan_repayment_schedule r on r.loan_id = l.id\r\nwhere o.id = ${officeId}\r\nand (l.currency_code = \"${currencyId}\" or \"-1\" = \"${currencyId}\")\r\nand (l.product_id = \"${loanProductId}\" or \"-1\" = \"${loanProductId}\")\r\nand (ifnull(l.loan_officer_id, -10) = \"${loanOfficerId}\" or \"-1\" = \"${loanOfficerId}\")\r\nand (ifnull(l.fund_id, -10) = ${fundId} or -1 = ${fundId})\r\nand (ifnull(l.loanpurpose_cv_id, -10) = ${loanPurposeId} or -1 = ${loanPurposeId})\r\nand l.loan_status_id = 300\r\nand r.completed_derived is false\r\nand r.duedate >= curdate()\r\ngroup by l.id\r\nhaving l.number_of_repayments = min(r.installment)) lastInstallment\r\njoin m_loan l on l.id = lastInstallment.loanId\r\nleft join m_loan_arrears_aging laa on laa.loan_id = l.id\r\norder by lastInstallment.hierarchy, lastInstallment.Currency, lastInstallment.`Client Account No`, lastInstallment.`Loan Account No`','Individual Client \n\nReport',1,1,0);
INSERT INTO `stretchy_report` VALUES (58,'Active Loans in last installment Summary','Table',NULL,'Loan','select concat(repeat(\"..\",   \r\n   ((LENGTH(mo.`hierarchy`) - LENGTH(REPLACE(mo.`hierarchy`, \'.\', \'\')) - 1))), mo.`name`) as \"Office/Branch\", x.currency as Currency,\r\n x.client_count as \"No. of Clients\", x.active_loan_count as \"No. Active Loans\", x. arrears_loan_count as \"No. of Loans in Arrears\",\r\nx.principal as \"Total Loans Disbursed\", x.principal_repaid as \"Principal Repaid\", x.principal_outstanding as \"Principal Outstanding\", x.principal_overdue as \"Principal Overdue\",\r\nx.interest as \"Total Interest\", x.interest_repaid as \"Interest Repaid\", x.interest_outstanding as \"Interest Outstanding\", x.interest_overdue as \"Interest Overdue\",\r\nx.fees as \"Total Fees\", x.fees_repaid as \"Fees Repaid\", x.fees_outstanding as \"Fees Outstanding\", x.fees_overdue as \"Fees Overdue\",\r\nx.penalties as \"Total Penalties\", x.penalties_repaid as \"Penalties Repaid\", x.penalties_outstanding as \"Penalties Outstanding\", x.penalties_overdue as \"Penalties Overdue\",\r\n\r\n	(case\r\n	when ${parType} = 1 then\r\n    cast(round((x.principal_overdue * 100) / x.principal_outstanding, 2) as char)\r\n	when ${parType} = 2 then\r\n    cast(round(((x.principal_overdue + x.interest_overdue) * 100) / (x.principal_outstanding + x.interest_outstanding), 2) as char)\r\n	when ${parType} = 3 then\r\n    cast(round(((x.principal_overdue + x.interest_overdue + x.fees_overdue) * 100) / (x.principal_outstanding + x.interest_outstanding + x.fees_outstanding), 2) as char)\r\n	when ${parType} = 4 then\r\n    cast(round(((x.principal_overdue + x.interest_overdue + x.fees_overdue + x.penalties_overdue) * 100) / (x.principal_outstanding + x.interest_outstanding + x.fees_outstanding + x.penalties_overdue), 2) as char)\r\n	else \"invalid PAR Type\"\r\n	end) as \"Portfolio at Risk %\"\r\n from m_office mo\r\njoin \r\n(select lastInstallment.branchId as branchId,\r\nlastInstallment.Currency,\r\ncount(distinct(lastInstallment.clientId)) as client_count, \r\ncount(distinct(lastInstallment.loanId)) as  active_loan_count,\r\ncount(distinct(laa.loan_id)  ) as arrears_loan_count,\r\n\r\nsum(l.principal_disbursed_derived) as principal,\r\nsum(l.principal_repaid_derived) as principal_repaid,\r\nsum(l.principal_outstanding_derived) as principal_outstanding,\r\nsum(ifnull(laa.principal_overdue_derived,0)) as principal_overdue,\r\n\r\nsum(l.interest_charged_derived) as interest,\r\nsum(l.interest_repaid_derived) as interest_repaid,\r\nsum(l.interest_outstanding_derived) as interest_outstanding,\r\nsum(ifnull(laa.interest_overdue_derived,0)) as interest_overdue,\r\n\r\nsum(l.fee_charges_charged_derived) as fees,\r\nsum(l.fee_charges_repaid_derived) as fees_repaid,\r\nsum(l.fee_charges_outstanding_derived)  as fees_outstanding,\r\nsum(ifnull(laa.fee_charges_overdue_derived,0)) as fees_overdue,\r\n\r\nsum(l.penalty_charges_charged_derived) as penalties,\r\nsum(l.penalty_charges_repaid_derived) as penalties_repaid,\r\nsum(l.penalty_charges_outstanding_derived) as penalties_outstanding,\r\nsum(ifnull(laa.penalty_charges_overdue_derived,0)) as penalties_overdue\r\n\r\nfrom \r\n(select l.id as loanId, l.number_of_repayments, min(r.installment), \r\nounder.id as branchId, ounder.hierarchy, ounder.`name` as branch, \r\nifnull(cur.display_symbol, l.currency_code) as Currency,\r\nlo.display_name as \"Loan Officer\", c.id as clientId, c.account_no as \"Client Account No\",\r\nc.display_name as \"Client\", l.account_no as \"Loan Account No\", pl.`name` as \"Product\", \r\nf.`name` as Fund,  l.principal_amount as \"Loan Amount\", \r\nl.annual_nominal_interest_rate as \"Annual Nominal Interest Rate\", \r\ndate(l.disbursedon_date) as \"Disbursed\", date(l.expected_maturedon_date) as \"Expected Matured On\"\r\nfrom m_office o \r\njoin m_office ounder on ounder.hierarchy like concat(o.hierarchy, \'%\')\r\nand ounder.hierarchy like concat(\'${currentUserHierarchy}\', \'%\')\r\njoin m_client c on c.office_id = ounder.id\r\njoin m_loan l on l.client_id = c.id\r\njoin m_product_loan pl on pl.id = l.product_id\r\nleft join m_staff lo on lo.id = l.loan_officer_id\r\nleft join m_currency cur on cur.code = l.currency_code\r\nleft join m_fund f on f.id = l.fund_id\r\nleft join m_loan_repayment_schedule r on r.loan_id = l.id\r\nwhere o.id = ${officeId}\r\nand (l.currency_code = \"${currencyId}\" or \"-1\" = \"${currencyId}\")\r\nand (l.product_id = \"${loanProductId}\" or \"-1\" = \"${loanProductId}\")\r\nand (ifnull(l.loan_officer_id, -10) = \"${loanOfficerId}\" or \"-1\" = \"${loanOfficerId}\")\r\nand (ifnull(l.fund_id, -10) = ${fundId} or -1 = ${fundId})\r\nand (ifnull(l.loanpurpose_cv_id, -10) = ${loanPurposeId} or -1 = ${loanPurposeId})\r\nand l.loan_status_id = 300\r\nand r.completed_derived is false\r\nand r.duedate >= curdate()\r\ngroup by l.id\r\nhaving l.number_of_repayments = min(r.installment)) lastInstallment\r\njoin m_loan l on l.id = lastInstallment.loanId\r\nleft join m_loan_arrears_aging laa on laa.loan_id = l.id\r\ngroup by lastInstallment.branchId) x on x.branchId = mo.id\r\norder by mo.hierarchy, x.Currency','Individual Client \n\nReport',1,1,0);
INSERT INTO `stretchy_report` VALUES (59,'Active Loans by Disbursal Period','Table',NULL,'Loan','select concat(repeat(\"..\",   \r\n   ((LENGTH(ounder.`hierarchy`) - LENGTH(REPLACE(ounder.`hierarchy`, \'.\', \'\')) - 1))), ounder.`name`) as \"Office/Branch\",\r\nifnull(cur.display_symbol, l.currency_code) as Currency,\r\nc.account_no as \"Client Account No\", c.display_name as \"Client\", l.account_no as \"Loan Account No\", pl.`name` as \"Product\", \r\nf.`name` as Fund,  \r\nl.principal_amount as \"Loan Principal Amount\", \r\nl.annual_nominal_interest_rate as \" Annual Nominal Interest Rate\", \r\ndate(l.disbursedon_date) as \"Disbursed Date\", \r\n\r\nl.total_expected_repayment_derived as \"Total Loan (P+I+F+Pen)\",\r\nl.total_repayment_derived as \"Total Repaid (P+I+F+Pen)\",\r\nlo.display_name as \"Loan Officer\"\r\n\r\nfrom m_office o \r\njoin m_office ounder on ounder.hierarchy like concat(o.hierarchy, \'%\')\r\nand ounder.hierarchy like concat(\'${currentUserHierarchy}\', \'%\')\r\njoin m_client c on c.office_id = ounder.id\r\njoin m_loan l on l.client_id = c.id\r\njoin m_product_loan pl on pl.id = l.product_id\r\nleft join m_staff lo on lo.id = l.loan_officer_id\r\nleft join m_currency cur on cur.code = l.currency_code\r\nleft join m_fund f on f.id = l.fund_id\r\nleft join m_loan_arrears_aging laa on laa.loan_id = l.id\r\nwhere o.id = ${officeId}\r\nand (l.currency_code = \"${currencyId}\" or \"-1\" = \"${currencyId}\")\r\nand (l.product_id = \"${loanProductId}\" or \"-1\" = \"${loanProductId}\")\r\nand (ifnull(l.loan_officer_id, -10) = \"${loanOfficerId}\" or \"-1\" = \"${loanOfficerId}\")\r\nand (ifnull(l.fund_id, -10) = ${fundId} or -1 = ${fundId})\r\nand (ifnull(l.loanpurpose_cv_id, -10) = ${loanPurposeId} or -1 = ${loanPurposeId})\r\nand l.disbursedon_date between \'${startDate}\' and \'${endDate}\'\r\nand l.loan_status_id = 300\r\ngroup by l.id\r\norder by ounder.hierarchy, l.currency_code, c.account_no, l.account_no','Individual Client \n\nReport',1,1,0);
INSERT INTO `stretchy_report` VALUES (61,'Aging Summary (Arrears in Months)','Table',NULL,'Loan','SELECT \r\n  IFNULL(periods.currencyName, periods.currency) as currency, \r\n  periods.period_no \'Days In Arrears\', \r\n  IFNULL(ars.loanId, 0) \'No Of Loans\', \r\n  IFNULL(ars.principal,0.0) \'Original Principal\', \r\n  IFNULL(ars.interest,0.0) \'Original Interest\', \r\n  IFNULL(ars.prinPaid,0.0) \'Principal Paid\', \r\n  IFNULL(ars.intPaid,0.0) \'Interest Paid\', \r\n  IFNULL(ars.prinOverdue,0.0) \'Principal Overdue\', \r\n  IFNULL(ars.intOverdue,0.0)\'Interest Overdue\'\r\nFROM \r\n	/* full table of aging periods/currencies used combo to ensure each line represented */\r\n  (SELECT curs.code as currency, curs.name as currencyName, pers.* from\r\n	(SELECT \'On Schedule\' period_no,1 pid UNION\r\n		SELECT \'0 - 30\',2 UNION\r\n		SELECT \'30 - 60\',3 UNION\r\n		SELECT \'60 - 90\',4 UNION\r\n		SELECT \'90 - 180\',5 UNION\r\n		SELECT \'180 - 360\',6 UNION\r\n		SELECT \'> 360\',7 ) pers,\r\n	(SELECT distinctrow moc.code, moc.name\r\n  	FROM m_office mo2\r\n   	INNER JOIN m_office ounder2 ON ounder2.hierarchy \r\n				LIKE CONCAT(mo2.hierarchy, \'%\')\r\nAND ounder2.hierarchy like CONCAT(\'${currentUserHierarchy}\', \'%\')\r\n   	INNER JOIN m_client mc2 ON mc2.office_id=ounder2.id\r\n   	INNER JOIN m_loan ml2 ON ml2.client_id = mc2.id\r\n	INNER JOIN m_organisation_currency moc ON moc.code = ml2.currency_code\r\n	WHERE ml2.loan_status_id=300 /* active */\r\n	AND mo2.id=${officeId}\r\nAND (ml2.currency_code = \"${currencyId}\" or \"-1\" = \"${currencyId}\")) curs) periods\r\n\r\n\r\nLEFT JOIN /* table of aging periods per currency with gaps if no applicable loans */\r\n(SELECT \r\n  	z.currency, z.arrPeriod, \r\n	COUNT(z.loanId) as loanId, SUM(z.principal) as principal, SUM(z.interest) as interest, \r\n	SUM(z.prinPaid) as prinPaid, SUM(z.intPaid) as intPaid, \r\n	SUM(z.prinOverdue) as prinOverdue, SUM(z.intOverdue) as intOverdue\r\nFROM\r\n	/*derived table just used to get arrPeriod value (was much slower to\r\n	duplicate calc of minOverdueDate in inner query)\r\nmight not be now with derived fields but didn’t check */\r\n	(SELECT x.loanId, x.currency, x.principal, x.interest, x.prinPaid, x.intPaid, x.prinOverdue, x.intOverdue,\r\n		IF(DATEDIFF(CURDATE(), minOverdueDate)<1, \'On Schedule\', \r\n		IF(DATEDIFF(CURDATE(), minOverdueDate)<31, \'0 - 30\', \r\n		IF(DATEDIFF(CURDATE(), minOverdueDate)<61, \'30 - 60\', \r\n		IF(DATEDIFF(CURDATE(), minOverdueDate)<91, \'60 - 90\', \r\n		IF(DATEDIFF(CURDATE(), minOverdueDate)<181, \'90 - 180\', \r\n		IF(DATEDIFF(CURDATE(), minOverdueDate)<361, \'180 - 360\', \r\n				 \'> 360\')))))) AS arrPeriod\r\n\r\n	FROM /* get the individual loan details */\r\n		(SELECT ml.id AS loanId, ml.currency_code as currency,\r\n   			ml.principal_disbursed_derived as principal, \r\n			   ml.interest_charged_derived as interest, \r\n   			ml.principal_repaid_derived as prinPaid, \r\n			   ml.interest_repaid_derived intPaid,\r\n\r\n			   laa.principal_overdue_derived as prinOverdue,\r\n			   laa.interest_overdue_derived as intOverdue,\r\n\r\n			   IFNULL(laa.overdue_since_date_derived, curdate()) as minOverdueDate\r\n			  \r\n  		FROM m_office mo\r\n   		INNER JOIN m_office ounder ON ounder.hierarchy \r\n				LIKE CONCAT(mo.hierarchy, \'%\')\r\nAND ounder.hierarchy like CONCAT(\'${currentUserHierarchy}\', \'%\')\r\n   		INNER JOIN m_client mc ON mc.office_id=ounder.id\r\n   		INNER JOIN m_loan ml ON ml.client_id = mc.id\r\n		   LEFT JOIN m_loan_arrears_aging laa on laa.loan_id = ml.id\r\n		WHERE ml.loan_status_id=300 /* active */\r\n     		AND mo.id=${officeId}\r\n     AND (ml.currency_code = \"${currencyId}\" or \"-1\" = \"${currencyId}\")\r\n  		GROUP BY ml.id) x\r\n	) z \r\nGROUP BY z.currency, z.arrPeriod ) ars ON ars.arrPeriod=periods.period_no and ars.currency = periods.currency\r\nORDER BY periods.currency, periods.pid','Loan amount in arrears by branch',1,1,0);
INSERT INTO `stretchy_report` VALUES (93,'Expected Payments By Date - Basic','Table',NULL,'Loan','SELECT \r\n      ounder.name \'Office\', \r\n      IFNULL(ms.display_name,\'-\') \'Loan Officer\',\r\n	  mc.account_no \'Client Account Number\',\r\n	  mc.display_name \'Name\',\r\n	  mp.name \'Product\',\r\n	  ml.account_no \'Loan Account Number\',\r\n	  mr.duedate \'Due Date\',\r\n	  mr.installment \'Installment\',\r\n	  cu.display_symbol \'Currency\',\r\n	  mr.principal_amount- IFNULL(mr.principal_completed_derived,0) \'Principal Due\',\r\n	  mr.interest_amount- IFNULL(IFNULL(mr.interest_completed_derived,mr.interest_waived_derived),0) \'Interest Due\', \r\n	  IFNULL(mr.fee_charges_amount,0)- IFNULL(IFNULL(mr.fee_charges_completed_derived,mr.fee_charges_waived_derived),0) \'Fees Due\', \r\n	  IFNULL(mr.penalty_charges_amount,0)- IFNULL(IFNULL(mr.penalty_charges_completed_derived,mr.penalty_charges_waived_derived),0) \'Penalty Due\',\r\n      (mr.principal_amount- IFNULL(mr.principal_completed_derived,0)) +\r\n       (mr.interest_amount- IFNULL(IFNULL(mr.interest_completed_derived,mr.interest_waived_derived),0)) + \r\n       (IFNULL(mr.fee_charges_amount,0)- IFNULL(IFNULL(mr.fee_charges_completed_derived,mr.fee_charges_waived_derived),0)) + \r\n       (IFNULL(mr.penalty_charges_amount,0)- IFNULL(IFNULL(mr.penalty_charges_completed_derived,mr.penalty_charges_waived_derived),0)) \'Total Due\', \r\n     mlaa.total_overdue_derived \'Total Overdue\'\r\n										 \r\n FROM m_office mo\r\n  JOIN m_office ounder ON ounder.hierarchy LIKE CONCAT(mo.hierarchy, \'%\')\r\n  \r\n  AND ounder.hierarchy like CONCAT(\'${currentUserHierarchy}\', \'%\')\r\n	\r\n  LEFT JOIN m_client mc ON mc.office_id=ounder.id\r\n  LEFT JOIN m_loan ml ON ml.client_id=mc.id AND ml.loan_status_id=300\r\n  LEFT JOIN m_loan_arrears_aging mlaa ON mlaa.loan_id=ml.id\r\n  LEFT JOIN m_loan_repayment_schedule mr ON mr.loan_id=ml.id AND mr.completed_derived=0\r\n  LEFT JOIN m_product_loan mp ON mp.id=ml.product_id\r\n  LEFT JOIN m_staff ms ON ms.id=ml.loan_officer_id\r\n  LEFT JOIN m_currency cu ON cu.code=ml.currency_code\r\n WHERE mo.id=${officeId}\r\n AND (IFNULL(ml.loan_officer_id, -10) = \"${loanOfficerId}\" OR \"-1\" = \"${loanOfficerId}\")\r\n AND mr.duedate BETWEEN \'${startDate}\' AND \'${endDate}\'\r\n ORDER BY ounder.id,mr.duedate,ml.account_no','Test',1,1,0);
INSERT INTO `stretchy_report` VALUES (96,'GroupSummaryCounts','Table',NULL,NULL,'\n/*\nActive Client is a client linked to the \'group\' via m_group_client\nand with an active \'status_enum\'.)\nActive Borrowers - Borrower may be a client or a \'group\'\n*/\nselect x.*\nfrom m_office o,\nm_group g,\n\n(select a.activeClients,\n(b.activeClientLoans + c.activeGroupLoans) as activeLoans,\nb.activeClientLoans, c.activeGroupLoans,\n(b.activeClientBorrowers + c.activeGroupBorrowers) as activeBorrowers,\nb.activeClientBorrowers, c.activeGroupBorrowers,\n(b.overdueClientLoans +  c.overdueGroupLoans) as overdueLoans,\nb.overdueClientLoans, c.overdueGroupLoans\nfrom\n(select count(*) as activeClients\nfrom m_group topgroup\njoin m_group g on g.hierarchy like concat(topgroup.hierarchy, \'%\')\njoin m_group_client gc on gc.group_id = g.id\njoin m_client c on c.id = gc.client_id\nwhere topgroup.id = ${groupId}\nand c.status_enum = 300) a,\n\n(select count(*) as activeClientLoans,\ncount(distinct(l.client_id)) as activeClientBorrowers,\nifnull(sum(if(laa.loan_id is not null, 1, 0)), 0) as overdueClientLoans\nfrom m_group topgroup\njoin m_group g on g.hierarchy like concat(topgroup.hierarchy, \'%\')\njoin m_loan l on l.group_id = g.id and l.client_id is not null\nleft join m_loan_arrears_aging laa on laa.loan_id = l.id\nwhere topgroup.id = ${groupId}\nand l.loan_status_id = 300) b,\n\n(select count(*) as activeGroupLoans,\ncount(distinct(l.group_id)) as activeGroupBorrowers,\nifnull(sum(if(laa.loan_id is not null, 1, 0)), 0) as overdueGroupLoans\nfrom m_group topgroup\njoin m_group g on g.hierarchy like concat(topgroup.hierarchy, \'%\')\njoin m_loan l on l.group_id = g.id and l.client_id is null\nleft join m_loan_arrears_aging laa on laa.loan_id = l.id\nwhere topgroup.id = ${groupId}\nand l.loan_status_id = 300) c\n) x\n\nwhere g.id = ${groupId}\nand o.id = g.office_id\nand o.hierarchy like concat(\'${currentUserHierarchy}\', \'%\')\n','Utility query for getting group summary count details for a group_id',1,0,0);
INSERT INTO `stretchy_report` VALUES (97,'GroupSummaryAmounts','Table',NULL,NULL,'\nselect ifnull(cur.display_symbol, l.currency_code) as currency,\nifnull(sum(l.principal_disbursed_derived),0) as totalDisbursedAmount,\nifnull(sum(l.principal_outstanding_derived),0) as totalLoanOutstandingAmount,\ncount(laa.loan_id) as overdueLoans, ifnull(sum(laa.total_overdue_derived), 0) as totalLoanOverdueAmount\nfrom m_group topgroup\njoin m_office o on o.id = topgroup.office_id and o.hierarchy like concat(\'${currentUserHierarchy}\', \'%\')\njoin m_group g on g.hierarchy like concat(topgroup.hierarchy, \'%\')\njoin m_loan l on l.group_id = g.id\nleft join m_loan_arrears_aging laa on laa.loan_id = l.id\nleft join m_currency cur on cur.code = l.currency_code\nwhere topgroup.id = ${groupId}\nand l.disbursedon_date is not null\ngroup by l.currency_code\n','Utility query for getting group summary currency amount details for a group_id',1,0,0);
INSERT INTO `stretchy_report` VALUES (106,'TxnRunningBalances','Table',NULL,'Transaction','\nselect date(\'${startDate}\') as \'Transaction Date\', \'Opening Balance\' as `Transaction Type`, null as Office,\n    null as \'Loan Officer\', null as `Loan Account No`, null as `Loan Product`, null as `Currency`,\n    null as `Client Account No`, null as Client,\n    null as Amount, null as Principal, null as Interest,\n@totalOutstandingPrincipal :=\nifnull(round(sum(\n    if (txn.transaction_type_enum = 1 /* disbursement */,\n        ifnull(txn.amount,0.00),\n        ifnull(txn.principal_portion_derived,0.00) * -1))\n            ,2),0.00)  as \'Outstanding Principal\',\n\n@totalInterestIncome :=\nifnull(round(sum(\n    if (txn.transaction_type_enum in (2,5,8) /* repayment, repayment at disbursal, recovery repayment */,\n        ifnull(txn.interest_portion_derived,0.00),\n        0))\n            ,2),0.00) as \'Interest Income\',\n\n@totalWriteOff :=\nifnull(round(sum(\n    if (txn.transaction_type_enum = 6 /* write-off */,\n        ifnull(txn.principal_portion_derived,0.00),\n        0))\n            ,2),0.00) as \'Principal Write Off\'\nfrom m_office o\njoin m_office ounder on ounder.hierarchy like concat(o.hierarchy, \'%\')\n                          and ounder.hierarchy like concat(\'${currentUserHierarchy}\', \'%\')\njoin m_client c on c.office_id = ounder.id\njoin m_loan l on l.client_id = c.id\njoin m_product_loan lp on lp.id = l.product_id\njoin m_loan_transaction txn on txn.loan_id = l.id\nleft join m_currency cur on cur.code = l.currency_code\nwhere txn.is_reversed = false\nand txn.transaction_type_enum not in (10,11)\nand o.id = ${officeId}\nand txn.transaction_date < date(\'${startDate}\')\n\nunion all\n\nselect x.`Transaction Date`, x.`Transaction Type`, x.Office, x.`Loan Officer`, x.`Loan Account No`, x.`Loan Product`, x.`Currency`,\n    x.`Client Account No`, x.Client, x.Amount, x.Principal, x.Interest,\ncast(round(\n    if (x.transaction_type_enum = 1 /* disbursement */,\n        @totalOutstandingPrincipal := @totalOutstandingPrincipal + x.`Amount`,\n        @totalOutstandingPrincipal := @totalOutstandingPrincipal - x.`Principal`)\n            ,2) as decimal(19,2)) as \'Outstanding Principal\',\ncast(round(\n    if (x.transaction_type_enum in (2,5,8) /* repayment, repayment at disbursal, recovery repayment */,\n        @totalInterestIncome := @totalInterestIncome + x.`Interest`,\n        @totalInterestIncome)\n            ,2) as decimal(19,2)) as \'Interest Income\',\ncast(round(\n    if (x.transaction_type_enum = 6 /* write-off */,\n        @totalWriteOff := @totalWriteOff + x.`Principal`,\n        @totalWriteOff)\n            ,2) as decimal(19,2)) as \'Principal Write Off\'\nfrom\n(select txn.transaction_type_enum, txn.id as txn_id, txn.transaction_date as \'Transaction Date\',\ncast(\n    ifnull(re.enum_message_property, concat(\'Unknown Transaction Type Value: \' , txn.transaction_type_enum))\n    as char) as \'Transaction Type\',\nounder.`name` as Office, lo.display_name as \'Loan Officer\',\nl.account_no  as \'Loan Account No\', lp.`name` as \'Loan Product\',\nifnull(cur.display_symbol, l.currency_code) as Currency,\nc.account_no as \'Client Account No\', c.display_name as \'Client\',\nifnull(txn.amount,0.00) as Amount,\nifnull(txn.principal_portion_derived,0.00) as Principal,\nifnull(txn.interest_portion_derived,0.00) as Interest\nfrom m_office o\njoin m_office ounder on ounder.hierarchy like concat(o.hierarchy, \'%\')\n                          and ounder.hierarchy like concat(\'${currentUserHierarchy}\', \'%\')\njoin m_client c on c.office_id = ounder.id\njoin m_loan l on l.client_id = c.id\nleft join m_staff lo on lo.id = l.loan_officer_id\njoin m_product_loan lp on lp.id = l.product_id\njoin m_loan_transaction txn on txn.loan_id = l.id\nleft join m_currency cur on cur.code = l.currency_code\nleft join r_enum_value re on re.enum_name = \'transaction_type_enum\'\n                        and re.enum_id = txn.transaction_type_enum\nwhere txn.is_reversed = false\nand txn.transaction_type_enum not in (10,11)\nand (ifnull(l.loan_officer_id, -10) = \'${loanOfficerId}\' or \'-1\' = \'${loanOfficerId}\')\nand o.id = ${officeId}\nand txn.transaction_date >= date(\'${startDate}\')\nand txn.transaction_date <= date(\'${endDate}\')\norder by txn.transaction_date, txn.id) x\n','Running Balance Txn report for Individual Lending.\nSuitable for small MFI\'s.  Larger could use it using the branch or other parameters.\nBasically, suck it and see if its quick enough for you out-of-te box or whether it needs performance work in your situation.\n',0,0,0);
INSERT INTO `stretchy_report` VALUES (107,'FieldAgentStats','Table',NULL,'Quipo','\nselect ifnull(cur.display_symbol, l.currency_code) as Currency,\n/*This query will return more than one entry if more than one currency is used */\ncount(distinct(c.id)) as activeClients, count(*) as activeLoans,\nsum(l.principal_disbursed_derived) as disbursedAmount,\nsum(l.principal_outstanding_derived) as loanOutstandingAmount,\nround((sum(l.principal_outstanding_derived) * 100) /  sum(l.principal_disbursed_derived),2) as loanOutstandingPC,\nsum(ifnull(lpa.principal_in_advance_derived,0.0)) as LoanPaidInAdvance,\nsum(\n    if(date_sub(curdate(), interval 28 day) > ifnull(laa.overdue_since_date_derived, curdate()),\n        l.principal_outstanding_derived,0)) as portfolioAtRisk,\n\nround((sum(\n    if(date_sub(curdate(), interval 28 day) > ifnull(laa.overdue_since_date_derived, curdate()),\n        l.principal_outstanding_derived,0)) * 100) / sum(l.principal_outstanding_derived), 2) as portfolioAtRiskPC,\n\ncount(distinct(\n        if(date_sub(curdate(), interval 28 day) > ifnull(laa.overdue_since_date_derived, curdate()),\n            c.id,null))) as clientsInDefault,\nround((count(distinct(\n        if(date_sub(curdate(), interval 28 day) > ifnull(laa.overdue_since_date_derived, curdate()),\n            c.id,null))) * 100) / count(distinct(c.id)),2) as clientsInDefaultPC,\n(sum(l.principal_disbursed_derived) / count(*))  as averageLoanAmount\nfrom m_staff fa\njoin m_office o on o.id = fa.office_id\n            and o.hierarchy like concat(\'${currentUserHierarchy}\', \'%\')\njoin m_group pgm on pgm.staff_id = fa.id\njoin m_loan l on l.group_id = pgm.id and l.client_id is not null\nleft join m_currency cur on cur.code = l.currency_code\nleft join m_loan_arrears_aging laa on laa.loan_id = l.id\nleft join m_loan_paid_in_advance lpa on lpa.loan_id = l.id\njoin m_client c on c.id = l.client_id\nwhere fa.id = ${staffId}\nand l.loan_status_id = 300\ngroup  by l.currency_code\n','Field Agent Statistics',0,0,0);
INSERT INTO `stretchy_report` VALUES (108,'FieldAgentPrograms','Table',NULL,'Quipo','\nselect pgm.id, pgm.display_name as `name`, sts.enum_message_property as status\n from m_group pgm\n join m_office o on o.id = pgm.office_id\n            and o.hierarchy like concat(\'${currentUserHierarchy}\', \'%\')\n left join r_enum_value sts on sts.enum_name = \'status_enum\' and sts.enum_id = pgm.status_enum\n where pgm.staff_id = ${staffId}\n','List of Field Agent Programs',0,0,0);
INSERT INTO `stretchy_report` VALUES (109,'ProgramDetails','Table',NULL,'Quipo','\n select l.id as loanId, l.account_no as loanAccountNo, c.id as clientId, c.account_no as clientAccountNo,\n pgm.display_name as programName,\n\n(select count(*)\nfrom m_loan cy\nwhere cy.group_id = pgm.id and cy.client_id =c.id\nand cy.disbursedon_date <= l.disbursedon_date) as loanCycleNo,\n\nc.display_name as clientDisplayName,\n ifnull(cur.display_symbol, l.currency_code) as Currency,\nifnull(l.principal_repaid_derived,0.0) as loanRepaidAmount,\nifnull(l.principal_outstanding_derived, 0.0) as loanOutstandingAmount,\nifnull(lpa.principal_in_advance_derived,0.0) as LoanPaidInAdvance,\n\nifnull(laa.principal_overdue_derived, 0.0) as loanInArrearsAmount,\nif(ifnull(laa.principal_overdue_derived, 0.00) > 0, \'Yes\', \'No\') as inDefault,\n\nif(date_sub(curdate(), interval 28 day) > ifnull(laa.overdue_since_date_derived, curdate()),\n        l.principal_outstanding_derived,0)  as portfolioAtRisk\n\n from m_group pgm\n join m_office o on o.id = pgm.office_id\n            and o.hierarchy like concat(\'${currentUserHierarchy}\', \'%\')\n join m_loan l on l.group_id = pgm.id and l.client_id is not null\n left join m_currency cur on cur.code = l.currency_code\n join m_client c on c.id = l.client_id\n left join m_loan_arrears_aging laa on laa.loan_id = l.id\n left join m_loan_paid_in_advance lpa on lpa.loan_id = l.id\n where pgm.id = ${programId}\n and l.loan_status_id = 300\norder by c.display_name, l.account_no\n\n','List of Loans in a Program',0,0,0);
INSERT INTO `stretchy_report` VALUES (110,'ChildrenStaffList','Table',NULL,'Quipo','\n select s.id, s.display_name,\ns.firstname, s.lastname, s.organisational_role_enum,\ns.organisational_role_parent_staff_id,\nsp.display_name as `organisational_role_parent_staff_display_name`\nfrom m_staff s\njoin m_staff sp on s.organisational_role_parent_staff_id = sp.id\nwhere s.organisational_role_parent_staff_id = ${staffId}\n','Get Next Level Down Staff',0,0,0);
INSERT INTO `stretchy_report` VALUES (111,'CoordinatorStats','Table',NULL,'Quipo','\nselect ifnull(cur.display_symbol, l.currency_code) as Currency,\n/*This query will return more than one entry if more than one currency is used */\ncount(distinct(c.id)) as activeClients, count(*) as activeLoans,\nsum(l.principal_disbursed_derived) as disbursedAmount,\nsum(l.principal_outstanding_derived) as loanOutstandingAmount,\nround((sum(l.principal_outstanding_derived) * 100) /  sum(l.principal_disbursed_derived),2) as loanOutstandingPC,\nsum(ifnull(lpa.principal_in_advance_derived,0.0)) as LoanPaidInAdvance,\nsum(\n    if(date_sub(curdate(), interval 28 day) > ifnull(laa.overdue_since_date_derived, curdate()),\n        l.principal_outstanding_derived,0)) as portfolioAtRisk,\n\nround((sum(\n    if(date_sub(curdate(), interval 28 day) > ifnull(laa.overdue_since_date_derived, curdate()),\n        l.principal_outstanding_derived,0)) * 100) / sum(l.principal_outstanding_derived), 2) as portfolioAtRiskPC,\n\ncount(distinct(\n        if(date_sub(curdate(), interval 28 day) > ifnull(laa.overdue_since_date_derived, curdate()),\n            c.id,null))) as clientsInDefault,\nround((count(distinct(\n        if(date_sub(curdate(), interval 28 day) > ifnull(laa.overdue_since_date_derived, curdate()),\n            c.id,null))) * 100) / count(distinct(c.id)),2) as clientsInDefaultPC,\n(sum(l.principal_disbursed_derived) / count(*))  as averageLoanAmount\nfrom m_staff coord\njoin m_staff fa on fa.organisational_role_parent_staff_id = coord.id\njoin m_office o on o.id = fa.office_id\n            and o.hierarchy like concat(\'${currentUserHierarchy}\', \'%\')\njoin m_group pgm on pgm.staff_id = fa.id\njoin m_loan l on l.group_id = pgm.id and l.client_id is not null\nleft join m_currency cur on cur.code = l.currency_code\nleft join m_loan_arrears_aging laa on laa.loan_id = l.id\nleft join m_loan_paid_in_advance lpa on lpa.loan_id = l.id\njoin m_client c on c.id = l.client_id\nwhere coord.id = ${staffId}\nand l.loan_status_id = 300\ngroup  by l.currency_code\n','Coordinator Statistics',0,0,0);
INSERT INTO `stretchy_report` VALUES (112,'BranchManagerStats','Table',NULL,'Quipo','\nselect ifnull(cur.display_symbol, l.currency_code) as Currency,\n/*This query will return more than one entry if more than one currency is used */\ncount(distinct(c.id)) as activeClients, count(*) as activeLoans,\nsum(l.principal_disbursed_derived) as disbursedAmount,\nsum(l.principal_outstanding_derived) as loanOutstandingAmount,\nround((sum(l.principal_outstanding_derived) * 100) /  sum(l.principal_disbursed_derived),2) as loanOutstandingPC,\nsum(ifnull(lpa.principal_in_advance_derived,0.0)) as LoanPaidInAdvance,\nsum(\n    if(date_sub(curdate(), interval 28 day) > ifnull(laa.overdue_since_date_derived, curdate()),\n        l.principal_outstanding_derived,0)) as portfolioAtRisk,\n\nround((sum(\n    if(date_sub(curdate(), interval 28 day) > ifnull(laa.overdue_since_date_derived, curdate()),\n        l.principal_outstanding_derived,0)) * 100) / sum(l.principal_outstanding_derived), 2) as portfolioAtRiskPC,\n\ncount(distinct(\n        if(date_sub(curdate(), interval 28 day) > ifnull(laa.overdue_since_date_derived, curdate()),\n            c.id,null))) as clientsInDefault,\nround((count(distinct(\n        if(date_sub(curdate(), interval 28 day) > ifnull(laa.overdue_since_date_derived, curdate()),\n            c.id,null))) * 100) / count(distinct(c.id)),2) as clientsInDefaultPC,\n(sum(l.principal_disbursed_derived) / count(*))  as averageLoanAmount\nfrom m_staff bm\njoin m_staff coord on coord.organisational_role_parent_staff_id = bm.id\njoin m_staff fa on fa.organisational_role_parent_staff_id = coord.id\njoin m_office o on o.id = fa.office_id\n            and o.hierarchy like concat(\'${currentUserHierarchy}\', \'%\')\njoin m_group pgm on pgm.staff_id = fa.id\njoin m_loan l on l.group_id = pgm.id and l.client_id is not null\nleft join m_currency cur on cur.code = l.currency_code\nleft join m_loan_arrears_aging laa on laa.loan_id = l.id\nleft join m_loan_paid_in_advance lpa on lpa.loan_id = l.id\njoin m_client c on c.id = l.client_id\nwhere bm.id = ${staffId}\nand l.loan_status_id = 300\ngroup  by l.currency_code\n','Branch Manager Statistics',0,0,0);
INSERT INTO `stretchy_report` VALUES (113,'ProgramDirectorStats','Table',NULL,'Quipo','\nselect ifnull(cur.display_symbol, l.currency_code) as Currency,\n/*This query will return more than one entry if more than one currency is used */\ncount(distinct(c.id)) as activeClients, count(*) as activeLoans,\nsum(l.principal_disbursed_derived) as disbursedAmount,\nsum(l.principal_outstanding_derived) as loanOutstandingAmount,\nround((sum(l.principal_outstanding_derived) * 100) /  sum(l.principal_disbursed_derived),2) as loanOutstandingPC,\nsum(ifnull(lpa.principal_in_advance_derived,0.0)) as LoanPaidInAdvance,\nsum(\n    if(date_sub(curdate(), interval 28 day) > ifnull(laa.overdue_since_date_derived, curdate()),\n        l.principal_outstanding_derived,0)) as portfolioAtRisk,\n\nround((sum(\n    if(date_sub(curdate(), interval 28 day) > ifnull(laa.overdue_since_date_derived, curdate()),\n        l.principal_outstanding_derived,0)) * 100) / sum(l.principal_outstanding_derived), 2) as portfolioAtRiskPC,\n\ncount(distinct(\n        if(date_sub(curdate(), interval 28 day) > ifnull(laa.overdue_since_date_derived, curdate()),\n            c.id,null))) as clientsInDefault,\nround((count(distinct(\n        if(date_sub(curdate(), interval 28 day) > ifnull(laa.overdue_since_date_derived, curdate()),\n            c.id,null))) * 100) / count(distinct(c.id)),2) as clientsInDefaultPC,\n(sum(l.principal_disbursed_derived) / count(*))  as averageLoanAmount\nfrom m_staff pd\njoin m_staff bm on bm.organisational_role_parent_staff_id = pd.id\njoin m_staff coord on coord.organisational_role_parent_staff_id = bm.id\njoin m_staff fa on fa.organisational_role_parent_staff_id = coord.id\njoin m_office o on o.id = fa.office_id\n            and o.hierarchy like concat(\'${currentUserHierarchy}\', \'%\')\njoin m_group pgm on pgm.staff_id = fa.id\njoin m_loan l on l.group_id = pgm.id and l.client_id is not null\nleft join m_currency cur on cur.code = l.currency_code\nleft join m_loan_arrears_aging laa on laa.loan_id = l.id\nleft join m_loan_paid_in_advance lpa on lpa.loan_id = l.id\njoin m_client c on c.id = l.client_id\nwhere pd.id = ${staffId}\nand l.loan_status_id = 300\ngroup  by l.currency_code\n','Program DirectorStatistics',0,0,0);
INSERT INTO `stretchy_report` VALUES (114,'ProgramStats','Table',NULL,'Quipo','\nselect ifnull(cur.display_symbol, l.currency_code) as Currency,\n/*This query will return more than one entry if more than one currency is used */\ncount(distinct(c.id)) as activeClients, count(*) as activeLoans,\nsum(l.principal_disbursed_derived) as disbursedAmount,\nsum(l.principal_outstanding_derived) as loanOutstandingAmount,\nround((sum(l.principal_outstanding_derived) * 100) /  sum(l.principal_disbursed_derived),2) as loanOutstandingPC,\nsum(ifnull(lpa.principal_in_advance_derived,0.0)) as LoanPaidInAdvance,\nsum(\n    if(date_sub(curdate(), interval 28 day) > ifnull(laa.overdue_since_date_derived, curdate()),\n        l.principal_outstanding_derived,0)) as portfolioAtRisk,\n\nround((sum(\n    if(date_sub(curdate(), interval 28 day) > ifnull(laa.overdue_since_date_derived, curdate()),\n        l.principal_outstanding_derived,0)) * 100) / sum(l.principal_outstanding_derived), 2) as portfolioAtRiskPC,\n\ncount(distinct(\n        if(date_sub(curdate(), interval 28 day) > ifnull(laa.overdue_since_date_derived, curdate()),\n            c.id,null))) as clientsInDefault,\nround((count(distinct(\n        if(date_sub(curdate(), interval 28 day) > ifnull(laa.overdue_since_date_derived, curdate()),\n            c.id,null))) * 100) / count(distinct(c.id)),2) as clientsInDefaultPC,\n(sum(l.principal_disbursed_derived) / count(*))  as averageLoanAmount\nfrom m_group pgm\njoin m_office o on o.id = pgm.office_id\n            and o.hierarchy like concat(\'${currentUserHierarchy}\', \'%\')\njoin m_loan l on l.group_id = pgm.id and l.client_id is not null\nleft join m_currency cur on cur.code = l.currency_code\nleft join m_loan_arrears_aging laa on laa.loan_id = l.id\nleft join m_loan_paid_in_advance lpa on lpa.loan_id = l.id\njoin m_client c on c.id = l.client_id\nwhere pgm.id = ${programId}\nand l.loan_status_id = 300\ngroup  by l.currency_code\n','Program Statistics',0,0,0);
INSERT INTO `stretchy_report` VALUES (115,'ClientSummary ','Table',NULL,NULL,'SELECT x.* FROM m_client c, m_office o, \n(\n       SELECT a.loanCycle, a.activeLoans, b.lastLoanAmount, d.activeSavings, d.totalSavings FROM \n	(SELECT IFNULL(MAX(l.loan_counter),0) AS loanCycle, COUNT(l.id) AS activeLoans FROM m_loan l WHERE l.loan_status_id=300 AND l.client_id=${clientId}) a, \n	(SELECT count(l.id), IFNULL(l.principal_amount,0) AS \'lastLoanAmount\' FROM m_loan l WHERE l.client_id=${clientId} AND l.disbursedon_date = (SELECT IFNULL(MAX(disbursedon_date),NOW()) FROM m_loan where client_id=${clientId} and loan_status_id=300) group by l.principal_amount) b, \n	(SELECT COUNT(s.id) AS \'activeSavings\', IFNULL(SUM(s.account_balance_derived),0) AS \'totalSavings\' FROM m_savings_account s WHERE s.status_enum=300 AND s.client_id=${clientId}) d\n) x\nWHERE c.id=${clientId} AND o.id = c.office_id AND o.hierarchy LIKE CONCAT(\'${currentUserHierarchy}\', \'%\')','Utility query for getting the client summary details',1,0,0);
INSERT INTO `stretchy_report` VALUES (116,'LoanCyclePerProduct','Table',NULL,NULL,'SELECT lp.name AS \'productName\', MAX(l.loan_product_counter) AS \'loanProductCycle\' FROM m_loan l JOIN m_product_loan lp ON l.product_id=lp.id WHERE lp.include_in_borrower_cycle=1 AND l.loan_product_counter IS NOT NULL AND l.client_id=${clientId} GROUP BY l.product_id','Utility query for getting the client loan cycle details',1,0,0);
INSERT INTO `stretchy_report` VALUES (117,'GroupSavingSummary','Table',NULL,NULL,'select ifnull(cur.display_symbol, sa.currency_code) as currency,\ncount(sa.id) as totalSavingAccounts, ifnull(sum(sa.account_balance_derived),0) as totalSavings\nfrom m_group topgroup\njoin m_office o on o.id = topgroup.office_id and o.hierarchy like concat(\'${currentUserHierarchy}\', \'%\')\njoin m_group g on g.hierarchy like concat(topgroup.hierarchy, \'%\')\njoin m_savings_account sa on sa.group_id = g.id\nleft join m_currency cur on cur.code = sa.currency_code\nwhere topgroup.id = ${groupId}\nand sa.activatedon_date is not null\ngroup by sa.currency_code','Utility query for getting group or center saving summary details for a group_id',1,0,0);
INSERT INTO `stretchy_report` VALUES (148,'GroupNamesByStaff','Table','','','Select gr.id as id, gr.display_name as name from m_group gr where gr.level_id=1 and gr.staff_id = ${staffId}','',1,0,0);
INSERT INTO `stretchy_report` VALUES (149,'ClientTrendsByDay','Table','','Client','SELECT COUNT(cl.id) AS count, cl.activation_date AS days             FROM m_office o LEFT JOIN m_client cl on o.id = cl.office_id             WHERE o.hierarchy like concat((select ino.hierarchy from m_office ino where ino.id = ${officeId}),\'%\' )                 AND (cl.activation_date BETWEEN DATE_SUB(CURDATE(), INTERVAL 12 DAY) AND DATE(NOW()- INTERVAL 1 DAY))             GROUP BY days             ','Retrieves the number of clients joined in last 12 days',1,0,0);
INSERT INTO `stretchy_report` VALUES (150,'ClientTrendsByWeek','Table','','Client','SELECT COUNT(cl.id) AS count, WEEK(cl.activation_date) AS Weeks             FROM m_office o LEFT JOIN m_client cl on o.id = cl.office_id             WHERE o.hierarchy like concat((select ino.hierarchy from m_office ino where ino.id = ${officeId}),\'%\' )                 AND (cl.activation_date BETWEEN DATE_SUB(CURDATE(), INTERVAL 12 WEEK) AND DATE(NOW()))             GROUP BY Weeks             ','',1,0,0);
INSERT INTO `stretchy_report` VALUES (151,'ClientTrendsByMonth','Table','','Client','SELECT COUNT(cl.id) AS count, MONTHNAME(cl.activation_date) AS Months             FROM m_office o LEFT JOIN m_client cl on o.id = cl.office_id             WHERE o.hierarchy like concat((select ino.hierarchy from m_office ino where ino.id = ${officeId}),\'%\' )                 AND (cl.activation_date BETWEEN DATE_SUB(CURDATE(), INTERVAL 12 MONTH) AND DATE(NOW()))             GROUP BY Months             ','',1,0,0);
INSERT INTO `stretchy_report` VALUES (152,'LoanTrendsByDay','Table','','Loan','SELECT COUNT(ln.id) AS lcount, ln.disbursedon_date AS days             FROM m_office o LEFT JOIN m_client cl on o.id = cl.office_id                 LEFT JOIN m_loan ln on cl.id = ln.client_id             WHERE o.hierarchy like concat((select ino.hierarchy from m_office ino where ino.id = ${officeId}),\'%\' )                 AND (ln.disbursedon_date BETWEEN DATE_SUB(CURDATE(), INTERVAL 12 DAY) AND DATE(NOW()- INTERVAL 1 DAY))             GROUP BY days             ','Retrieves Number of loans disbursed for last 12 days',1,0,0);
INSERT INTO `stretchy_report` VALUES (153,'LoanTrendsByWeek','Table','','Loan','SELECT COUNT(ln.id) AS lcount, WEEK(ln.disbursedon_date) AS Weeks             FROM m_office o                 LEFT JOIN m_client cl on o.id = cl.office_id                 LEFT JOIN m_loan ln on cl.id = ln.client_id             WHERE o.hierarchy like concat((select ino.hierarchy from m_office ino where ino.id = ${officeId}),\'%\' )                 AND (ln.disbursedon_date BETWEEN DATE_SUB(CURDATE(), INTERVAL 12 WEEK) AND DATE(NOW()))             GROUP BY Weeks             ','',1,0,0);
INSERT INTO `stretchy_report` VALUES (154,'LoanTrendsByMonth','Table','','Loan','SELECT COUNT(ln.id) AS lcount, MONTHNAME(ln.disbursedon_date) AS Months             FROM m_office o                 LEFT JOIN m_client cl on o.id = cl.office_id                 LEFT JOIN m_loan ln on cl.id = ln.client_id             WHERE o.hierarchy like concat((select ino.hierarchy from m_office ino where ino.id = ${officeId}),\'%\' )                 AND (ln.disbursedon_date BETWEEN (CURDATE() - INTERVAL 12 MONTH) AND DATE(NOW()))             GROUP BY Months             ','',1,0,0);
INSERT INTO `stretchy_report` VALUES (155,'Demand Vs Collection','Table','','Loan','SELECT amount.AmountDue-amount.AmountPaid as AmountDue, amount.AmountPaid as AmountPaid FROM             (SELECT             (COALESCE(SUM(ls.principal_amount),0) - COALESCE(SUM(ls.principal_writtenoff_derived),0)              + COALESCE(SUM(ls.interest_amount),0) - COALESCE(SUM(ls.interest_writtenoff_derived),0)              - COALESCE(SUM(ls.interest_waived_derived),0)              + COALESCE(SUM(ls.fee_charges_amount),0) - COALESCE(SUM(ls.fee_charges_writtenoff_derived),0)              - COALESCE(SUM(ls.fee_charges_waived_derived),0)              + COALESCE(SUM(ls.penalty_charges_amount),0) - COALESCE(SUM(ls.penalty_charges_writtenoff_derived),0)              - COALESCE(SUM(ls.penalty_charges_waived_derived),0)             ) AS AmountDue,             (COALESCE(SUM(ls.principal_completed_derived),0) - COALESCE(SUM(ls.principal_writtenoff_derived),0) + COALESCE(SUM(ls.interest_completed_derived),0) - COALESCE(SUM(ls.interest_writtenoff_derived),0)              - COALESCE(SUM(ls.interest_waived_derived),0)              + COALESCE(SUM(ls.fee_charges_completed_derived),0) - COALESCE(SUM(ls.fee_charges_writtenoff_derived),0)              - COALESCE(SUM(ls.fee_charges_waived_derived),0)              + COALESCE(SUM(ls.penalty_charges_completed_derived),0) - COALESCE(SUM(ls.penalty_charges_writtenoff_derived),0)              - COALESCE(SUM(ls.penalty_charges_waived_derived),0)             ) AS AmountPaid             FROM m_office o             LEFT JOIN m_client cl ON o.id = cl.office_id             LEFT JOIN m_loan ln ON cl.id = ln.client_id             LEFT JOIN m_loan_repayment_schedule ls ON ln.id = ls.loan_id             WHERE              (o.hierarchy LIKE CONCAT((SELECT ino.hierarchy FROM m_office ino WHERE ino.id = ${officeId}),\'%\'))) as amount             ','Demand Vs Collection',1,0,0);
INSERT INTO `stretchy_report` VALUES (156,'Disbursal Vs Awaitingdisbursal','Table','','Loan','SELECT awaitinddisbursal.amount-disbursedAmount.amount as amountToBeDisburse, disbursedAmount.amount as disbursedAmount from             (SELECT COUNT(ln.id) AS noOfLoans, COALESCE(SUM(ln.principal_amount),0) AS amount FROM m_office o             LEFT JOIN m_client cl ON cl.office_id = o.id             LEFT JOIN m_loan ln ON cl.id = ln.client_id             WHERE (ln.loan_status_id=200 OR ln.loan_status_id=300) AND                 o.hierarchy like concat((select ino.hierarchy from m_office ino where ino.id = ${officeId}),\'%\' )             ) awaitinddisbursal,             (SELECT COUNT(ltrxn.id) as count, COALESCE(SUM(ltrxn.amount),0) as amount FROM m_office o             LEFT JOIN m_client cl ON cl.office_id = o.id             LEFT JOIN m_loan ln ON cl.id = ln.client_id             LEFT JOIN m_loan_transaction ltrxn ON ln.id = ltrxn.loan_id             WHERE ltrxn.is_reversed = false AND ltrxn.transaction_type_enum=1 AND                 o.hierarchy like concat((select ino.hierarchy from m_office ino where ino.id = ${officeId}),\'%\' )             ) disbursedAmount             ','Disbursal_Vs_Awaitingdisbursal',1,0,0);
INSERT INTO `stretchy_report` VALUES (165,'Savings Accounts Dormancy Report','Table',NULL,'Savings','select cl.display_name as \'Client Display Name\',\r\nsa.account_no as \'Account Number\',\r\ncl.mobile_no as \'Mobile Number\',\r\n@lastdate:=(select IFNULL(max(sat.transaction_date),sa.activatedon_date) \r\n            from m_savings_account_transaction as sat \r\n            where sat.is_reversed = 0 \r\n            and sat.transaction_type_enum in (1,2) \r\n            and sat.savings_account_id = sa.id) as \'Date of Last Activity\',\r\nDATEDIFF(now(), @lastdate) as \'Days Since Last Activity\'\r\nfrom m_savings_account as sa \r\ninner join m_savings_product as sp on (sa.product_id = sp.id and sp.is_dormancy_tracking_active = 1) \r\nleft join m_client as cl on sa.client_id = cl.id \r\nwhere sa.sub_status_enum = ${subStatus}\r\nand cl.office_id = ${officeId}',NULL,1,1,0);
INSERT INTO `stretchy_report` VALUES (166,'Active Clients','SMS','NonTriggered','Client','SELECT c.id AS \"id\", \r\nc.firstname AS \"firstName\",\r\nc.middlename AS \"middleName\",\r\nc.lastname AS \"lastName\",\r\nc.display_name AS \"fullName\",\r\nc.mobile_no AS \"mobileNo\", CONCAT(REPEAT(\"..\", ((LENGTH(ounder.`hierarchy`) - LENGTH(\r\nREPLACE(ounder.`hierarchy`, \'.\', \'\')) - 1))), ounder.`name`) AS \"officeName\", \r\no.id AS \"officeNumber\"\r\nFROM m_office o\r\nJOIN m_office ounder ON ounder.hierarchy LIKE CONCAT(o.hierarchy, \'%\')\r\nJOIN m_client c ON c.office_id = ounder.id\r\nLEFT JOIN r_enum_value r ON r.enum_name = \'status_enum\' AND r.enum_id = c.status_enum\r\nWHERE o.id = ${officeId} AND c.status_enum = 300 AND (IFNULL(c.staff_id, -10) = ${loanOfficerId} OR \"-1\" = ${loanOfficerId})\r\nGROUP BY c.id\r\nORDER BY ounder.hierarchy, c.account_no','All clients with the status ‘Active’',0,1,0);
INSERT INTO `stretchy_report` VALUES (167,'Prospective Clients','SMS','NonTriggered','Client','SELECT c.id AS \"id\", \r\nc.firstname AS \"firstName\",\r\nc.middlename AS \"middleName\",\r\nc.lastname AS \"lastName\",\r\nc.display_name AS \"fullName\",\r\nc.mobile_no AS \"mobileNo\", CONCAT(REPEAT(\"..\", ((LENGTH(ounder.`hierarchy`) - LENGTH(\r\nREPLACE(ounder.`hierarchy`, \'.\', \'\')) - 1))), ounder.`name`) AS \"officeName\", \r\no.id AS \"officeNumber\"\r\nFROM m_office o\r\nJOIN m_office ounder ON ounder.hierarchy LIKE CONCAT(o.hierarchy, \'%\')\r\nJOIN m_client c ON c.office_id = ounder.id\r\nLEFT JOIN r_enum_value r ON r.enum_name = \'status_enum\' AND r.enum_id = c.status_enum\r\nLEFT JOIN m_loan l ON l.client_id = c.id\r\nWHERE o.id = ${officeId} AND c.status_enum = 300 AND (IFNULL(c.staff_id, -10) = ${loanOfficerId} OR \"-1\" = ${loanOfficerId}) AND l.client_id IS NULL\r\nGROUP BY c.id\r\nORDER BY ounder.hierarchy, c.account_no','All clients with the status ‘Active’ who have never had a loan before',0,1,0);
INSERT INTO `stretchy_report` VALUES (168,'Active Loan Clients','SMS','NonTriggered','Client','SELECT \r\nc.id AS \"id\", \r\nc.firstname AS \"firstName\",\r\nc.middlename AS \"middleName\",\r\nc.lastname AS \"lastName\",\r\nc.display_name AS \"fullName\",\r\nc.mobile_no AS \"mobileNo\", \r\nl.principal_amount AS \"loanAmount\", \r\n(IFNULL(l.principal_outstanding_derived, 0) + IFNULL(l.interest_outstanding_derived, 0) + IFNULL(l.fee_charges_outstanding_derived, 0) + IFNULL(l.penalty_charges_outstanding_derived, 0)) AS \"loanOutstanding\",\r\nl.principal_disbursed_derived AS \"loanDisbursed\",\r\nounder.id AS \"officeNumber\", \r\nl.account_no AS \"loanAccountId\", \r\ngua.lastname AS \"guarantorLastName\", COUNT(gua.id) AS \"numberOfGuarantors\",\r\ng.display_name AS \"groupName\"\r\n\r\nFROM m_office o\r\nJOIN m_office ounder ON ounder.hierarchy LIKE CONCAT(o.hierarchy, \'%\')\r\nJOIN m_client c ON c.office_id = ounder.id\r\nJOIN m_loan l ON l.client_id = c.id\r\nJOIN m_product_loan pl ON pl.id = l.product_id\r\nLEFT JOIN m_group_client gc ON gc.client_id = c.id\r\nLEFT JOIN m_group g ON g.id = gc.group_id\r\nLEFT JOIN m_staff lo ON lo.id = l.loan_officer_id\r\nLEFT JOIN m_currency cur ON cur.code = l.currency_code\r\nLEFT JOIN m_guarantor gua ON gua.loan_id = l.id\r\nWHERE o.id = ${officeId} AND (IFNULL(l.loan_officer_id, -10) = ${loanOfficerId} OR \"-1\" = ${loanOfficerId}) AND l.loan_status_id = 300 AND (DATEDIFF(CURDATE(), l.disbursedon_date) BETWEEN ${cycleX} AND ${cycleY})\r\nGROUP BY l.id\r\nORDER BY ounder.hierarchy, l.currency_code, c.account_no, l.account_no','All clients with an outstanding loan between cycleX and cycleY days',0,1,0);
INSERT INTO `stretchy_report` VALUES (169,'Loan in arrears','SMS','NonTriggered','Loan','SELECT \r\nmc.id AS \"id\", \r\nmc.firstname AS \"firstName\",\r\nmc.middlename AS \"middleName\",\r\nmc.lastname AS \"lastName\",\r\nmc.display_name AS \"fullName\",\r\nmc.mobile_no AS \"mobileNo\", \r\nml.principal_amount AS \"loanAmount\", \r\n(IFNULL(ml.principal_outstanding_derived, 0) + IFNULL(ml.interest_outstanding_derived, 0) + IFNULL(ml.fee_charges_outstanding_derived, 0) + IFNULL(ml.penalty_charges_outstanding_derived, 0)) AS \"loanOutstanding\",\r\nml.principal_disbursed_derived AS \"loanDisbursed\",\r\nlaa.overdue_since_date_derived AS \"paymentDueDate\",\r\nIFNULL(laa.total_overdue_derived, 0) AS \"totalDue\",\r\nounder.id AS \"officeNumber\", \r\nml.account_no AS \"loanAccountId\", \r\ngua.lastname AS \"guarantorLastName\", \r\nCOUNT(gua.id) AS \"numberOfGuarantors\",\r\ng.display_name AS \"groupName\"\r\n\r\nFROM m_office mo\r\nJOIN m_office ounder ON ounder.hierarchy LIKE CONCAT(mo.hierarchy, \'%\')\r\nINNER JOIN m_client mc ON mc.office_id=ounder.id\r\nINNER JOIN m_loan ml ON ml.client_id = mc.id\r\nINNER JOIN r_enum_value rev ON rev.enum_id=ml.loan_status_id AND rev.enum_name = \'loan_status_id\'\r\nINNER JOIN m_loan_arrears_aging laa ON laa.loan_id=ml.id\r\nLEFT JOIN m_currency cur ON cur.code = ml.currency_code\r\nLEFT JOIN m_group_client gc ON gc.client_id = mc.id\r\nLEFT JOIN m_group g ON g.id = gc.group_id\r\nLEFT JOIN m_staff lo ON lo.id = ml.loan_officer_id\r\nLEFT JOIN m_guarantor gua ON gua.loan_id = ml.id\r\nWHERE ml.loan_status_id=300 AND mo.id=${officeId} AND (IFNULL(ml.loan_officer_id, -10) = ${loanOfficerId} OR \"-1\" = ${loanOfficerId}) AND (DATEDIFF(CURDATE(), laa.overdue_since_date_derived) BETWEEN ${fromX} AND ${toY})\r\nGROUP BY ml.id\r\nORDER BY ounder.hierarchy, ml.currency_code, mc.account_no, ml.account_no','All clients with an outstanding loan in arrears between fromX and toY days',0,1,0);
INSERT INTO `stretchy_report` VALUES (170,'Loan payments due','SMS','NonTriggered','Loan','SELECT \r\ncl.id AS \"id\", \r\ncl.firstname AS \"firstName\",\r\ncl.middlename AS \"middleName\",\r\ncl.lastname AS \"lastName\",\r\ncl.display_name AS \"fullName\",\r\ncl.mobile_no AS \"mobileNo\", \r\nl.principal_amount AS \"loanAmount\",\r\nof.id AS \"officeNumber\",\r\n(IFNULL(l.principal_outstanding_derived, 0) + IFNULL(l.interest_outstanding_derived, 0) + IFNULL(l.fee_charges_outstanding_derived, 0) + IFNULL(l.penalty_charges_outstanding_derived, 0)) AS \"loanOutstanding\",\r\nl.principal_disbursed_derived AS \"loanDisbursed\",\r\nls.duedate AS \"paymentDueDate\",\r\n(IFNULL(SUM(ls.principal_amount),0) - IFNULL(SUM(ls.principal_writtenoff_derived),0)\r\n + IFNULL(SUM(ls.interest_amount),0) - IFNULL(SUM(ls.interest_writtenoff_derived),0) \r\n - IFNULL(SUM(ls.interest_waived_derived),0)\r\n + IFNULL(SUM(ls.fee_charges_amount),0) - IFNULL(SUM(ls.fee_charges_writtenoff_derived),0) \r\n - IFNULL(SUM(ls.fee_charges_waived_derived),0)\r\n + IFNULL(SUM(ls.penalty_charges_amount),0) - IFNULL(SUM(ls.penalty_charges_writtenoff_derived),0) \r\n - IFNULL(SUM(ls.penalty_charges_waived_derived),0)\r\n) AS \"totalDue\",\r\nlaa.total_overdue_derived AS \"totalOverdue\",\r\nl.account_no AS \"loanAccountId\",\r\ngua.lastname AS \"guarantorLastName\",\r\nCOUNT(gua.id) AS \"numberOfGuarantors\",\r\ngp.display_name AS \"groupName\"\r\n\r\nFROM m_office of\r\nLEFT JOIN m_client cl ON of.id = cl.office_id\r\nLEFT JOIN m_loan l ON cl.id = l.client_id\r\nLEFT JOIN m_group_client gc ON gc.client_id = cl.id\r\nLEFT JOIN m_group gp ON gp.id = l.group_id\r\nLEFT JOIN m_loan_repayment_schedule ls ON l.id = ls.loan_id\r\nLEFT JOIN m_guarantor gua ON gua.loan_id = l.id\r\nINNER JOIN m_loan_arrears_aging laa ON laa.loan_id=l.id\r\nWHERE of.id = ${officeId} AND (IFNULL(l.loan_officer_id, -10) = ${loanOfficerId} OR \"-1\" = ${loanOfficerId}) AND (DATEDIFF(CURDATE(), ls.duedate) BETWEEN ${fromX} AND ${toY}) \r\nAND (of.hierarchy LIKE CONCAT((\r\nSELECT ino.hierarchy\r\nFROM m_office ino\r\nWHERE ino.id = ${officeId}),\"%\"))\r\nGROUP BY l.id\r\nORDER BY of.hierarchy, l.currency_code, cl.account_no, l.account_no','All clients with an unpaid installment due on their loan between fromX and toY days',0,1,0);
INSERT INTO `stretchy_report` VALUES (171,'Dormant Prospects','SMS','NonTriggered','Client','SELECT c.id AS \"id\", CONCAT(REPEAT(\"..\", ((LENGTH(ounder.`hierarchy`) - LENGTH(\r\nREPLACE(ounder.`hierarchy`, \'.\', \'\')) - 1))), ounder.`name`) AS \"officeName\", \r\nc.firstname AS \"firstName\",\r\nc.middlename AS \"middleName\",\r\nc.lastname AS \"lastName\",\r\nc.display_name AS \"fullName\",\r\nc.mobile_no AS \"mobileNo\",  \r\no.id AS \"officeNumber\", \r\nTIMESTAMPDIFF(MONTH, c.activation_date, CURDATE()) AS \"dormant\"\r\nFROM m_office o\r\nJOIN m_office ounder ON ounder.hierarchy LIKE CONCAT(o.hierarchy, \'%\')\r\nJOIN m_client c ON c.office_id = ounder.id\r\nLEFT JOIN r_enum_value r ON r.enum_name = \'status_enum\' AND r.enum_id = c.status_enum\r\nLEFT JOIN m_loan l ON l.client_id = c.id\r\nWHERE o.id = ${officeId} AND c.status_enum = 300 AND (IFNULL(c.staff_id, -10) = ${loanOfficerId} OR \"-1\" = ${loanOfficerId}) AND l.client_id IS NULL AND (TIMESTAMPDIFF(MONTH, c.activation_date, CURDATE()) > 3)\r\nGROUP BY c.id\r\nORDER BY ounder.hierarchy, c.account_no','All individuals who have not yet received a loan but were also entered into the system more than 3 months',0,1,0);
INSERT INTO `stretchy_report` VALUES (172,'Active group leaders','SMS','NonTriggered','Client','SELECT c.id AS \"id\", \r\nc.firstname AS \"firstName\",\r\nc.middlename AS \"middleName\",\r\nc.lastname AS \"lastName\",\r\nc.display_name AS \"fullName\",\r\nc.mobile_no AS \"mobileNo\", CONCAT(REPEAT(\"..\", ((LENGTH(ounder.`hierarchy`) - LENGTH(\r\nREPLACE(ounder.`hierarchy`, \'.\', \'\')) - 1))), ounder.`name`) AS \"officeName\", \r\no.id AS \"officeNumber\"\r\nFROM m_office o\r\nJOIN m_office ounder ON ounder.hierarchy LIKE CONCAT(o.hierarchy, \'%\')\r\nJOIN m_group g ON g.office_id = ounder.id\r\nJOIN m_client c ON c.office_id = ounder.id\r\nLEFT JOIN m_group_client gc ON gc.group_id = g.id AND gc.client_id = c.id\r\nLEFT JOIN m_group_roles gr ON gr.group_id = g.id AND gr.client_id = c.id\r\nLEFT JOIN m_staff ms ON ms.id = c.staff_id\r\nLEFT JOIN r_enum_value r ON r.enum_name = \'status_enum\' AND r.enum_id = c.status_enum\r\nLEFT JOIN m_code_value cv ON cv.id = gr.role_cv_id\r\nLEFT JOIN m_code code ON code.id = cv.code_id\r\nWHERE o.id = ${officeId} AND g.status_enum = 300 AND c.status_enum = 300  AND (IFNULL(c.staff_id, -10) = ${loanOfficerId} OR \"-1\" = ${loanOfficerId}) AND code.code_name = \'GROUPROLE\' AND cv.code_value = \'Leader\'\r\nGROUP BY c.id\r\nORDER BY ounder.hierarchy, c.account_no','All active group chairmen',0,1,0);
INSERT INTO `stretchy_report` VALUES (173,'Loan payments due (Overdue Loans)','SMS','NonTriggered','Loan','SELECT \r\nmc.id AS \"id\", \r\nmc.firstname AS \"firstName\",\r\nmc.middlename AS \"middleName\",\r\nmc.lastname AS \"lastName\",\r\nmc.display_name AS \"fullName\",\r\nmc.mobile_no AS \"mobileNo\", \r\nml.principal_amount AS \"loanAmount\", \r\n(IFNULL(ml.principal_outstanding_derived, 0) + IFNULL(ml.interest_outstanding_derived, 0) + IFNULL(ml.fee_charges_outstanding_derived, 0) + IFNULL(ml.penalty_charges_outstanding_derived, 0)) AS \"loanOutstanding\",\r\nml.principal_disbursed_derived AS \"loanDisbursed\",\r\nlaa.overdue_since_date_derived AS \"paymentDueDate\",\r\n(IFNULL(SUM(ls.principal_amount),0) - IFNULL(SUM(ls.principal_writtenoff_derived),0)\r\n + IFNULL(SUM(ls.interest_amount),0) - IFNULL(SUM(ls.interest_writtenoff_derived),0) \r\n - IFNULL(SUM(ls.interest_waived_derived),0)\r\n + IFNULL(SUM(ls.fee_charges_amount),0) - IFNULL(SUM(ls.fee_charges_writtenoff_derived),0) \r\n - IFNULL(SUM(ls.fee_charges_waived_derived),0)\r\n + IFNULL(SUM(ls.penalty_charges_amount),0) - IFNULL(SUM(ls.penalty_charges_writtenoff_derived),0) \r\n - IFNULL(SUM(ls.penalty_charges_waived_derived),0)\r\n) AS \"totalDue\",\r\nlaa.total_overdue_derived AS \"totalOverdue\",\r\nounder.id AS \"officeNumber\", \r\nml.account_no AS \"loanAccountId\", \r\ngua.lastname AS \"guarantorLastName\", \r\nCOUNT(gua.id) AS \"numberOfGuarantors\",\r\ng.display_name AS \"groupName\"\r\n\r\nFROM m_office mo\r\nJOIN m_office ounder ON ounder.hierarchy LIKE CONCAT(mo.hierarchy, \'%\')\r\nINNER JOIN m_client mc ON mc.office_id=ounder.id\r\nINNER JOIN m_loan ml ON ml.client_id = mc.id\r\nINNER JOIN r_enum_value rev ON rev.enum_id=ml.loan_status_id AND rev.enum_name = \'loan_status_id\'\r\nINNER JOIN m_loan_arrears_aging laa ON laa.loan_id=ml.id\r\nLEFT JOIN m_loan_repayment_schedule ls ON ls.loan_id = ml.id\r\nLEFT JOIN m_currency cur ON cur.code = ml.currency_code\r\nLEFT JOIN m_group_client gc ON gc.client_id = mc.id\r\nLEFT JOIN m_group g ON g.id = gc.group_id\r\nLEFT JOIN m_staff lo ON lo.id = ml.loan_officer_id\r\nLEFT JOIN m_guarantor gua ON gua.loan_id = ml.id\r\nWHERE ml.loan_status_id=300 AND mo.id=${officeId} AND (IFNULL(ml.loan_officer_id, -10) = ${loanOfficerId} OR \"-1\" = ${loanOfficerId}) \r\nAND (DATEDIFF(CURDATE(), ls.duedate) BETWEEN ${fromX} AND ${toY})\r\nAND (DATEDIFF(CURDATE(), laa.overdue_since_date_derived) BETWEEN ${overdueX} AND ${overdueY})\r\nGROUP BY ml.id\r\nORDER BY ounder.hierarchy, ml.currency_code, mc.account_no, ml.account_no','Loan Payments Due between fromX to toY days for clients in arrears between overdueX and overdueY days',0,1,0);
INSERT INTO `stretchy_report` VALUES (174,'Loan payments received (Active Loans)','SMS','NonTriggered','Loan','SELECT \r\nmc.id AS \"id\", \r\nmc.firstname AS \"firstName\",\r\nmc.middlename AS \"middleName\",\r\nmc.lastname AS \"lastName\",\r\nmc.display_name AS \"fullName\",\r\nmc.mobile_no AS \"mobileNo\", \r\nml.principal_amount AS \"loanAmount\", \r\n(IFNULL(ml.principal_outstanding_derived, 0) + IFNULL(ml.interest_outstanding_derived, 0) + IFNULL(ml.fee_charges_outstanding_derived, 0) + IFNULL(ml.penalty_charges_outstanding_derived, 0)) AS \"loanOutstanding\",\r\nounder.id AS \"officeNumber\", \r\nml.account_no AS \"loanAccountNumber\",\r\nSUM(lt.amount) AS \"repaymentAmount\"\r\nFROM m_office mo\r\nJOIN m_office ounder ON ounder.hierarchy LIKE CONCAT(mo.hierarchy, \'%\')\r\nINNER JOIN m_client mc ON mc.office_id=ounder.id\r\nINNER JOIN m_loan ml ON ml.client_id = mc.id\r\nINNER JOIN r_enum_value rev ON rev.enum_id=ml.loan_status_id AND rev.enum_name = \'loan_status_id\'\r\nINNER JOIN m_loan_transaction lt ON lt.loan_id = ml.id\r\nINNER JOIN m_appuser au ON au.id = lt.createdby_id\r\nLEFT JOIN m_loan_arrears_aging laa ON laa.loan_id=ml.id\r\nLEFT JOIN m_payment_detail mpd ON mpd.id=lt.payment_detail_id\r\nLEFT JOIN m_currency cur ON cur.code = ml.currency_code\r\nLEFT JOIN m_group_client gc ON gc.client_id = mc.id\r\nLEFT JOIN m_group g ON g.id = gc.group_id\r\nLEFT JOIN m_staff lo ON lo.id = ml.loan_officer_id\r\nLEFT JOIN m_guarantor gua ON gua.loan_id = ml.id\r\nWHERE ml.loan_status_id=300 AND mo.id=${officeId} AND (IFNULL(ml.loan_officer_id, -10) = ${loanOfficerId} OR \"-1\" = ${loanOfficerId}) AND (DATEDIFF(CURDATE(), lt.transaction_date) BETWEEN ${fromX} AND ${toY}) AND lt.is_reversed=0 AND lt.transaction_type_enum=2 AND laa.loan_id IS NULL\r\nGROUP BY ml.id\r\nORDER BY ounder.hierarchy, ml.currency_code, mc.account_no, ml.account_no','Payments received in the last fromX to toY days for any loan with the status Active (on-time)',0,1,0);
INSERT INTO `stretchy_report` VALUES (175,'Loan payments received (Overdue Loans)','SMS','NonTriggered','Loan','SELECT \r\nml.id AS \"loanId\", \r\nmc.id AS \"id\", \r\nmc.firstname AS \"firstName\",\r\nmc.middlename AS \"middleName\",\r\nmc.lastname AS \"lastName\",\r\nmc.display_name AS \"fullName\",\r\nmc.mobile_no AS \"mobileNo\", \r\nml.principal_amount AS \"loanAmount\", \r\n(IFNULL(ml.principal_outstanding_derived, 0) + IFNULL(ml.interest_outstanding_derived, 0) + IFNULL(ml.fee_charges_outstanding_derived, 0) + IFNULL(ml.penalty_charges_outstanding_derived, 0)) AS \"loanOutstanding\",\r\nounder.id AS \"officeNumber\", \r\nml.account_no AS \"loanAccountNumber\",\r\nSUM(lt.amount) AS \"repaymentAmount\"\r\nFROM m_office mo\r\nJOIN m_office ounder ON ounder.hierarchy LIKE CONCAT(mo.hierarchy, \'%\')\r\nINNER JOIN m_client mc ON mc.office_id=ounder.id\r\nINNER JOIN m_loan ml ON ml.client_id = mc.id\r\nINNER JOIN r_enum_value rev ON rev.enum_id=ml.loan_status_id AND rev.enum_name = \'loan_status_id\'\r\nINNER JOIN m_loan_arrears_aging laa ON laa.loan_id=ml.id\r\nINNER JOIN m_loan_transaction lt ON lt.loan_id = ml.id\r\nINNER JOIN m_appuser au ON au.id = lt.created_by\r\nLEFT JOIN m_payment_detail mpd ON mpd.id=lt.payment_detail_id\r\nLEFT JOIN m_currency cur ON cur.code = ml.currency_code\r\nLEFT JOIN m_group_client gc ON gc.client_id = mc.id\r\nLEFT JOIN m_group g ON g.id = gc.group_id\r\nLEFT JOIN m_staff lo ON lo.id = ml.loan_officer_id\r\nLEFT JOIN m_guarantor gua ON gua.loan_id = ml.id\r\nWHERE ml.loan_status_id=300 AND mo.id=${officeId} AND (IFNULL(ml.loan_officer_id, -10) = ${loanOfficerId} OR \"-1\" = ${loanOfficerId}) AND (DATEDIFF(CURDATE(), lt.transaction_date) BETWEEN ${fromX} AND ${toY}) AND (DATEDIFF(CURDATE(), laa.overdue_since_date_derived) BETWEEN ${overdueX} AND ${overdueY}) AND lt.is_reversed=0 AND lt.transaction_type_enum=2\r\nGROUP BY ml.id\r\nORDER BY ounder.hierarchy, ml.currency_code, mc.account_no, ml.account_no','Payments received in the last fromX to toY days for any loan with the status Overdue (arrears) between overdueX and overdueY days',0,1,0);
INSERT INTO `stretchy_report` VALUES (176,'Happy Birthday','SMS','NonTriggered','Client','SELECT \r\nc.id AS \"id\", \r\nc.firstname AS \"firstName\",\r\nc.middlename AS \"middleName\",\r\nc.lastname AS \"lastName\",\r\nc.display_name AS \"fullName\",\r\nc.mobile_no AS \"mobileNo\", CONCAT(REPEAT(\"..\", ((LENGTH(ounder.`hierarchy`) - LENGTH(\r\nREPLACE(ounder.`hierarchy`, \'.\', \'\')) - 1))), ounder.`name`) AS \"officeName\", \r\no.id AS \"officeNumber\", \r\nc.date_of_birth AS \"dateOfBirth\",\r\nIF(c.date_of_birth IS NULL, 0, CEIL(DATEDIFF (NOW(), c.date_of_birth)/365)) AS \"age\"\r\nFROM m_office o\r\nJOIN m_office ounder ON ounder.hierarchy LIKE CONCAT(o.hierarchy, \'%\')\r\nJOIN m_client c ON c.office_id = ounder.id\r\nLEFT JOIN r_enum_value r ON r.enum_name = \'status_enum\' AND r.enum_id = c.status_enum\r\nLEFT JOIN m_staff ms ON ms.id = c.staff_id\r\nWHERE o.id = ${officeId} AND c.status_enum = 300 AND (IFNULL(c.staff_id, -10) = ${loanOfficerId} OR \"-1\" = ${loanOfficerId}) AND c.date_of_birth IS NOT NULL AND (DAY(c.date_of_birth)=DAY(NOW())) AND (MONTH(c.date_of_birth)=MONTH(NOW()))\r\nORDER BY ounder.hierarchy, c.account_no','This sends a message to all clients with the status Active on their Birthday',0,1,0);
INSERT INTO `stretchy_report` VALUES (177,'Loan fully repaid','SMS','NonTriggered','Loan','SELECT \r\nc.id AS \"id\", \r\nc.firstname AS \"firstName\",\r\nc.middlename AS \"middleName\",\r\nc.lastname AS \"lastName\",\r\nc.display_name AS \"fullName\",\r\nc.mobile_no AS \"mobileNo\", \r\nl.principal_amount AS \"loanAmount\",\r\n(IFNULL(l.principal_outstanding_derived, 0) + IFNULL(l.interest_outstanding_derived, 0) + IFNULL(l.fee_charges_outstanding_derived, 0) + IFNULL(l.penalty_charges_outstanding_derived, 0)) AS \"loanOutstanding\",\r\nl.principal_disbursed_derived AS \"loanDisbursed\",\r\no.id AS \"officeNumber\",\r\nl.account_no AS \"loanAccountId\",\r\ngua.lastname AS \"guarantorLastName\", COUNT(gua.id) AS \"numberOfGuarantors\",\r\nls.duedate AS \"dueDate\",\r\nlaa.total_overdue_derived AS \"totalDue\",\r\ngp.display_name AS \"groupName\",\r\nl.total_repayment_derived AS \"totalFullyPaid\"\r\nFROM m_office o\r\nJOIN m_office ounder ON ounder.hierarchy LIKE CONCAT(o.hierarchy, \'%\')\r\nJOIN m_client c ON c.office_id = ounder.id\r\nJOIN m_loan l ON l.client_id = c.id\r\nLEFT JOIN m_staff lo ON lo.id = l.loan_officer_id\r\nLEFT JOIN m_currency cur ON cur.code = l.currency_code\r\nLEFT JOIN m_group_client gc ON gc.client_id = c.id\r\nLEFT JOIN m_group gp ON gp.id = l.group_id\r\nLEFT JOIN m_loan_repayment_schedule ls ON l.id = ls.loan_id\r\nLEFT JOIN m_guarantor gua ON gua.loan_id = l.id\r\nLEFT JOIN m_loan_arrears_aging laa ON laa.loan_id=l.id\r\nWHERE o.id = ${officeId} AND (IFNULL(l.loan_officer_id, -10) = ${loanOfficerId} OR \"-1\" = ${loanOfficerId}) AND \r\n(DATEDIFF(CURDATE(), l.closedon_date) BETWEEN ${fromX} AND ${toY})\r\n AND (l.loan_status_id IN (600, 700))\r\nGROUP BY l.id\r\nORDER BY ounder.hierarchy, l.currency_code, c.account_no, l.account_no','All loans that have been fully repaid (Closed or Overpaid) in the last fromX to toY days',0,1,0);
INSERT INTO `stretchy_report` VALUES (178,'Loan outstanding after final instalment date','SMS','NonTriggered','Loan','SELECT \r\nc.id AS \"id\", \r\nc.firstname AS \"firstName\",\r\nc.middlename AS \"middleName\",\r\nc.lastname AS \"lastName\",\r\nc.display_name AS \"fullName\",\r\nc.mobile_no AS \"mobileNo\", \r\nl.principal_amount AS \"loanAmount\",\r\no.id AS \"officeNumber\",\r\n(IFNULL(l.principal_outstanding_derived, 0) + IFNULL(l.interest_outstanding_derived, 0) + IFNULL(l.fee_charges_outstanding_derived, 0) + IFNULL(l.penalty_charges_outstanding_derived, 0)) AS \"loanOutstanding\",\r\nl.principal_disbursed_derived AS \"loanDisbursed\",\r\nls.duedate AS \"paymentDueDate\",\r\n(IFNULL(SUM(ls.principal_amount),0) - IFNULL(SUM(ls.principal_writtenoff_derived),0)\r\n + IFNULL(SUM(ls.interest_amount),0) - IFNULL(SUM(ls.interest_writtenoff_derived),0) \r\n - IFNULL(SUM(ls.interest_waived_derived),0)\r\n + IFNULL(SUM(ls.fee_charges_amount),0) - IFNULL(SUM(ls.fee_charges_writtenoff_derived),0) \r\n - IFNULL(SUM(ls.fee_charges_waived_derived),0)\r\n + IFNULL(SUM(ls.penalty_charges_amount),0) - IFNULL(SUM(ls.penalty_charges_writtenoff_derived),0) \r\n - IFNULL(SUM(ls.penalty_charges_waived_derived),0)\r\n) AS \"totalDue\",\r\nlaa.total_overdue_derived AS \"totalOverdue\",\r\nl.account_no AS \"loanAccountId\",\r\ngua.lastname AS \"guarantorLastName\",\r\nCOUNT(gua.id) AS \"numberOfGuarantors\",\r\ngp.display_name AS \"groupName\"\r\n\r\nFROM m_office o\r\nJOIN m_office ounder ON ounder.hierarchy LIKE CONCAT(o.hierarchy, \'%\')\r\nJOIN m_client c ON c.office_id = ounder.id\r\nJOIN m_loan l ON l.client_id = c.id\r\nLEFT JOIN m_staff lo ON lo.id = l.loan_officer_id\r\nLEFT JOIN m_currency cur ON cur.code = l.currency_code\r\nLEFT JOIN m_loan_arrears_aging laa ON laa.loan_id = l.id\r\nLEFT JOIN m_group_client gc ON gc.client_id = c.id\r\nLEFT JOIN m_group gp ON gp.id = l.group_id\r\nLEFT JOIN m_loan_repayment_schedule ls ON l.id = ls.loan_id\r\nLEFT JOIN m_guarantor gua ON gua.loan_id = l.id\r\nWHERE o.id = ${officeId} AND (IFNULL(l.loan_officer_id, -10) = ${loanOfficerId} OR \"-1\" = ${loanOfficerId}) AND l.loan_status_id = 300 AND l.expected_maturedon_date < CURDATE() \r\nAND (DATEDIFF(CURDATE(), l.expected_maturedon_date) BETWEEN ${fromX} AND ${toY})\r\nGROUP BY l.id\r\nORDER BY ounder.hierarchy, l.currency_code, c.account_no, l.account_no','All active loans (with an outstanding balance) between fromX to toY days after the final instalment date on their loan schedule',0,1,0);
INSERT INTO `stretchy_report` VALUES (179,'Loan Repayment','SMS','Triggered',NULL,'select ml.id as loanId,mc.id, mc.firstname, ifnull(mc.middlename,\'\') as middlename, mc.lastname, mc.display_name as FullName, mobile_no as mobileNo, mc.group_name as GroupName, round(ml.principal_amount, ml.currency_digits) as LoanAmount, round(ml.`total_outstanding_derived`, ml.currency_digits) as LoanOutstanding,\nml.`account_no` as LoanAccountId, round(mlt.amountPaid, ml.currency_digits) as repaymentAmount\nFROM m_office mo\nJOIN m_office ounder ON ounder.hierarchy LIKE CONCAT(mo.hierarchy, \'%\')\nAND ounder.hierarchy like CONCAT(\'.\', \'%\')\nLEFT JOIN (\n select \n ml.id as loanId, \n ifnull(mc.id,mc2.id) as id, \n ifnull(mc.firstname,mc2.firstname) as firstname, \n ifnull(mc.middlename,ifnull(mc2.middlename,(\'\'))) as middlename, \n ifnull(mc.lastname,mc2.lastname) as lastname, \n ifnull(mc.display_name,mc2.display_name) as display_name, \n ifnull(mc.status_enum,mc2.status_enum) as status_enum,\n ifnull(mc.mobile_no,mc2.mobile_no) as mobile_no,\n ifnull(mg.office_id,mc2.office_id) as office_id,\n ifnull(mg.staff_id,mc2.staff_id) as staff_id,\n mg.id as group_id, \nmg.display_name as group_name\n from\n m_loan ml\n left join m_group mg on mg.id = ml.group_id\n left join m_group_client mgc on mgc.group_id = mg.id\n left join m_client mc on mc.id = mgc.client_id\n left join m_client mc2 on mc2.id = ml.client_id\n order by loanId\n ) mc on mc.office_id = ounder.id\nright join m_loan as ml on mc.loanId = ml.id\nright join(\nselect mlt.amount as amountPaid,mlt.id,mlt.loan_id\nfrom m_loan_transaction mlt\nwhere mlt.is_reversed = 0 \ngroup by mlt.loan_id\n) as mlt on mlt.loan_id = ml.id\nright join m_loan_repayment_schedule as mls1 on ml.id = mls1.loan_id and mls1.`completed_derived` = 0\nand mls1.installment = (SELECT MIN(installment) from m_loan_repayment_schedule where loan_id = ml.id and duedate <= CURDATE() and completed_derived=0)\nwhere mc.status_enum = 300 and mobile_no is not null and ml.`loan_status_id` = 300\nand (mo.id = ${officeId} or ${officeId} = -1)\nand (mc.staff_id = ${loanOfficerId} or ${loanOfficerId} = -1)\nand (ml.loan_type_enum = ${loanType} or ${loanType} = -1)\nand ml.id in (select mla.loan_id from m_loan_arrears_aging mla)\ngroup by ml.id','Loan Repayment',0,0,0);
INSERT INTO `stretchy_report` VALUES (180,'Loan Approved','SMS','Triggered',NULL,'SELECT mc.id, mc.firstname, mc.middlename as middlename, mc.lastname, mc.display_name as FullName, mc.mobile_no as mobileNo, mc.group_name as GroupName, mo.name as officename, ml.id as loanId, ml.account_no as accountnumber, ml.principal_amount_proposed as loanamount, ml.annual_nominal_interest_rate as annualinterestrate FROM m_office mo JOIN m_office ounder ON ounder.hierarchy LIKE CONCAT(mo.hierarchy, \'%\') AND ounder.hierarchy like CONCAT(\'.\', \'%\') LEFT JOIN ( select  ml.id as loanId,  ifnull(mc.id,mc2.id) as id,  ifnull(mc.firstname,mc2.firstname) as firstname,  ifnull(mc.middlename,ifnull(mc2.middlename,(\'\'))) as middlename,  ifnull(mc.lastname,mc2.lastname) as lastname,  ifnull(mc.display_name,mc2.display_name) as display_name,  ifnull(mc.status_enum,mc2.status_enum) as status_enum, ifnull(mc.mobile_no,mc2.mobile_no) as mobile_no, ifnull(mg.office_id,mc2.office_id) as office_id, ifnull(mg.staff_id,mc2.staff_id) as staff_id, mg.id as group_id, mg.display_name as group_name from m_loan ml left join m_group mg on mg.id = ml.group_id left join m_group_client mgc on mgc.group_id = mg.id left join m_client mc on mc.id = mgc.client_id left join m_client mc2 on mc2.id = ml.client_id order by loanId ) mc on mc.office_id = ounder.id  left join m_loan ml on ml.id = mc.loanId WHERE mc.status_enum = 300 and mc.mobile_no is not null and (mo.id = ${officeId} or ${officeId} = -1) and (mc.staff_id = ${loanOfficerId} or ${loanOfficerId} = -1)and (ml.id = ${loanId} or ${loanId} = -1)and (mc.id = ${clientId} or ${clientId} = -1)and (mc.group_id = ${groupId} or ${groupId} = -1)and (ml.loan_type_enum = ${loanType} or ${loanType} = -1)','Loan and client data of approved loan',0,0,0);
INSERT INTO `stretchy_report` VALUES (181,'Loan Rejected','SMS','Triggered',NULL,'SELECT mc.id, mc.firstname, mc.middlename as middlename, mc.lastname, mc.display_name as FullName, mc.mobile_no as mobileNo, mc.group_name as GroupName,  mo.name as officename, ml.id as loanId, ml.account_no as accountnumber, ml.principal_amount_proposed as loanamount, ml.annual_nominal_interest_rate as annualinterestrate  FROM  m_office mo  JOIN m_office ounder ON ounder.hierarchy LIKE CONCAT(mo.hierarchy, \'%\')  AND ounder.hierarchy like CONCAT(\'.\', \'%\')  LEFT JOIN (  select   ml.id as loanId,   ifnull(mc.id,mc2.id) as id,   ifnull(mc.firstname,mc2.firstname) as firstname,   ifnull(mc.middlename,ifnull(mc2.middlename,(\'\'))) as middlename,   ifnull(mc.lastname,mc2.lastname) as lastname,   ifnull(mc.display_name,mc2.display_name) as display_name,   ifnull(mc.status_enum,mc2.status_enum) as status_enum,  ifnull(mc.mobile_no,mc2.mobile_no) as mobile_no,  ifnull(mg.office_id,mc2.office_id) as office_id,  ifnull(mg.staff_id,mc2.staff_id) as staff_id,  mg.id as group_id,  mg.display_name as group_name  from  m_loan ml  left join m_group mg on mg.id = ml.group_id  left join m_group_client mgc on mgc.group_id = mg.id  left join m_client mc on mc.id = mgc.client_id  left join m_client mc2 on mc2.id = ml.client_id  order by loanId  ) mc on mc.office_id = ounder.id  left join m_loan ml on ml.id = mc.loanId  WHERE mc.status_enum = 300 and mc.mobile_no is not null  and (mo.id = ${officeId} or ${officeId} = -1)  and (mc.staff_id = ${loanOfficerId} or ${loanOfficerId} = -1) and (ml.id = ${loanId} or ${loanId} = -1) and (mc.id = ${clientId} or ${clientId} = -1) and (mc.group_id = ${groupId} or ${groupId} = -1)  and (ml.loan_type_enum = ${loanType} or ${loanType} = -1)','Loan and client data of rejected loan',0,0,0);
INSERT INTO `stretchy_report` VALUES (182,'Client Rejected','SMS','Triggered','Client','SELECT c.id AS \"id\", \r\nc.firstname AS \"firstName\",\r\nc.middlename AS \"middleName\",\r\nc.lastname AS \"lastName\",\r\nc.display_name AS \"fullName\",\r\nc.mobile_no AS \"mobileNo\", CONCAT(REPEAT(\"..\", ((LENGTH(ounder.`hierarchy`) - LENGTH(\r\nREPLACE(ounder.`hierarchy`, \'.\', \'\')) - 1))), ounder.`name`) AS \"officeName\", \r\no.id AS \"officeNumber\"\r\nFROM m_office o\r\nJOIN m_office ounder ON ounder.hierarchy LIKE CONCAT(o.hierarchy, \'%\')\r\nJOIN m_client c ON c.office_id = ounder.id\r\nLEFT JOIN r_enum_value r ON r.enum_name = \'status_enum\' AND r.enum_id = c.status_enum\r\nWHERE o.id = ${officeId} AND c.id = ${clientId} AND (IFNULL(c.staff_id, -10) = ${loanOfficerId} OR \"-1\" = ${loanOfficerId})','Client Rejection',0,1,0);
INSERT INTO `stretchy_report` VALUES (183,'Client Activated','SMS','Triggered','Client','SELECT c.id AS \"id\", \r\nc.firstname AS \"firstName\",\r\nc.middlename AS \"middleName\",\r\nc.lastname AS \"lastName\",\r\nc.display_name AS \"fullName\",\r\nc.mobile_no AS \"mobileNo\", CONCAT(REPEAT(\"..\", ((LENGTH(ounder.`hierarchy`) - LENGTH(\r\nREPLACE(ounder.`hierarchy`, \'.\', \'\')) - 1))), ounder.`name`) AS \"officeName\", \r\no.id AS \"officeNumber\"\r\nFROM m_office o\r\nJOIN m_office ounder ON ounder.hierarchy LIKE CONCAT(o.hierarchy, \'%\')\r\nJOIN m_client c ON c.office_id = ounder.id\r\nLEFT JOIN r_enum_value r ON r.enum_name = \'status_enum\' AND r.enum_id = c.status_enum\r\nWHERE o.id = ${officeId} AND c.id = ${clientId} AND (IFNULL(c.staff_id, -10) = ${loanOfficerId} OR \"-1\" = ${loanOfficerId})','Client Activation',0,1,0);
INSERT INTO `stretchy_report` VALUES (184,'Savings Rejected','SMS','Triggered','Savings','SELECT \r\nc.id AS \"id\",\r\nc.firstname AS \"firstName\",\r\nc.middlename AS \"middleName\",\r\nc.lastname AS \"lastName\",\r\nc.display_name AS \"fullName\",\r\nc.mobile_no AS \"mobileNo\",\r\ns.account_no AS \"savingsAccountNo\",\r\nounder.id AS \"officeNumber\",\r\nounder.name AS \"officeName\"\r\n\r\nFROM m_office o\r\nJOIN m_office ounder ON ounder.hierarchy LIKE CONCAT(o.hierarchy, \'%\')\r\nJOIN m_client c ON c.office_id = ounder.id\r\nJOIN m_savings_account s ON s.client_id = c.id\r\nJOIN m_savings_product sp ON sp.id = s.product_id\r\nLEFT JOIN m_staff st ON st.id = s.field_officer_id\r\nLEFT JOIN m_currency cur ON cur.code = s.currency_code\r\nWHERE o.id = ${officeId} AND (IFNULL(s.field_officer_id, -10) = ${loanOfficerId} OR \"-1\" = ${loanOfficerId}) AND s.id = ${savingsId}','Savings Rejected',0,1,0);
INSERT INTO `stretchy_report` VALUES (185,'Savings Activated','SMS','Triggered','Savings','SELECT \r\nc.id AS \"id\",\r\nc.firstname AS \"firstName\",\r\nc.middlename AS \"middleName\",\r\nc.lastname AS \"lastName\",\r\nc.display_name AS \"fullName\",\r\nc.mobile_no AS \"mobileNo\",\r\ns.account_no AS \"savingsAccountNo\",\r\nounder.id AS \"officeNumber\",\r\nounder.name AS \"officeName\"\r\n\r\nFROM m_office o\r\nJOIN m_office ounder ON ounder.hierarchy LIKE CONCAT(o.hierarchy, \'%\')\r\nJOIN m_client c ON c.office_id = ounder.id\r\nJOIN m_savings_account s ON s.client_id = c.id\r\nJOIN m_savings_product sp ON sp.id = s.product_id\r\nLEFT JOIN m_staff st ON st.id = s.field_officer_id\r\nLEFT JOIN m_currency cur ON cur.code = s.currency_code\r\nWHERE o.id = ${officeId} AND (IFNULL(s.field_officer_id, -10) = ${loanOfficerId} OR \"-1\" = ${loanOfficerId}) AND s.id = ${savingsId}','Savings Activation',0,1,0);
INSERT INTO `stretchy_report` VALUES (186,'Savings Deposit','SMS','Triggered',NULL,'SELECT sc.savingsId AS savingsId, sc.id AS clientId, sc.firstname, IFNULL(sc.middlename,\'\') AS middlename, sc.lastname, sc.display_name AS FullName, sc.mobile_no AS mobileNo,\r\nms.`account_no` AS savingsAccountNo, ROUND(mst.amountPaid, ms.currency_digits) AS depositAmount, ms.account_balance_derived AS balance, \r\nmst.transactionDate AS transactionDate\r\nFROM m_office mo\r\nJOIN m_office ounder ON ounder.hierarchy LIKE CONCAT(mo.hierarchy, \'%\') AND ounder.hierarchy LIKE CONCAT(\'.\', \'%\')\r\nLEFT JOIN (\r\nSELECT \r\n sa.id AS savingsId, mc.id AS id, mc.firstname AS firstname, mc.middlename AS middlename, mc.lastname AS lastname, \r\n mc.display_name AS display_name, mc.status_enum AS status_enum, \r\n mc.mobile_no AS mobile_no, mc.office_id AS office_id, \r\n mc.staff_id AS staff_id\r\nFROM\r\nm_savings_account sa\r\nLEFT JOIN m_client mc ON mc.id = sa.client_id\r\nORDER BY savingsId) sc ON sc.office_id = ounder.id\r\nRIGHT JOIN m_savings_account AS ms ON sc.savingsId = ms.id\r\nRIGHT JOIN(\r\nSELECT st.amount AS amountPaid, st.id, st.savings_account_id, st.id AS savingsTransactionId, st.transaction_date AS transactionDate\r\nFROM m_savings_account_transaction st\r\nWHERE st.is_reversed = 0\r\nGROUP BY st.savings_account_id\r\n) AS mst ON mst.savings_account_id = ms.id\r\nWHERE sc.mobile_no IS NOT NULL AND (mo.id = ${officeId} OR ${officeId} = -1) AND (sc.staff_id = ${loanOfficerId} OR ${loanOfficerId} = -1) AND mst.savingsTransactionId = ${savingsTransactionId}','Savings Deposit',0,1,0);
INSERT INTO `stretchy_report` VALUES (187,'Savings Withdrawal','SMS','Triggered',NULL,'SELECT sc.savingsId AS savingsId, sc.id AS clientId, sc.firstname, IFNULL(sc.middlename,\'\') AS middlename, sc.lastname, sc.display_name AS FullName, sc.mobile_no AS mobileNo,\r\nms.`account_no` AS savingsAccountNo, ROUND(mst.amountPaid, ms.currency_digits) AS withdrawAmount, ms.account_balance_derived AS balance, \r\nmst.transactionDate AS transactionDate\r\nFROM m_office mo\r\nJOIN m_office ounder ON ounder.hierarchy LIKE CONCAT(mo.hierarchy, \'%\') AND ounder.hierarchy LIKE CONCAT(\'.\', \'%\')\r\nLEFT JOIN (\r\nSELECT \r\n sa.id AS savingsId, mc.id AS id, mc.firstname AS firstname, mc.middlename AS middlename, mc.lastname AS lastname, \r\n mc.display_name AS display_name, mc.status_enum AS status_enum, \r\n mc.mobile_no AS mobile_no, mc.office_id AS office_id, \r\n mc.staff_id AS staff_id\r\nFROM\r\nm_savings_account sa\r\nLEFT JOIN m_client mc ON mc.id = sa.client_id\r\nORDER BY savingsId) sc ON sc.office_id = ounder.id\r\nRIGHT JOIN m_savings_account AS ms ON sc.savingsId = ms.id\r\nRIGHT JOIN(\r\nSELECT st.amount AS amountPaid, st.id, st.savings_account_id, st.id AS savingsTransactionId, st.transaction_date AS transactionDate\r\nFROM m_savings_account_transaction st\r\nWHERE st.is_reversed = 0\r\nGROUP BY st.savings_account_id\r\n) AS mst ON mst.savings_account_id = ms.id\r\nWHERE sc.mobile_no IS NOT NULL AND (mo.id = ${officeId} OR ${officeId} = -1) AND (sc.staff_id = ${loanOfficerId} OR ${loanOfficerId} = -1) AND mst.savingsTransactionId = ${savingsTransactionId}','Savings Withdrawal',0,1,0);
INSERT INTO `stretchy_report` VALUES (188,'ReportCategoryList','Table',NULL,'(NULL)','(NULL)','(NULL)',1,1,0);
INSERT INTO `stretchy_report` VALUES (189,'FullReportList','Table',NULL,'(NULL)','(NULL)','(NULL)',1,1,0);
INSERT INTO `stretchy_report` VALUES (190,'Loan Approved - Email','Email','Triggered',NULL,'select  ml.id as loanId,  ifnull(mc.id,mc2.id) as id,  ifnull(mc.firstname,mc2.firstname) as firstname,  \nifnull(mc.middlename,ifnull(mc2.middlename,(\'\'))) as middlename,  ifnull(mc.lastname,mc2.lastname) as lastname,  \nifnull(mc.display_name,mc2.display_name) as display_name,  ifnull(mc.status_enum,mc2.status_enum) as status_enum, \nifnull(mc.mobile_no,mc2.mobile_no) as mobile_no, ifnull(mg.office_id,mc2.office_id) as office_id, ifnull(mg.staff_id,mc2.staff_id) as staff_id, \nmg.id as group_id, mg.display_name as group_name, ifnull(mc.email_address,mc2.email_address) as emailAddress\nfrom m_loan ml left join m_group mg on mg.id = ml.group_id \nleft join m_group_client mgc on mgc.group_id = mg.id \nleft join m_client mc on mc.id = mgc.client_id \nleft join m_client mc2 on mc2.id = ml.client_id\nWHERE (mc.status_enum = 300 or mc2.status_enum = 300) and (mc.email_address is not null or mc2.email_address is not null) and ml.id = ${loanId}\n','Loan and client data of approved loan',0,1,0);
INSERT INTO `stretchy_report` VALUES (191,'Loan Rejected - Email','Email','Triggered',NULL,'select  ml.id as loanId,  ifnull(mc.id,mc2.id) as id,  ifnull(mc.firstname,mc2.firstname) as firstname,  \nifnull(mc.middlename,ifnull(mc2.middlename,(\'\'))) as middlename,  ifnull(mc.lastname,mc2.lastname) as lastname,  \nifnull(mc.display_name,mc2.display_name) as display_name,  ifnull(mc.status_enum,mc2.status_enum) as status_enum, \nifnull(mc.mobile_no,mc2.mobile_no) as mobile_no, ifnull(mg.office_id,mc2.office_id) as office_id, ifnull(mg.staff_id,mc2.staff_id) as staff_id, \nmg.id as group_id, mg.display_name as group_name, ifnull(mc.email_address,mc2.email_address) as emailAddress\nfrom m_loan ml left join m_group mg on mg.id = ml.group_id \nleft join m_group_client mgc on mgc.group_id = mg.id \nleft join m_client mc on mc.id = mgc.client_id \nleft join m_client mc2 on mc2.id = ml.client_id\nWHERE (mc.status_enum = 300 or mc2.status_enum = 300) and (mc.email_address is not null or mc2.email_address is not null) and ml.id = ${loanId}\n','Loan and client data of rejected loan',0,1,0);
INSERT INTO `stretchy_report` VALUES (192,'Loan Repayment - Email','Email','Triggered',NULL,'select  ml.id as loanId,  ifnull(mc.id,mc2.id) as id,  ifnull(mc.firstname,mc2.firstname) as firstname,  \nifnull(mc.middlename,ifnull(mc2.middlename,(\'\'))) as middlename,  ifnull(mc.lastname,mc2.lastname) as lastname,  \nifnull(mc.display_name,mc2.display_name) as display_name,  ifnull(mc.status_enum,mc2.status_enum) as status_enum, \nifnull(mc.mobile_no,mc2.mobile_no) as mobile_no, ifnull(mg.office_id,mc2.office_id) as office_id, ifnull(mg.staff_id,mc2.staff_id) as staff_id, \nmg.id as group_id, mg.display_name as group_name, ifnull(mc.email_address,mc2.email_address) as emailAddress, lt.amount as repaymentAmount \nfrom m_loan_transaction lt join m_loan ml on ml.id=lt.loan_id left join m_group mg on mg.id = ml.group_id \nleft join m_group_client mgc on mgc.group_id = mg.id \nleft join m_client mc on mc.id = mgc.client_id \nleft join m_client mc2 on mc2.id = ml.client_id\nWHERE (mc.status_enum = 300 or mc2.status_enum = 300) and (mc.email_address is not null or mc2.email_address is not null) and ml.id = ${loanId} and lt.id = ${loanTransactionId}\n','Loan and client data of rejected loan',0,1,0);
INSERT INTO `stretchy_report` VALUES (193,'Trial Balance Table','Table',NULL,'Accounting','select * from (select debits.glcode as \'glcode\',  debits.name as \'name\', IF(debits.type = 1 or debits.type = 5,  ifnull(debits.debitamount,0)-ifnull(credits.creditamount,0),null) as \'debit\',  IF(debits.type = 4 or debits.type = 3 or debits.type = 2,  ifnull(credits.creditamount,0)-ifnull(debits.debitamount,0),null) as \'credit\' from (select acc_gl_account.gl_code as \'glcode\', name,sum(amount) as \'debitamount\', acc_gl_account.classification_enum as \'type\' from acc_gl_journal_entry,acc_gl_account where acc_gl_account.id = acc_gl_journal_entry.account_id and acc_gl_journal_entry.type_enum=2 and acc_gl_journal_entry.entry_date between date(\'${startDate}\') and date(\'${endDate}\') and (acc_gl_journal_entry.office_id= ${officeId} or ${officeId}=1) group by glcode order by glcode) debits LEFT OUTER JOIN (select acc_gl_account.gl_code as \'glcode\', name as \'name\', sum(amount) as \'creditamount\', acc_gl_account.classification_enum as \'type\' from acc_gl_journal_entry,acc_gl_account where acc_gl_account.id = acc_gl_journal_entry.account_id and acc_gl_journal_entry.type_enum=1 and acc_gl_journal_entry.entry_date between date(\'${startDate}\') and date(\'${endDate}\') and (acc_gl_journal_entry.office_id= ${officeId} or ${officeId}=1) group by glcode order by glcode) credits on debits.glcode=credits.glcode union select credits.glcode as \'glcode\',  credits.name as \'name\', IF(credits.type = 1 or credits.type = 5,  ifnull(debits.debitamount,0)-ifnull(credits.creditamount,0),null) as \'debit\',  IF(credits.type = 4 or credits.type = 3 or credits.type = 2,  ifnull(credits.creditamount,0)-ifnull(debits.debitamount,0),null) as \'credit\' from (select acc_gl_account.gl_code as \'glcode\', name, sum(amount) as \'debitamount\', acc_gl_account.classification_enum as \'type\' from acc_gl_journal_entry,acc_gl_account where acc_gl_account.id = acc_gl_journal_entry.account_id and acc_gl_journal_entry.type_enum=2 and acc_gl_journal_entry.entry_date between date(\'${startDate}\') and date(\'${endDate}\') and (acc_gl_journal_entry.office_id= ${officeId} or ${officeId}=1) group by glcode order by glcode) debits RIGHT OUTER JOIN (select acc_gl_account.gl_code as \'glcode\',name as \'name\', sum(amount) as \'creditamount\', acc_gl_account.classification_enum as \'type\' from acc_gl_journal_entry,acc_gl_account where acc_gl_account.id = acc_gl_journal_entry.account_id and acc_gl_journal_entry.type_enum=1 and acc_gl_journal_entry.entry_date between date(\'${startDate}\') and date(\'${endDate}\') and (acc_gl_journal_entry.office_id= ${officeId} or ${officeId}=1) group by glcode order by glcode) credits on debits.glcode=credits.glcode) as fullouterjoinresult order by glcode ','Trial Balance Report',1,1,0);
INSERT INTO `stretchy_report` VALUES (194,'GeneralLedgerReport Table','Table',NULL,'Accounting','select details.edate entry_date, details.account_name account_name, sum(details.debit_amount) debit_amount, sum(details.credit_amount) credit_amount, details.description, ifnull(opb.openingbalance, 0) openingbalance, if(details.manual_entry = 1, details.id, \'0system\') transtype, if(actype in (1, 5), (sum(details.debit_amount) - sum(details.credit_amount)), (sum(details.credit_amount) - sum(details.debit_amount))) as cumulative_sum from ( select a.account_id acid1 , concat(gl.gl_code, \'-\', gl.name) as report_header , gl.classification_enum actype , gl.gl_code as reportid , j1.entry_date edate , concat(gl1.gl_code, \'-\', gl1.name) as account_name , if (j1.type_enum = 1, j1.amount, 0) as debit_amount , if (j1.type_enum = 2, j1.amount , 0) as credit_amount , j1.id , j1.office_id , j1.transaction_id , j1.type_enum , j1.office_running_balance as aftertxn , j1.description as description , j1.transaction_id as transactionid , a.manual_entry from acc_gl_journal_entry j1 inner join ( select distinct je.transaction_id tid, je.account_id, je.manual_entry from m_office o left join m_office ounder on ounder.hierarchy like concat(o.hierarchy, \'%\') inner join acc_gl_journal_entry je on je.office_id = ounder.id where je.account_id = ${GLAccountNO} and o.id = ${officeId} and je.entry_date between \'${startDate}\' and \'${endDate}\')a on a.tid = j1.transaction_id and j1.account_id <> ${GLAccountNO} left join acc_gl_account gl on gl.id = a.account_id left join acc_gl_account gl1 on gl1.id = j1.account_id order by j1.entry_date, j1.id) details left join ( select je.account_id acid2, if(aga1.classification_enum in (1, 5), (sum(if(je.type_enum = 2, ifnull(je.amount, 0), 0))- sum(if(je.type_enum = 1, ifnull(je.amount, 0), 0))), (sum(if(je.type_enum = 1, ifnull(je.amount, 0), 0))- sum(if(je.type_enum = 2, ifnull(je.amount, 0), 0)))) openingbalance from m_office o left join m_office ounder on ounder.hierarchy like concat(o.hierarchy, \'%\') left join acc_gl_journal_entry je on je.office_id = ounder.id left join acc_gl_account aga1 on aga1.id = je.account_id where je.entry_date >= DATE_SUB(\'${startDate}\', INTERVAL 2 day) and je.office_running_balance is not null and (o.id = ${officeId}) and je.account_id = ${GLAccountNO} group by je.account_id)opb on opb.acid2 = details.acid1 left join ( select name branchname from m_office mo where mo.id = 1)branch on details.office_id = ${officeId} group by details.edate, details.acid1, details.report_header, details.reportid, details.account_name, branch.branchname , transtype, details.description, openingbalance ',NULL,0,1,0);
INSERT INTO `stretchy_report` VALUES (195,'Income Statement Table','Table',NULL,'Accounting','(select * from ( select debits.glcode as \'glcode\', debits.name as \'name\',  \'Expense\'as IncomeOrExpense, (ifnull(debits.debitamount,0)-ifnull(credits.creditamount,0)) as \'balance\' from (select acc_gl_account.gl_code as \'glcode\',name,sum(amount) as \'debitamount\' from acc_gl_journal_entry,acc_gl_account where acc_gl_account.id = acc_gl_journal_entry.account_id and acc_gl_journal_entry.type_enum=2 and acc_gl_account.classification_enum in (5) and acc_gl_journal_entry.entry_date between date(\'${startDate}\') and date(\'${endDate}\') and (acc_gl_journal_entry.office_id= ${officeId} or ${officeId}=1) group by gl_code order by glcode) debits LEFT OUTER JOIN (select acc_gl_account.gl_code as \'glcode\',name,sum(amount) as \'creditamount\' from acc_gl_journal_entry,acc_gl_account where acc_gl_account.id = acc_gl_journal_entry.account_id and acc_gl_journal_entry.type_enum=1 and acc_gl_account.classification_enum in (5) and acc_gl_journal_entry.entry_date between date(\'${startDate}\') and date(\'${endDate}\') and (acc_gl_journal_entry.office_id= ${officeId} or ${officeId}=1) group by gl_code) credits on debits.glcode=credits.glcode union select credits.glcode as \'glcode\', credits.name as \'name\',  \'Expense\'as IncomeOrExpense, (ifnull(debits.debitamount,0)-ifnull(credits.creditamount,0)) as \'balance\' from (select acc_gl_account.gl_code as \'glcode\',name,sum(amount) as \'debitamount\' from acc_gl_journal_entry,acc_gl_account where acc_gl_account.id = acc_gl_journal_entry.account_id and acc_gl_journal_entry.type_enum=2 and acc_gl_account.classification_enum in (5) and acc_gl_journal_entry.entry_date between date(\'${startDate}\') and date(\'${endDate}\') and (acc_gl_journal_entry.office_id= ${officeId} or ${officeId}=1) group by gl_code order by glcode) debits RIGHT OUTER JOIN (select acc_gl_account.gl_code as \'glcode\',name as \'name\',sum(amount) as \'creditamount\' from acc_gl_journal_entry,acc_gl_account where acc_gl_account.id = acc_gl_journal_entry.account_id and acc_gl_journal_entry.type_enum=1 and acc_gl_account.classification_enum in (5) and acc_gl_journal_entry.entry_date between date(\'${startDate}\') and date(\'${endDate}\') and (acc_gl_journal_entry.office_id= ${officeId} or ${officeId}=1) group by gl_code order by glcode) credits on debits.glcode=credits.glcode)as fullouterjoinresult order by glcode) UNION  (select * from ( select debits.glcode as \'glcode\',  debits.name as \'name\',  \'Income\' as IncomeOrExpense, (ifnull(credits.creditamount,0)-ifnull(debits.debitamount,0)) as \'balance\' from (select acc_gl_account.gl_code as \'glcode\', name, sum(amount) as \'debitamount\' from acc_gl_journal_entry,acc_gl_account where acc_gl_account.id = acc_gl_journal_entry.account_id and acc_gl_journal_entry.type_enum=2 and acc_gl_account.classification_enum in (4) and acc_gl_journal_entry.entry_date between date(\'${startDate}\') and date(\'${endDate}\') and (acc_gl_journal_entry.office_id= ${officeId} or ${officeId}=1) group by glcode order by glcode) debits LEFT OUTER JOIN (select acc_gl_account.gl_code as \'glcode\',name,sum(amount) as \'creditamount\' from acc_gl_journal_entry,acc_gl_account where acc_gl_account.id = acc_gl_journal_entry.account_id and acc_gl_journal_entry.type_enum=1 and acc_gl_account.classification_enum in (4) and acc_gl_journal_entry.entry_date between date(\'${startDate}\') and date(\'${endDate}\') and (acc_gl_journal_entry.office_id= ${officeId} or ${officeId}=1) group by glcode order by glcode) credits on debits.glcode=credits.glcode union select credits.glcode as \'glcode\', credits.name as \'name\',  \'Income\' as IncomeOrExpense, (ifnull(credits.creditamount,0)-ifnull(debits.debitamount,0)) as \'balance\' from (select acc_gl_account.gl_code as \'glcode\',name,sum(amount) as \'debitamount\' from acc_gl_journal_entry,acc_gl_account where acc_gl_account.id = acc_gl_journal_entry.account_id and acc_gl_journal_entry.type_enum=2 and acc_gl_account.classification_enum in (4) and acc_gl_journal_entry.entry_date between date(\'${startDate}\') and date(\'${endDate}\') and (acc_gl_journal_entry.office_id= ${officeId} or ${officeId}=1) group by glcode order by glcode) debits RIGHT OUTER JOIN (select acc_gl_account.gl_code as \'glcode\',name as \'name\',sum(amount) as \'creditamount\' from acc_gl_journal_entry,acc_gl_account where acc_gl_account.id = acc_gl_journal_entry.account_id and acc_gl_journal_entry.type_enum=1 and acc_gl_account.classification_enum in (4) and acc_gl_journal_entry.entry_date between date(\'${startDate}\') and date(\'${endDate}\') and (acc_gl_journal_entry.office_id= ${officeId} or ${officeId}=1) group by glcode order by glcode) credits on debits.glcode=credits.glcode)as fullouterjoinresult order by glcode)','Profit and Loss Statement',1,1,0);
INSERT INTO `stretchy_report` VALUES (196,'Balance Sheet Table','Table',NULL,'Accounting','( select debits.glcode as \'glcode\', debits.name as \'name\', \'Assets\' as BalanceType, ( ifnull(debits.debitamount, 0)- ifnull(credits.creditamount, 0) ) as \'balance\' from ( select acc_gl_account.gl_code as \'glcode\', name, sum(amount) as \'debitamount\' from acc_gl_journal_entry, acc_gl_account where acc_gl_account.id = acc_gl_journal_entry.account_id and acc_gl_journal_entry.type_enum = 2 and acc_gl_account.classification_enum in (1) and acc_gl_journal_entry.entry_date <= date(\'${endDate}\') and ( acc_gl_journal_entry.office_id = ${officeId} or ${officeId} = 1 ) group by glcode order by glcode ) debits LEFT OUTER JOIN ( select acc_gl_account.gl_code as \'glcode\', name, sum(amount) as \'creditamount\' from acc_gl_journal_entry, acc_gl_account where acc_gl_account.id = acc_gl_journal_entry.account_id and acc_gl_journal_entry.type_enum = 1 and acc_gl_account.classification_enum in (1) and acc_gl_journal_entry.entry_date <= date(\'${endDate}\') and ( acc_gl_journal_entry.office_id = ${officeId} or ${officeId} = 1 ) group by glcode order by glcode ) credits on debits.glcode = credits.glcode ) union ( select credits.glcode as \'glcode\', credits.name as \'name\', \'Assets\' as BalanceType, ( ifnull(debits.debitamount, 0)- ifnull(credits.creditamount, 0) ) as \'balance\' from ( select acc_gl_account.gl_code as \'glcode\', name, sum(amount) as \'debitamount\' from acc_gl_journal_entry, acc_gl_account where acc_gl_account.id = acc_gl_journal_entry.account_id and acc_gl_journal_entry.type_enum = 2 and acc_gl_account.classification_enum in (1) and acc_gl_journal_entry.entry_date <= date(\'${endDate}\') and ( acc_gl_journal_entry.office_id = ${officeId} or ${officeId} = 1 ) group by glcode order by glcode ) debits RIGHT OUTER JOIN ( select acc_gl_account.gl_code as \'glcode\', name, sum(amount) as \'creditamount\' from acc_gl_journal_entry, acc_gl_account where acc_gl_account.id = acc_gl_journal_entry.account_id and acc_gl_journal_entry.type_enum = 1 and acc_gl_account.classification_enum in (1) and acc_gl_journal_entry.entry_date <= date(\'${endDate}\') and ( acc_gl_journal_entry.office_id = ${officeId} or ${officeId} = 1 ) group by glcode order by glcode ) credits on debits.glcode = credits.glcode ) UNION ( select debits.glcode as \'glcode\', debits.name as \'name\', \'Liability\' as BalanceType, ( ifnull(credits.creditamount, 0)- ifnull(debits.debitamount, 0) ) as \'balance\' from ( select acc_gl_account.gl_code as \'glcode\', name, sum(amount) as \'debitamount\' from acc_gl_journal_entry, acc_gl_account where acc_gl_account.id = acc_gl_journal_entry.account_id and acc_gl_journal_entry.type_enum = 2 and acc_gl_account.classification_enum in (2) and acc_gl_journal_entry.entry_date <= date(\'${endDate}\') and ( acc_gl_journal_entry.office_id = ${officeId} or ${officeId} = 1 ) group by glcode order by glcode ) debits LEFT OUTER JOIN ( select acc_gl_account.gl_code as \'glcode\', name, sum(amount) as \'creditamount\' from acc_gl_journal_entry, acc_gl_account where acc_gl_account.id = acc_gl_journal_entry.account_id and acc_gl_journal_entry.type_enum = 1 and acc_gl_account.classification_enum in (2) and acc_gl_journal_entry.entry_date <= date(\'${endDate}\') and ( acc_gl_journal_entry.office_id = ${officeId} or ${officeId} = 1 ) group by glcode order by glcode ) credits on debits.glcode = credits.glcode ) union ( select credits.glcode as \'glcode\', credits.name as \'name\', \'Liability\' as BalanceType, ( ifnull(credits.creditamount, 0)- ifnull(debits.debitamount, 0) ) as \'balance\' from ( select acc_gl_account.gl_code as \'glcode\', name, sum(amount) as \'debitamount\' from acc_gl_journal_entry, acc_gl_account where acc_gl_account.id = acc_gl_journal_entry.account_id and acc_gl_journal_entry.type_enum = 2 and acc_gl_account.classification_enum in (2) and acc_gl_journal_entry.entry_date <= date(\'${endDate}\') and ( acc_gl_journal_entry.office_id = ${officeId} or ${officeId} = 1 ) group by glcode order by glcode ) debits RIGHT OUTER JOIN ( select acc_gl_account.gl_code as \'glcode\', name, sum(amount) as \'creditamount\' from acc_gl_journal_entry, acc_gl_account where acc_gl_account.id = acc_gl_journal_entry.account_id and acc_gl_journal_entry.type_enum = 1 and acc_gl_account.classification_enum in (2) and acc_gl_journal_entry.entry_date <= date(\'${endDate}\') and ( acc_gl_journal_entry.office_id = ${officeId} or ${officeId} = 1 ) group by glcode order by glcode ) credits on debits.glcode = credits.glcode ) UNION ( select debits.glcode as \'glcode\', debits.name as \'name\', \'Equity\' as BalanceType, ( ifnull(credits.creditamount, 0)- ifnull(debits.debitamount, 0) ) as \'balance\' from ( select acc_gl_account.gl_code as \'glcode\', name, sum(amount) as \'debitamount\' from acc_gl_journal_entry, acc_gl_account where acc_gl_account.id = acc_gl_journal_entry.account_id and acc_gl_journal_entry.type_enum = 2 and acc_gl_account.classification_enum in (3) and acc_gl_journal_entry.entry_date <= date(\'${endDate}\') and ( acc_gl_journal_entry.office_id = ${officeId} or ${officeId} = 1 ) group by glcode order by glcode ) debits LEFT OUTER JOIN ( select acc_gl_account.gl_code as \'glcode\', name, sum(amount) as \'creditamount\' from acc_gl_journal_entry, acc_gl_account where acc_gl_account.id = acc_gl_journal_entry.account_id and acc_gl_journal_entry.type_enum = 1 and acc_gl_account.classification_enum in (3) and acc_gl_journal_entry.entry_date <= date(\'${endDate}\') and ( acc_gl_journal_entry.office_id = ${officeId} or ${officeId} = 1 ) group by glcode order by glcode ) credits on debits.glcode = credits.glcode ) UNION ( select credits.glcode as \'glcode\', credits.name as \'name\', \'Equity\' as BalanceType, ( ifnull(credits.creditamount, 0)- ifnull(debits.debitamount, 0) ) as \'balance\' from ( select acc_gl_account.gl_code as \'glcode\', name, sum(amount) as \'debitamount\' from acc_gl_journal_entry, acc_gl_account where acc_gl_account.id = acc_gl_journal_entry.account_id and acc_gl_journal_entry.type_enum = 2 and acc_gl_account.classification_enum in (3) and acc_gl_journal_entry.entry_date <= date(\'${endDate}\') and ( acc_gl_journal_entry.office_id = ${officeId} or ${officeId} = 1 ) group by glcode order by glcode ) debits RIGHT OUTER JOIN ( select acc_gl_account.gl_code as \'glcode\', name, sum(amount) as \'creditamount\' from acc_gl_journal_entry, acc_gl_account where acc_gl_account.id = acc_gl_journal_entry.account_id and acc_gl_journal_entry.type_enum = 1 and acc_gl_account.classification_enum in (3) and acc_gl_journal_entry.entry_date <= date(\'${endDate}\') and ( acc_gl_journal_entry.office_id = ${officeId} or ${officeId} = 1 ) group by glcode order by glcode ) credits on debits.glcode = credits.glcode )','Balance Sheet',1,1,0);
INSERT INTO `stretchy_report` VALUES (197,'Trial Balance Summary Report','Table',NULL,'Accounting','SELECT *             FROM             (               SELECT                 \'${endDate}\' AS PostingDate,                 loan.pname AS Product,                 loan.gl_code AS GlAcct,                 loan.glname AS Description,                 loan.openingbalance AS BeginningBalance,                 (loan.debitamount * 1) AS DebitMovement,                 (loan.creditamount *-1) AS CreditMovement,                 (                   loan.openingbalance + loan.debitamount - loan.creditamount                 ) AS EndingBalance               FROM                 (                   SELECT                     g.pname,                     g.gl_code,                     g.glname,                     COALESCE(debits.debitamount, 0) - COALESCE(debits.creditamount, 0) AS openingbalance,                     COALESCE(loanproduct.debitamount, 0) AS debitamount,                     COALESCE(loanproduct.creditamount, 0) AS creditamount                   FROM                     (                       SELECT                         ag.gl_code,                         pl.name AS pname,                         ag.name AS glname                       FROM                         acc_gl_account ag                         JOIN acc_product_mapping am ON am.gl_account_id = ag.id                         AND am.product_type = 1                         JOIN m_product_loan pl ON pl.id = am.product_id                     ) g                     LEFT JOIN (                       SELECT                         lp.name AS productname,                         acc_gl_account.gl_code AS glcode,                         acc_gl_account.name AS glname,                         sum(                           case when acc_gl_journal_entry.type_enum = 2 then amount ELSE 0 end                         ) AS debitamount,                         sum(                           case when acc_gl_journal_entry.type_enum = 1 then amount ELSE 0 end                         ) AS creditamount                       FROM                         acc_gl_account                         JOIN acc_gl_journal_entry on acc_gl_account.id = acc_gl_journal_entry.account_id                         JOIN m_loan m ON m.id = acc_gl_journal_entry.entity_id                         JOIN m_product_loan lp ON lp.id = m.product_id                       WHERE                         acc_gl_journal_entry.entity_type_enum = 1                         AND acc_gl_journal_entry.manual_entry = false                         and acc_gl_journal_entry.submitted_on_date < \'${endDate}\'                         and (                           acc_gl_journal_entry.office_id = ${officeId}                         )                       group by                         productname,                         glcode,                         glname                       order by                         glcode                     ) debits ON g.gl_code = debits.glcode                     AND debits.productname = g.pname                     LEFT JOIN (                       SELECT                         lp.name AS productname, account_id,                         acc_gl_account.gl_code AS glcode,                         acc_gl_account.name AS glname,                         sum(                           case when acc_gl_journal_entry.type_enum = 2 then amount ELSE 0 END                         ) AS debitamount,                         sum(                           case when acc_gl_journal_entry.type_enum = 1 then amount ELSE 0 END                         ) AS creditamount                       FROM                         acc_gl_journal_entry                         JOIN acc_gl_account on acc_gl_account.id = acc_gl_journal_entry.account_id                         JOIN m_loan m ON m.id = acc_gl_journal_entry.entity_id                         JOIN m_product_loan lp ON lp.id = m.product_id                       WHERE                         acc_gl_journal_entry.entity_type_enum = 1                         AND acc_gl_journal_entry.manual_entry = false                         and acc_gl_journal_entry.submitted_on_date = \'${endDate}\'                         AND (                           acc_gl_journal_entry.office_id = ${officeId}                         )                       group by                         productname,                         account_id,                         glcode,                         glname                       order by                         glcode                     ) loanproduct ON g.gl_code = loanproduct.glcode                     AND loanproduct.productname = g.pname                 ) loan               UNION               SELECT                 \'${endDate}\' AS PostingDate,                 loan.pname AS Product,                 loan.gl_code AS GlAcct,                 loan.glname AS Description,                 loan.openingbalance AS Beginning_Balance,                 loan.debitamount AS Debit_Movement,                 loan.creditamount AS Credit_Movement,                 (                   loan.openingbalance + loan.debitamount - loan.creditamount                 ) AS Ending_Balance               FROM                 (                   SELECT                     g.pname,                     g.gl_code,                     g.glname,                     COALESCE(debits.debitamount, 0) - COALESCE(debits.creditamount, 0) AS openingbalance,                     COALESCE(loanproduct.debitamount, 0) AS debitamount,                     COALESCE(loanproduct.creditamount, 0) AS creditamount                   FROM                     (                       SELECT                         ag.gl_code,                         pl.name AS pname,                         ag.name AS glname                       FROM                         acc_gl_account ag                         JOIN acc_product_mapping am ON am.gl_account_id = ag.id                         AND am.product_type = 2                         JOIN m_savings_product pl ON pl.id = am.product_id                     ) g                     LEFT join (                       SELECT                         lp.name productname,                         acc_gl_account.gl_code AS glcode,                         acc_gl_account.name AS glname,                         sum(                           case when acc_gl_journal_entry.type_enum = 2 then amount ELSE 0 end                         ) AS debitamount,                         sum(                           case when acc_gl_journal_entry.type_enum = 1 then amount ELSE 0 end                         ) AS creditamount                       FROM                         acc_gl_account                         join acc_gl_journal_entry on acc_gl_account.id = acc_gl_journal_entry.account_id                         JOIN m_savings_account m ON m.id = acc_gl_journal_entry.entity_id                         JOIN m_savings_product lp ON lp.id = m.product_id                       WHERE                         acc_gl_journal_entry.entity_type_enum = 2                         AND acc_gl_journal_entry.manual_entry = false                         and acc_gl_journal_entry.submitted_on_date < \'${endDate}\'                         and (                           acc_gl_journal_entry.office_id = ${officeId}                         )                       group by                         productname,                         glcode,                         glname                       order by                         glcode                     ) debits ON g.gl_code = debits.glcode                     AND debits.productname = g.pname                     left JOIN (                       SELECT                         lp.name productname,                         acc_gl_account.gl_code AS glcode,                         acc_gl_account.name AS glname,                         sum(                           case when acc_gl_journal_entry.type_enum = 2 then amount ELSE 0 end                         ) AS debitamount,                         sum(                           case when acc_gl_journal_entry.type_enum = 1 then amount ELSE 0 end                         ) AS creditamount                       from                         acc_gl_journal_entry                         join acc_gl_account on acc_gl_account.id = acc_gl_journal_entry.account_id                         JOIN m_savings_account m ON m.id = acc_gl_journal_entry.entity_id                         JOIN m_savings_product lp ON lp.id = m.product_id                       WHERE                         acc_gl_journal_entry.entity_type_enum = 2                         AND acc_gl_journal_entry.manual_entry = false                         and acc_gl_journal_entry.submitted_on_date = \'${endDate}\'                         and (                           acc_gl_journal_entry.office_id = ${officeId}                         )                       group by                         productname,                         glcode,                         glname                       order by                         glcode                     ) loanproduct ON g.gl_code = loanproduct.glcode                     AND loanproduct.productname = g.pname                 ) loan               UNION               SELECT                 \'${endDate}\' AS PostingDate,                 \'manual\' AS Product,                 loan.gl_code AS GlAcct,                 loan.glname AS Description,                 loan.openingbalance AS Beginning_Balance,                 loan.debitamount AS Debit_Movement,                 loan.creditamount AS Credit_Movement,                 (                   loan.openingbalance + loan.debitamount - loan.creditamount                 ) AS Ending_Balance               FROM                 (                   SELECT                     g.gl_code,                     g.name AS glname,                     COALESCE(debits.debitamount, 0) - COALESCE(debits.creditamount, 0) AS openingbalance,                     COALESCE(loanproduct.debitamount, 0) AS debitamount,                     COALESCE(loanproduct.creditamount, 0) AS creditamount                   FROM                     acc_gl_account g                     LEFT join (                       SELECT                         acc_gl_account.gl_code AS glcode,                         acc_gl_account.name AS glname,                         sum(                           case when acc_gl_journal_entry.type_enum = 2 then amount ELSE 0 end                         ) AS debitamount,                         sum(                           case when acc_gl_journal_entry.type_enum = 1 then amount ELSE 0 end                         ) AS creditamount                       FROM                         acc_gl_account                         JOIN acc_gl_journal_entry on acc_gl_account.id = acc_gl_journal_entry.account_id                       WHERE                         acc_gl_journal_entry.manual_entry = true                         and acc_gl_journal_entry.submitted_on_date < \'${endDate}\'                         and (                           acc_gl_journal_entry.office_id = ${officeId}                         )                       group by                         glcode,                         glname                       order by                         glcode                     ) debits ON g.gl_code = debits.glcode                     left JOIN (                       SELECT                         acc_gl_account.gl_code AS glcode,                         acc_gl_account.name AS glname,                         sum(                           case when acc_gl_journal_entry.type_enum = 2 then amount ELSE 0 end                         ) AS debitamount,                         sum(                           case when acc_gl_journal_entry.type_enum = 1 then amount ELSE 0 end                         ) AS creditamount                       FROM                         acc_gl_journal_entry                         join acc_gl_account on acc_gl_account.id = acc_gl_journal_entry.account_id                       where                         acc_gl_journal_entry.manual_entry = true                         and acc_gl_journal_entry.submitted_on_date = \'${endDate}\'                         and (                           acc_gl_journal_entry.office_id = ${officeId}                         )                       group by                         glcode,                         glname                       order by                         glcode                     ) loanproduct ON g.gl_code = loanproduct.glcode                 ) loan             ) a           where             a.EndingBalance != 0 or a.DebitMovement != 0 or a.CreditMovement != 0 ','Trial Balance Summary Report',0,1,0);
INSERT INTO `stretchy_report` VALUES (198,'Transaction Summary Report','Table',NULL,'Accounting','SELECT             \'${endDate}\' AS TransactionDate,             a.product AS Product,             (               SELECT                 enum_message_property               FROM                 r_enum_value               WHERE                 enum_name = \'transaction_type_enum\'                 and enum_id = a.transaction_type             ) TransactionType_Name,             (               select                 value               from                 m_payment_type               where                 id = a.payment_type_id             ) as PaymentType_Name,             a.chargetype as chargetype,             a.reversal_indicator AS Reversed,             a.Allocation_Type AS Allocation_Type,             \'\' AS Chargeoff_ReasonCode,             case when a.transaction_type IN (2, 23, 21, 22, 24, 4, 5, 8, 6, 27, 9, 26, 41, 43)             AND a.reversal_indicator = false then sum(a.amount) * -1 when a.transaction_type IN (2, 23, 21, 22, 24, 4, 5, 8, 6, 27, 9, 26, 41, 43)             AND a.reversal_indicator = true then sum(a.amount) * + 1 when a.transaction_type IN (1, 10, 25, 20, 40, 42)             AND a.reversal_indicator = false then sum(a.amount) * + 1 when a.transaction_type IN (1, 10, 25, 20, 40, 42)             AND a.reversal_indicator = true then sum(a.amount) * -1 end AS Transaction_Amount           FROM             (               SELECT                 \'${endDate}\' AS transactiondate,                 t.id,                 l.name AS product,                 t.transaction_type_enum AS transaction_type,                 d.payment_type_id,                 \'\' as chargetype,                 false AS reversal_indicator,                 \'Principal\' AS Allocation_Type,                 CASE when t.transaction_type_enum in (1) then (                   case when t.amount is null then 0 else t.amount end                 ) else (                   case when t.principal_portion_derived is null then 0 else t.principal_portion_derived end                 ) end amount               FROM                 m_loan_transaction t                 JOIN m_loan m ON m.id = t.loan_id                 JOIN m_product_loan l ON l.id = m.product_id                 left join m_payment_detail d on d.id = t.payment_detail_id               WHERE                 t.submitted_on_date = \'${endDate}\'                 and t.transaction_type_enum not in (10, 26)                 and (t.office_id = ${officeId})               UNION ALL               SELECT                 \'${endDate}\' AS transactiondate,                 t.id,                 l.name AS product,                 t.transaction_type_enum AS transaction_type,                 d.payment_type_id,                 \'\' as chargetype,                 false AS reversal_indicator,                 \'Interest\' AS Allocation_Type,                 case when t.interest_portion_derived is null then 0 else t.interest_portion_derived end AS amount               FROM                 m_loan_transaction t                 JOIN m_loan m ON m.id = t.loan_id                 JOIN m_product_loan l ON l.id = m.product_id                 left join m_payment_detail d on d.id = t.payment_detail_id               WHERE                 t.submitted_on_date = \'${endDate}\'                 and t.transaction_type_enum not in (10, 26)                 and (t.office_id = ${officeId})               UNION ALL               SELECT                 \'${endDate}\' AS transactiondate,                 t.id,                 l.name AS product,                 t.transaction_type_enum AS transaction_type,                 d.payment_type_id,                 \'\' as chargetype,                 false AS reversal_indicator,                 \'Fees\' AS Allocation_Type,                 case when t.fee_charges_portion_derived is null then 0 else t.fee_charges_portion_derived end as amount               FROM                 m_loan_transaction t                 JOIN m_loan m ON m.id = t.loan_id                 JOIN m_product_loan l ON l.id = m.product_id                 left join m_payment_detail d on d.id = t.payment_detail_id               WHERE                 t.submitted_on_date = \'${endDate}\'                 and t.transaction_type_enum not in (10, 26)                 and (t.office_id = ${officeId})               UNION ALL               SELECT                 \'${endDate}\' AS transactiondate,                 t.id,                 l.name AS product,                 t.transaction_type_enum AS transaction_type,                 d.payment_type_id,                 \'\' as chargetype,                 false AS reversal_indicator,                 \'Penalty\' AS Allocation_Type,                 case when t.penalty_charges_portion_derived is null then 0 else t.penalty_charges_portion_derived end as amount               FROM                 m_loan_transaction t                 JOIN m_loan m ON m.id = t.loan_id                 JOIN m_product_loan l ON l.id = m.product_id                 left join m_payment_detail d on d.id = t.payment_detail_id               WHERE                 t.submitted_on_date = \'${endDate}\'                 and t.transaction_type_enum not in (10, 26)                 and (t.office_id = ${officeId})               UNION ALL               SELECT                 \'${endDate}\' AS transactiondate,                 t.id,                 l.name AS product,                 t.transaction_type_enum AS transaction_type,                 d.payment_type_id,                 \'\' as chargetype,                 false AS reversal_indicator,                 \'Unallocated Credit (UNC)\' AS Allocation_Type,                 case when t.overpayment_portion_derived is null then 0 else t.overpayment_portion_derived end as amount               FROM                 m_loan_transaction t                 JOIN m_loan m ON m.id = t.loan_id                 JOIN m_product_loan l ON l.id = m.product_id                 left join m_payment_detail d on d.id = t.payment_detail_id               WHERE                 t.submitted_on_date = \'${endDate}\'                 and t.transaction_type_enum not in (10, 26)                 and (t.office_id = ${officeId})               UNION ALL               SELECT                 \'${endDate}\' AS transactiondate,                 t.id,                 l.name AS product,                 t.transaction_type_enum AS transaction_type,                 null,                 mc.name,                 false AS reversal_indicator,                 \'Fees\' AS Allocation_Type,                 case when pd.amount is null then 0 else pd.amount end as amount               FROM                 m_loan_transaction t                 JOIN m_loan m ON m.id = t.loan_id                 JOIN m_product_loan l ON l.id = m.product_id                 join m_loan_charge_paid_by pd on pd.loan_transaction_id = t.id                 join m_loan_charge c on c.id = pd.loan_charge_id                 join m_charge mc on mc.id = c.charge_id                 and mc.is_penalty = false               WHERE                 t.submitted_on_date = \'${endDate}\'                 and t.transaction_type_enum = 10                 and t.is_reversed = false                 and (t.office_id = ${officeId})               UNION ALL               SELECT                 \'${endDate}\' AS transactiondate,                 t.id,                 l.name AS product,                 t.transaction_type_enum AS transaction_type,                 null,                 mc.name,                 false AS reversal_indicator,                 \'Penalty\' AS Allocation_Type,                 case when pd.amount is null then 0 else pd.amount end as amount               FROM                 m_loan_transaction t                 JOIN m_loan m ON m.id = t.loan_id                 JOIN m_product_loan l ON l.id = m.product_id                 join m_loan_charge_paid_by pd on pd.loan_transaction_id = t.id                 join m_loan_charge c on c.id = pd.loan_charge_id                 join m_charge mc on mc.id = c.charge_id                 and mc.is_penalty = true               WHERE                 t.submitted_on_date = \'${endDate}\'                 and t.transaction_type_enum = 10                 and t.is_reversed = false                 and (t.office_id = ${officeId})               UNION ALL               SELECT                 \'${endDate}\' AS transactiondate,                 t.id,                 l.name AS product,                 t.transaction_type_enum AS transaction_type,                 null,                 \'\' as chargetype,                 false AS reversal_indicator,                 \'Interest\' AS Allocation_Type,                 case when t.interest_portion_derived is null then 0 else t.interest_portion_derived end AS amount               FROM                 m_loan_transaction t                 JOIN m_loan m ON m.id = t.loan_id                 JOIN m_product_loan l ON l.id = m.product_id               WHERE                 t.submitted_on_date = \'${endDate}\'                 and t.transaction_type_enum = 10                 and t.is_reversed = false                 and (t.office_id = ${officeId})               UNION ALL               SELECT                 \'${endDate}\' AS transactiondate,                 t.id,                 l.name AS product,                 t.transaction_type_enum AS transaction_type,                 d.payment_type_id,                 mc.name,                 false AS reversal_indicator,                 \'Fees\' AS Allocation_Type,                 case when pd.amount is null then 0 else pd.amount end as amount               FROM                 m_loan_transaction t                 JOIN m_loan m ON m.id = t.loan_id                 JOIN m_product_loan l ON l.id = m.product_id                 join m_loan_charge_paid_by pd on pd.loan_transaction_id = t.id                 join m_loan_charge c on c.id = pd.loan_charge_id                 join m_charge mc on mc.id = c.charge_id                 and mc.is_penalty = false                 left join m_payment_detail d on d.id = t.payment_detail_id               WHERE                 t.submitted_on_date = \'${endDate}\'                 and t.transaction_type_enum = 26                 and (t.office_id = ${officeId})               UNION ALL               SELECT                 \'${endDate}\' AS transactiondate,                 t.id,                 l.name AS product,                 t.transaction_type_enum AS transaction_type,                 d.payment_type_id,                 mc.name,                 false AS reversal_indicator,                 \'Penalty\' AS Allocation_Type,                 case when pd.amount is null then 0 else pd.amount end AS amount               FROM                 m_loan_transaction t                 JOIN m_loan m ON m.id = t.loan_id                 JOIN m_product_loan l ON l.id = m.product_id                 join m_loan_charge_paid_by pd on pd.loan_transaction_id = t.id                 join m_loan_charge c on c.id = pd.loan_charge_id                 join m_charge mc on mc.id = c.charge_id                 and mc.is_penalty = true                 left join m_payment_detail d on d.id = t.payment_detail_id               WHERE                 t.submitted_on_date = \'${endDate}\'                 and t.transaction_type_enum = 26                 and (t.office_id = ${officeId})               UNION ALL               SELECT                 \'${endDate}\' AS transactiondate,                 t.id,                 l.name AS product,                 t.transaction_type_enum AS transaction_type,                 d.payment_type_id,                 \'\' as chargetype,                 false AS reversal_indicator,                 \'Interest\' AS Allocation_Type,                 case when t.interest_portion_derived is null then 0 else t.interest_portion_derived end AS amount               FROM                 m_loan_transaction t                 JOIN m_loan m ON m.id = t.loan_id                 JOIN m_product_loan l ON l.id = m.product_id                 left join m_payment_detail d on d.id = t.payment_detail_id               WHERE                 t.submitted_on_date = \'${endDate}\'                 and t.transaction_type_enum = 26                 and (t.office_id = ${officeId})               UNION ALL               SELECT                 \'${endDate}\' AS transactiondate,                 t.id,                 l.name AS product,                 t.transaction_type_enum AS transaction_type,                 d.payment_type_id,                 \'\' as chargetype,                 false AS reversal_indicator,                 \'Principal\' AS Allocation_Type,                 case when t.principal_portion_derived is null then 0 else t.principal_portion_derived end AS amount               FROM                 m_loan_transaction t                 JOIN m_loan m ON m.id = t.loan_id                 JOIN m_product_loan l ON l.id = m.product_id                 left join m_payment_detail d on d.id = t.payment_detail_id               WHERE                 t.submitted_on_date = \'${endDate}\'                 and t.transaction_type_enum = 26                 and (t.office_id = ${officeId})               UNION ALL               SELECT                 \'${endDate}\' AS transactiondate,                 t.id,                 l.name AS product,                 t.transaction_type_enum AS transaction_type,                 d.payment_type_id,                 \'\' as chargetype,                 false AS reversal_indicator,                 \'Unallocated Credit (UNC)\' AS Allocation_Type,                 case when t.overpayment_portion_derived is null then 0 else t.overpayment_portion_derived end AS amount               FROM                 m_loan_transaction t                 JOIN m_loan m ON m.id = t.loan_id                 JOIN m_product_loan l ON l.id = m.product_id                 left join m_payment_detail d on d.id = t.payment_detail_id               WHERE                 t.submitted_on_date = \'${endDate}\'                 and t.transaction_type_enum = 26                 and (t.office_id = ${officeId})               UNION ALL               SELECT                 \'${endDate}\' AS transactiondate,                 t.id,                 l.name AS product,                 t.transaction_type_enum AS transaction_type,                 d.payment_type_id,                 \'\' as chargetype,                 true AS reversal_indicator,                 \'Principal\' AS Allocation_Type,                 CASE when t.transaction_type_enum in (1) then (                   case when t.amount is null then 0 else t.amount end                 ) else (                   case when t.principal_portion_derived is null then 0 else t.principal_portion_derived end                 ) end amount               FROM                 m_loan_transaction t                 JOIN m_loan m ON m.id = t.loan_id                 JOIN m_product_loan l ON l.id = m.product_id                 left join m_payment_detail d on d.id = t.payment_detail_id               WHERE                 t.reversed_on_date = \'${endDate}\'                 and t.transaction_type_enum not in (10, 26)                 and (t.office_id = ${officeId})               UNION ALL               SELECT                 \'${endDate}\' AS transactiondate,                 t.id,                 l.name AS product,                 t.transaction_type_enum AS transaction_type,                 d.payment_type_id,                 \'\' as chargetype,                 true AS reversal_indicator,                 \'Interest\' AS Allocation_Type,                 case when t.interest_portion_derived is null then 0 else t.interest_portion_derived end AS amount               FROM                 m_loan_transaction t                 JOIN m_loan m ON m.id = t.loan_id                 JOIN m_product_loan l ON l.id = m.product_id                 left join m_payment_detail d on d.id = t.payment_detail_id               WHERE                 t.reversed_on_date = \'${endDate}\'                 and t.transaction_type_enum not in (10, 26)                 and (t.office_id = ${officeId})               UNION ALL               SELECT                 \'${endDate}\' AS transactiondate,                 t.id,                 l.name AS product,                 t.transaction_type_enum AS transaction_type,                 d.payment_type_id,                 \'\' as chargetype,                 true AS reversal_indicator,                 \'Fees\' AS Allocation_Type,                 case when t.fee_charges_portion_derived is null then 0 else t.fee_charges_portion_derived end as amount               FROM                 m_loan_transaction t                 JOIN m_loan m ON m.id = t.loan_id                 JOIN m_product_loan l ON l.id = m.product_id                 left join m_payment_detail d on d.id = t.payment_detail_id               WHERE                 t.reversed_on_date = \'${endDate}\'                 and t.transaction_type_enum not in (10, 26)                 and (t.office_id = ${officeId})               UNION ALL               SELECT                 \'${endDate}\' AS transactiondate,                 t.id,                 l.name AS product,                 t.transaction_type_enum AS transaction_type,                 d.payment_type_id,                 \'\' as chargetype,                 true AS reversal_indicator,                 \'Penalty\' AS Allocation_Type,                 case when t.penalty_charges_portion_derived is null then 0 else t.penalty_charges_portion_derived end as amount               FROM                 m_loan_transaction t                 JOIN m_loan m ON m.id = t.loan_id                 JOIN m_product_loan l ON l.id = m.product_id                 left join m_payment_detail d on d.id = t.payment_detail_id               WHERE                 t.reversed_on_date = \'${endDate}\'                 and t.transaction_type_enum not in (10, 26)                 and (t.office_id = ${officeId})               UNION ALL               SELECT                 \'${endDate}\' AS transactiondate,                 t.id,                 l.name AS product,                 t.transaction_type_enum AS transaction_type,                 d.payment_type_id,                 \'\' as chargetype,                 true AS reversal_indicator,                 \'Unallocated Credit (UNC)\' AS Allocation_Type,                 case when t.overpayment_portion_derived is null then 0 else t.overpayment_portion_derived end as amount               FROM                 m_loan_transaction t                 JOIN m_loan m ON m.id = t.loan_id                 JOIN m_product_loan l ON l.id = m.product_id                 left join m_payment_detail d on d.id = t.payment_detail_id               WHERE                 t.reversed_on_date = \'${endDate}\'                 and t.transaction_type_enum not in (10, 26)                 and (t.office_id = ${officeId})               UNION ALL               SELECT                 \'${endDate}\' AS transactiondate,                 t.id,                 l.name AS product,                 t.transaction_type_enum AS transaction_type,                 null,                 mc.name,                 true AS reversal_indicator,                 \'Fees\' AS Allocation_Type,                 case when pd.amount is null then 0 else pd.amount end as amount               FROM                 m_loan_transaction t                 JOIN m_loan m ON m.id = t.loan_id                 JOIN m_product_loan l ON l.id = m.product_id                 join m_loan_charge_paid_by pd on pd.loan_transaction_id = t.id                 join m_loan_charge c on c.id = pd.loan_charge_id                 join m_charge mc on mc.id = c.charge_id                 and mc.is_penalty = false               WHERE                 t.reversed_on_date = \'${endDate}\'                 and t.transaction_type_enum = 10                 and t.is_reversed = true                 and (t.office_id = ${officeId})               UNION ALL               SELECT                 \'${endDate}\' AS transactiondate,                 t.id,                 l.name AS product,                 t.transaction_type_enum AS transaction_type,                 null,                 mc.name,                 true AS reversal_indicator,                 \'Penalty\' AS Allocation_Type,                 case when pd.amount is null then 0 else pd.amount end as amount               FROM                 m_loan_transaction t                 JOIN m_loan m ON m.id = t.loan_id                 JOIN m_product_loan l ON l.id = m.product_id                 join m_loan_charge_paid_by pd on pd.loan_transaction_id = t.id                 join m_loan_charge c on c.id = pd.loan_charge_id                 join m_charge mc on mc.id = c.charge_id                 and mc.is_penalty = true               WHERE                 t.reversed_on_date = \'${endDate}\'                 and t.transaction_type_enum = 10                 and t.is_reversed = true                 and (t.office_id = ${officeId})               UNION ALL               SELECT                 \'${endDate}\' AS transactiondate,                 t.id,                 l.name AS product,                 t.transaction_type_enum AS transaction_type,                 null,                 \'\' as chargetype,                 true AS reversal_indicator,                 \'Interest\' AS Allocation_Type,                 case when t.interest_portion_derived is null then 0 else t.interest_portion_derived end AS amount               FROM                 m_loan_transaction t                 JOIN m_loan m ON m.id = t.loan_id                 JOIN m_product_loan l ON l.id = m.product_id               WHERE                 t.reversed_on_date = \'${endDate}\'                 and t.transaction_type_enum = 10                 and t.is_reversed = true                 and (t.office_id = ${officeId})               UNION ALL               SELECT                 \'${endDate}\' AS transactiondate,                 t.id,                 l.name AS product,                 t.transaction_type_enum AS transaction_type,                 d.payment_type_id,                 mc.name,                 true AS reversal_indicator,                 \'Fees\' AS Allocation_Type,                 case when pd.amount is null then 0 else pd.amount end as amount               FROM                 m_loan_transaction t                 JOIN m_loan m ON m.id = t.loan_id                 JOIN m_product_loan l ON l.id = m.product_id                 join m_loan_charge_paid_by pd on pd.loan_transaction_id = t.id                 join m_loan_charge c on c.id = pd.loan_charge_id                 join m_charge mc on mc.id = c.charge_id                 and mc.is_penalty = false                 left join m_payment_detail d on d.id = t.payment_detail_id               WHERE                 t.reversed_on_date = \'${endDate}\'                 and t.transaction_type_enum = 26                 and (t.office_id = ${officeId})               UNION ALL               SELECT                 \'${endDate}\' AS transactiondate,                 t.id,                 l.name AS product,                 t.transaction_type_enum AS transaction_type,                 d.payment_type_id,                 mc.name,                 true AS reversal_indicator,                 \'Penalty\' AS Allocation_Type,                 case when pd.amount is null then 0 else pd.amount end AS amount               FROM                 m_loan_transaction t                 JOIN m_loan m ON m.id = t.loan_id                 JOIN m_product_loan l ON l.id = m.product_id                 join m_loan_charge_paid_by pd on pd.loan_transaction_id = t.id                 join m_loan_charge c on c.id = pd.loan_charge_id                 join m_charge mc on mc.id = c.charge_id                 and mc.is_penalty = true                 left join m_payment_detail d on d.id = t.payment_detail_id               WHERE                 t.reversed_on_date = \'${endDate}\'                 and t.transaction_type_enum = 26                 and (t.office_id = ${officeId})               UNION ALL               SELECT                 \'${endDate}\' AS transactiondate,                 t.id,                 l.name AS product,                 t.transaction_type_enum AS transaction_type,                 d.payment_type_id,                 \'\' as chargetype,                 true AS reversal_indicator,                 \'Interest\' AS Allocation_Type,                 case when t.interest_portion_derived is null then 0 else t.interest_portion_derived end AS amount               FROM                 m_loan_transaction t                 JOIN m_loan m ON m.id = t.loan_id                 JOIN m_product_loan l ON l.id = m.product_id                 left join m_payment_detail d on d.id = t.payment_detail_id               WHERE                 t.reversed_on_date = \'${endDate}\'                 and t.transaction_type_enum = 26                 and (t.office_id = ${officeId})               UNION ALL               SELECT                 \'${endDate}\' AS transactiondate,                 t.id,                 l.name AS product,                 t.transaction_type_enum AS transaction_type,                 d.payment_type_id,                 \'\' as chargetype,                 true AS reversal_indicator,                 \'Principal\' AS Allocation_Type,                 case when t.principal_portion_derived is null then 0 else t.principal_portion_derived end AS amount               FROM                 m_loan_transaction t                 JOIN m_loan m ON m.id = t.loan_id                 JOIN m_product_loan l ON l.id = m.product_id                 left join m_payment_detail d on d.id = t.payment_detail_id               WHERE                 t.reversed_on_date = \'${endDate}\'                 and t.transaction_type_enum = 26                 and (t.office_id = ${officeId})               UNION ALL               SELECT                 \'${endDate}\' AS transactiondate,                 t.id,                 l.name AS product,                 t.transaction_type_enum AS transaction_type,                 d.payment_type_id,                 \'\' as chargetype,                 true AS reversal_indicator,                 \'Unallocated Credit (UNC)\' AS Allocation_Type,                 case when t.overpayment_portion_derived is null then 0 else t.overpayment_portion_derived end AS amount               FROM                 m_loan_transaction t                 JOIN m_loan m ON m.id = t.loan_id                 JOIN m_product_loan l ON l.id = m.product_id                 left join m_payment_detail d on d.id = t.payment_detail_id               WHERE                 t.reversed_on_date = \'${endDate}\'                 and t.transaction_type_enum = 26                 and (t.office_id = ${officeId})             ) a           GROUP BY             a.transactiondate,             a.product,             a.transaction_type,             a.payment_type_id,             a.chargetype,             a.reversal_indicator,             a.Allocation_Type           order by             1,             2,             3,             4,             5,             6,             7 ','Transaction Summary Report',0,1,0);
INSERT INTO `stretchy_report` VALUES (199,'Trial Balance Summary Report with Asset Owner','Table',NULL,'Accounting','WITH retained_earning AS (SELECT DISTINCT \'${endDate}\' AS postingdate,\n lp.name AS product,\n gl_code AS glacct,\n COALESCE((SELECT name FROM acc_gl_account WHERE gl_code = e.gl_code),\n \'\') AS description,\n COALESCE(e.owner_external_id, \'self\') AS assetowner,\n SUM(opening_balance_amount) AS beginningbalance,\n 0 AS debitmovement,\n 0 AS creditmovement,\n SUM(opening_balance_amount) AS endingbalance,\n COALESCE(e.originator_external_ids, \'\') AS originator_external_ids\n FROM acc_gl_journal_entry_annual_summary e,\n m_product_loan lp\n WHERE e.office_id = ${officeId}\n AND lp.id = product_id\n AND EXTRACT(YEAR FROM e.year_end_date) < EXTRACT(YEAR FROM CAST(\'${endDate}\' AS DATE))\n GROUP BY gl_code, lp.name, office_id, owner_external_id, originator_external_ids),\n aggregated_date AS (SELECT MAX(aggregated_on_date_to) AS latest\n FROM m_journal_entry_aggregation_tracking\n WHERE aggregated_on_date_to < \'${endDate}\'),\n summary_snapshot_baseline_data AS (SELECT lp.NAME AS productname,\n acc_gl_account.gl_code AS glcode,\n acc_gl_account.NAME AS glname,\n CASE\n WHEN ags.external_owner_id IS NULL THEN 0\n ELSE ags.external_owner_id END AS assetowner,\n COALESCE(ags.originator_external_ids, \'\') AS originator_external_ids,\n SUM(ags.debit_amount) AS debitamount,\n SUM(ags.credit_amount) AS creditamount\n FROM acc_gl_account\n JOIN m_journal_entry_aggregation_summary ags\n ON acc_gl_account.id = ags.gl_account_id\n JOIN m_product_loan lp ON lp.id = ags.product_id\n WHERE ags.entity_type_enum = 1\n AND ags.manual_entry = FALSE\n AND ags.aggregated_on_date <= (SELECT latest FROM aggregated_date)\n AND (ags.office_id = ${officeId})\n GROUP BY productname, glcode, glname, assetowner, originator_external_ids),\n post_snapshot_delta_data AS (SELECT lp.NAME AS productname,\n acc_gl_account.gl_code AS glcode,\n acc_gl_account.NAME AS glname,\n CASE WHEN aw.owner_id IS NULL THEN 0 ELSE aw.owner_id END AS assetowner,\n SUM(CASE WHEN acc_gl_journal_entry.type_enum = 2 THEN amount ELSE 0 END) AS debitamount,\n SUM(CASE WHEN acc_gl_journal_entry.type_enum = 1 THEN amount ELSE 0 END) AS creditamount,\n COALESCE((SELECT GROUP_CONCAT(DISTINCT mlo.external_id ORDER BY mlo.external_id SEPARATOR \', \')\n FROM m_loan_originator_mapping mlom\n JOIN m_loan_originator mlo ON mlo.id = mlom.originator_id\n WHERE mlom.loan_id = m.id), \'\') AS originator_external_ids\n FROM acc_gl_account\n JOIN acc_gl_journal_entry\n ON acc_gl_account.id = acc_gl_journal_entry.account_id\n JOIN m_loan m ON m.id = acc_gl_journal_entry.entity_id\n JOIN m_product_loan lp ON lp.id = m.product_id\n LEFT JOIN m_external_asset_owner_journal_entry_mapping aw\n ON aw.journal_entry_id = acc_gl_journal_entry.id\n WHERE acc_gl_journal_entry.entity_type_enum = 1\n AND acc_gl_journal_entry.manual_entry = FALSE\n AND (\n (SELECT latest FROM aggregated_date) IS NULL\n OR\n acc_gl_journal_entry.submitted_on_date > (SELECT latest FROM aggregated_date)\n )\n AND acc_gl_journal_entry.submitted_on_date < \'${endDate}\'\n AND (acc_gl_journal_entry.office_id = ${officeId})\n GROUP BY productname, glcode, glname, assetowner, originator_external_ids),\n merged_historical_data AS (SELECT COALESCE(s.productname, p.productname) AS productname,\n COALESCE(s.glcode, p.glcode) AS glcode,\n COALESCE(s.glname, p.glname) AS glname,\n COALESCE(s.assetowner, p.assetowner, 0) AS assetowner,\n COALESCE(s.debitamount, 0) + COALESCE(p.debitamount, 0) AS debitamount,\n COALESCE(s.creditamount, 0) + COALESCE(p.creditamount, 0) AS creditamount,\n COALESCE(p.originator_external_ids, s.originator_external_ids, \'\') AS originator_external_ids\n FROM summary_snapshot_baseline_data s\n LEFT JOIN post_snapshot_delta_data p\n ON s.glcode = p.glcode\n AND s.productname = p.productname\n AND s.assetowner = p.assetowner\n AND s.originator_external_ids = p.originator_external_ids\n\n UNION ALL\n\n SELECT p.productname AS productname,\n p.glcode AS glcode,\n p.glname AS glname,\n COALESCE(p.assetowner, 0) AS assetowner,\n COALESCE(p.debitamount, 0) AS debitamount,\n COALESCE(p.creditamount, 0) AS creditamount,\n COALESCE(p.originator_external_ids, \'\') AS originator_external_ids\n FROM post_snapshot_delta_data p\n LEFT JOIN summary_snapshot_baseline_data s\n ON s.glcode = p.glcode\n AND s.productname = p.productname\n AND s.assetowner = p.assetowner\n AND s.originator_external_ids = p.originator_external_ids\n WHERE s.glcode IS NULL),\n current_cob_data AS (SELECT lp.name AS productname,\n account_id,\n acc_gl_account.gl_code AS glcode,\n acc_gl_account.name AS glname,\n CASE WHEN aw.owner_id IS NULL THEN 0 ELSE aw.owner_id END AS assetowner,\n SUM(CASE WHEN acc_gl_journal_entry.type_enum = 2 THEN amount ELSE 0 END) AS debitamount,\n SUM(CASE WHEN acc_gl_journal_entry.type_enum = 1 THEN amount ELSE 0 END) AS creditamount,\n COALESCE((SELECT GROUP_CONCAT(DISTINCT mlo.external_id ORDER BY mlo.external_id SEPARATOR \', \')\n FROM m_loan_originator_mapping mlom\n JOIN m_loan_originator mlo ON mlo.id = mlom.originator_id\n WHERE mlom.loan_id = m.id), \'\') AS originator_external_ids\n FROM acc_gl_journal_entry\n JOIN acc_gl_account ON acc_gl_account.id = acc_gl_journal_entry.account_id\n JOIN m_loan m ON m.id = acc_gl_journal_entry.entity_id\n JOIN m_product_loan lp ON lp.id = m.product_id\n LEFT JOIN m_external_asset_owner_journal_entry_mapping aw\n ON aw.journal_entry_id = acc_gl_journal_entry.id\n WHERE acc_gl_journal_entry.entity_type_enum = 1\n AND acc_gl_journal_entry.manual_entry = FALSE\n AND acc_gl_journal_entry.submitted_on_date = \'${endDate}\'\n AND (acc_gl_journal_entry.office_id = ${officeId})\n GROUP BY productname, account_id, glcode, glname, assetowner, originator_external_ids)\n\nSELECT *\nFROM (SELECT *\n FROM retained_earning\n WHERE glacct = (SELECT gl_code FROM acc_gl_account WHERE name = \'Retained Earnings Prior Year\')\n\n UNION\n\n SELECT txnreport.postingdate,\n txnreport.product,\n txnreport.glacct,\n txnreport.description,\n txnreport.assetowner,\n (COALESCE(txnreport.beginningbalance, 0) + COALESCE(summary.beginningbalance, 0)) AS beginningbalance,\n txnreport.debitmovement AS debitmovement,\n txnreport.creditmovement AS creditmovement,\n (COALESCE(txnreport.endingbalance, 0) + COALESCE(summary.beginningbalance, 0)) AS endingbalance,\n txnreport.originator_external_ids AS originator_external_ids\n FROM (SELECT *\n FROM (SELECT DISTINCT \'${endDate}\' AS postingdate,\n loan.pname AS product,\n loan.gl_code AS glacct,\n loan.glname AS description,\n COALESCE((SELECT external_id FROM m_external_asset_owner WHERE id = loan.assetowner),\n \'self\') AS assetowner,\n loan.openingbalance AS beginningbalance,\n (loan.debitamount * 1) AS debitmovement,\n (loan.creditamount * -1) AS creditmovement,\n (loan.openingbalance + loan.debitamount - loan.creditamount) AS endingbalance,\n loan.originator_external_ids AS originator_external_ids\n FROM (SELECT DISTINCT g.pname AS pname,\n g.gl_code AS gl_code,\n g.glname AS glname,\n COALESCE(mh.assetowner, c.assetowner, 0) AS assetowner,\n COALESCE(mh.debitamount, 0) - COALESCE(mh.creditamount, 0) AS openingbalance,\n COALESCE(c.debitamount, 0) AS debitamount,\n COALESCE(c.creditamount, 0) AS creditamount,\n COALESCE(mh.originator_external_ids, c.originator_external_ids) AS originator_external_ids\n FROM (SELECT DISTINCT ag.gl_code, ag.id, pl.NAME AS pname, ag.NAME AS glname\n FROM acc_gl_account ag\n JOIN acc_product_mapping am ON am.gl_account_id = ag.id AND am.product_type = 1\n JOIN m_product_loan pl ON pl.id = am.product_id) g\n LEFT JOIN merged_historical_data mh\n ON g.gl_code = mh.glcode\n AND mh.productname = g.pname\n LEFT JOIN current_cob_data c\n ON g.gl_code = c.glcode\n AND c.productname = g.pname\n AND mh.assetowner = c.assetowner\n AND mh.originator_external_ids = c.originator_external_ids\n\n UNION ALL\n\n SELECT DISTINCT c.productname AS pname,\n c.glcode AS gl_code,\n c.glname AS glname,\n COALESCE(c.assetowner, 0) AS assetowner,\n 0 AS openingbalance,\n COALESCE(c.debitamount, 0) AS debitamount,\n COALESCE(c.creditamount, 0) AS creditamount,\n COALESCE(matched.originator_external_ids, c.originator_external_ids) AS originator_external_ids\n FROM current_cob_data c\n LEFT JOIN (SELECT g3.gl_code, g3.pname, mh.assetowner, mh.originator_external_ids\n FROM (SELECT DISTINCT ag.gl_code, pl.NAME AS pname\n FROM acc_gl_account ag\n JOIN acc_product_mapping am\n ON am.gl_account_id = ag.id AND am.product_type = 1\n JOIN m_product_loan pl ON pl.id = am.product_id) g3\n LEFT JOIN merged_historical_data mh\n ON g3.gl_code = mh.glcode\n AND mh.productname = g3.pname) matched\n ON matched.gl_code = c.glcode\n AND matched.pname = c.productname\n AND matched.assetowner = c.assetowner\n AND matched.originator_external_ids = c.originator_external_ids\n WHERE matched.gl_code IS NULL) loan) a) AS txnreport\n LEFT JOIN retained_earning summary\n ON txnreport.glacct = summary.glacct\n AND txnreport.assetowner = summary.assetowner\n AND summary.product = txnreport.product\n AND summary.originator_external_ids = txnreport.originator_external_ids) report\nWHERE report.endingbalance != 0\n OR report.debitmovement != 0\n OR report.creditmovement != 0\nORDER BY glacct','Trial Balance Summary Report with Asset Owner',0,1,0);
INSERT INTO `stretchy_report` VALUES (200,'Transaction Summary Report with Asset Owner','Table',NULL,'Accounting','WITH slt_except_charge_adj_and_accrual AS (SELECT \'${endDate}\' AS transactiondate,\n            t.id,\n            l.name,\n            d.payment_type_id,\n            CASE\n                WHEN d.payment_type_id IS NULL AND t.classification_cv_id IS NOT NULL\n                    THEN (SELECT code_value FROM m_code_value WHERE id = t.classification_cv_id)\n                ELSE NULL END AS classification_name,\n            t.transaction_type_enum,\n            t.amount,\n            t.overpayment_portion_derived,\n            t.principal_portion_derived,\n            t.interest_portion_derived,\n            t.fee_charges_portion_derived,\n            t.penalty_charges_portion_derived,\n            e.status,\n            e.settlement_date,\n            e.owner_id,\n            m.charged_off_on_date,\n            t.transaction_date,\n            m.charge_off_reason_cv_id,\n            (SELECT GROUP_CONCAT(DISTINCT mlo.external_id ORDER BY mlo.external_id SEPARATOR \', \') FROM m_loan_originator_mapping mlom JOIN m_loan_originator mlo ON mlo.id = mlom.originator_id WHERE mlom.loan_id = t.loan_id) AS originator_external_ids\n     FROM m_loan_transaction t\n              JOIN m_loan m ON m.id = t.loan_id\n              JOIN m_product_loan l ON l.id = m.product_id\n              LEFT JOIN m_payment_detail d ON d.id = t.payment_detail_id\n              LEFT JOIN m_external_asset_owner_transfer e\n                        ON e.loan_id = t.loan_id AND\n        e.settlement_date < \'${endDate}\' AND\n        e.effective_date_to >= \'${endDate}\'\n     WHERE t.submitted_on_date = \'${endDate}\'\n       AND t.transaction_type_enum not in (10, 26, 32, 34, 36, 39, 42, 43)\n       AND (t.office_id = ${officeId})),\n     slt_charge_adj AS (SELECT \'${endDate}\' AS transactiondate,\n            t.id,\n            l.name,\n            t.transaction_type_enum,\n            d.payment_type_id,\n            t.overpayment_portion_derived,\n            t.principal_portion_derived,\n            t.interest_portion_derived,\n            t.fee_charges_portion_derived,\n            t.penalty_charges_portion_derived,\n            t.amount,\n            e.status,\n            e.settlement_date,\n            e.owner_id,\n            m.charged_off_on_date,\n            t.transaction_date,\n            m.charge_off_reason_cv_id,\n            (SELECT GROUP_CONCAT(DISTINCT mlo.external_id ORDER BY mlo.external_id SEPARATOR \', \') FROM m_loan_originator_mapping mlom JOIN m_loan_originator mlo ON mlo.id = mlom.originator_id WHERE mlom.loan_id = t.loan_id) AS originator_external_ids\n     FROM m_loan_transaction t\n              JOIN m_loan m ON m.id = t.loan_id\n              JOIN m_product_loan l ON l.id = m.product_id\n              LEFT JOIN m_payment_detail d ON d.id = t.payment_detail_id\n              LEFT JOIN m_external_asset_owner_transfer e\n     ON e.loan_id = t.loan_id AND e.settlement_date < \'${endDate}\' AND\n        e.effective_date_to >= \'${endDate}\'\n     WHERE t.submitted_on_date = \'${endDate}\'\n       AND t.transaction_type_enum = 26\n       AND (t.office_id = ${officeId})),\n     rlt_except_charge_adj_and_accrual AS (SELECT \'${endDate}\' AS transactiondate,\n            t.id,\n            l.name,\n            t.transaction_type_enum,\n            d.payment_type_id,\n            CASE\n                WHEN d.payment_type_id IS NULL AND t.classification_cv_id IS NOT NULL\n                    THEN (SELECT code_value FROM m_code_value WHERE id = t.classification_cv_id)\n                ELSE NULL END AS classification_name,\n            t.overpayment_portion_derived,\n            t.principal_portion_derived,\n            t.interest_portion_derived,\n            t.fee_charges_portion_derived,\n            t.penalty_charges_portion_derived,\n            t.amount,\n            e.status,\n            e.settlement_date,\n            e.owner_id,\n            m.charged_off_on_date,\n            t.transaction_date,\n            m.charge_off_reason_cv_id,\n            (SELECT GROUP_CONCAT(DISTINCT mlo.external_id ORDER BY mlo.external_id SEPARATOR \', \') FROM m_loan_originator_mapping mlom JOIN m_loan_originator mlo ON mlo.id = mlom.originator_id WHERE mlom.loan_id = t.loan_id) AS originator_external_ids\n     FROM m_loan_transaction t\n              JOIN m_loan m ON m.id = t.loan_id\n              JOIN m_product_loan l ON l.id = m.product_id\n              LEFT JOIN m_payment_detail d ON d.id = t.payment_detail_id\n              LEFT JOIN m_external_asset_owner_transfer e\n                        ON e.loan_id = t.loan_id AND\n        e.settlement_date < \'${endDate}\' AND\n        e.effective_date_to >= \'${endDate}\'\n     WHERE t.reversed_on_date = \'${endDate}\'\n       AND t.transaction_type_enum not in (10, 26, 32, 34, 36, 39, 42, 43)\n       AND (t.office_id = ${officeId})),\n     rlt_charge_adj AS (SELECT \'${endDate}\' AS transactiondate,\n            t.id,\n            l.name,\n            t.transaction_type_enum,\n            d.payment_type_id,\n            t.overpayment_portion_derived,\n            t.principal_portion_derived,\n            t.interest_portion_derived,\n            t.fee_charges_portion_derived,\n            t.penalty_charges_portion_derived,\n            t.amount,\n            e.status,\n            e.settlement_date,\n            e.owner_id,\n            m.charged_off_on_date,\n            t.transaction_date,\n            m.charge_off_reason_cv_id,\n            (SELECT GROUP_CONCAT(DISTINCT mlo.external_id ORDER BY mlo.external_id SEPARATOR \', \') FROM m_loan_originator_mapping mlom JOIN m_loan_originator mlo ON mlo.id = mlom.originator_id WHERE mlom.loan_id = t.loan_id) AS originator_external_ids\n     FROM m_loan_transaction t\n              JOIN m_loan m ON m.id = t.loan_id\n              JOIN m_product_loan l ON l.id = m.product_id\n              LEFT JOIN m_payment_detail d ON d.id = t.payment_detail_id\n              LEFT JOIN m_external_asset_owner_transfer e\n     ON e.loan_id = t.loan_id AND e.settlement_date < \'${endDate}\' AND\n        e.effective_date_to >= \'${endDate}\'\n     WHERE t.reversed_on_date = \'${endDate}\'\n       AND t.transaction_type_enum = 26\n       AND (t.office_id = ${officeId})),\n     slt_cap_income_amortization AS (SELECT \'${endDate}\' AS transactiondate,\n      t.id,\n      l.name,\n      t.transaction_type_enum,\n      d.payment_type_id,\n      CASE\n          WHEN d.payment_type_id IS NULL AND bt.classification_cv_id IS NOT NULL\n              THEN (SELECT code_value FROM m_code_value WHERE id = bt.classification_cv_id)\n          ELSE NULL END AS classification_name,\n      CASE\n          WHEN t.overpayment_portion_derived IS NOT NULL\n              THEN map.amount\n          ELSE NULL END AS overpayment_portion_derived,\n      CASE\n          WHEN t.principal_portion_derived IS NOT NULL\n              THEN map.amount\n          ELSE NULL END AS principal_portion_derived,\n      CASE\n          WHEN t.interest_portion_derived IS NOT NULL\n              THEN map.amount\n          ELSE NULL END AS interest_portion_derived,\n      CASE\n          WHEN t.fee_charges_portion_derived IS NOT NULL\n              THEN map.amount\n          ELSE NULL END AS fee_charges_portion_derived,\n      CASE\n          WHEN t.penalty_charges_portion_derived IS NOT NULL\n              THEN map.amount\n          ELSE NULL END AS penalty_charges_portion_derived,\n      map.amount,\n      e.status,\n      e.settlement_date,\n      e.owner_id,\n      m.charged_off_on_date,\n      t.transaction_date,\n      m.charge_off_reason_cv_id,\n      (SELECT GROUP_CONCAT(DISTINCT mlo.external_id ORDER BY mlo.external_id SEPARATOR \', \') FROM m_loan_originator_mapping mlom JOIN m_loan_originator mlo ON mlo.id = mlom.originator_id WHERE mlom.loan_id = t.loan_id) AS originator_external_ids\n                  FROM m_loan_transaction t\n        JOIN m_loan m ON m.id = t.loan_id\n        JOIN m_product_loan l ON l.id = m.product_id\n        LEFT JOIN m_payment_detail d ON d.id = t.payment_detail_id\n        JOIN m_loan_amortization_allocation_mapping map\n             ON map.amortization_loan_transaction_id = t.id\n        JOIN m_loan_transaction bt ON bt.id = map.base_loan_transaction_id\n        LEFT JOIN m_external_asset_owner_transfer e ON e.loan_id = t.loan_id AND\n                 e.settlement_date <\n                 \'${endDate}\' AND\n                 e.effective_date_to >=\n                 \'${endDate}\'\n                  WHERE t.submitted_on_date = \'${endDate}\'\n                    AND t.is_reversed = false\n                    AND t.transaction_type_enum IN (36, 39, 42, 43)\n                    AND (t.office_id = ${officeId})),\n     rlt_cap_income_amortization AS (SELECT \'${endDate}\' AS transactiondate,\n      t.id,\n      l.name,\n      t.transaction_type_enum,\n      d.payment_type_id,\n      CASE\n          WHEN d.payment_type_id IS NULL AND bt.classification_cv_id IS NOT NULL\n              THEN (SELECT code_value FROM m_code_value WHERE id = bt.classification_cv_id)\n          ELSE NULL END AS classification_name,\n      CASE\n          WHEN t.overpayment_portion_derived IS NOT NULL\n              THEN map.amount\n          ELSE NULL END AS overpayment_portion_derived,\n      CASE\n          WHEN t.principal_portion_derived IS NOT NULL\n              THEN map.amount\n          ELSE NULL END AS principal_portion_derived,\n      CASE\n          WHEN t.interest_portion_derived IS NOT NULL\n              THEN map.amount\n          ELSE NULL END AS interest_portion_derived,\n      CASE\n          WHEN t.fee_charges_portion_derived IS NOT NULL\n              THEN map.amount\n          ELSE NULL END AS fee_charges_portion_derived,\n      CASE\n          WHEN t.penalty_charges_portion_derived IS NOT NULL\n              THEN map.amount\n          ELSE NULL END AS penalty_charges_portion_derived,\n      map.amount,\n      e.status,\n      e.settlement_date,\n      e.owner_id,\n      m.charged_off_on_date,\n      t.transaction_date,\n      m.charge_off_reason_cv_id,\n      (SELECT GROUP_CONCAT(DISTINCT mlo.external_id ORDER BY mlo.external_id SEPARATOR \', \') FROM m_loan_originator_mapping mlom JOIN m_loan_originator mlo ON mlo.id = mlom.originator_id WHERE mlom.loan_id = t.loan_id) AS originator_external_ids\n                  FROM m_loan_transaction t\n        JOIN m_loan m ON m.id = t.loan_id\n        JOIN m_product_loan l ON l.id = m.product_id\n        LEFT JOIN m_payment_detail d ON d.id = t.payment_detail_id\n        JOIN m_loan_amortization_allocation_mapping map\n             ON map.amortization_loan_transaction_id = t.id\n        JOIN m_loan_transaction bt ON bt.id = map.base_loan_transaction_id\n        LEFT JOIN m_external_asset_owner_transfer e ON e.loan_id = t.loan_id AND\n                 e.settlement_date <\n                 \'${endDate}\' AND\n                 e.effective_date_to >=\n                 \'${endDate}\'\n                  WHERE t.reversed_on_date = \'${endDate}\'\n                    AND t.is_reversed = true\n                    AND t.transaction_type_enum IN (36, 39, 42, 43)\n                    AND (t.office_id = ${officeId})),\n     active_external_asset_owner_transfers AS (SELECT \'${endDate}\' AS transactiondate,\n                t.id,\n                p.name,\n                t.owner_id,\n                t.previous_owner_id,\n                dt.principal_outstanding_derived,\n                dt.interest_outstanding_derived,\n                dt.fee_charges_outstanding_derived,\n                dt.penalty_charges_outstanding_derived,\n                dt.total_overpaid_derived,\n                l.charged_off_on_date,\n                t.settlement_date,\n                l.charge_off_reason_cv_id,\n                (SELECT GROUP_CONCAT(DISTINCT mlo.external_id ORDER BY mlo.external_id SEPARATOR \', \') FROM m_loan_originator_mapping mlom JOIN m_loan_originator mlo ON mlo.id = mlom.originator_id WHERE mlom.loan_id = t.loan_id) AS originator_external_ids\n         FROM m_external_asset_owner_transfer t\n                  JOIN m_loan l ON l.id = t.loan_id\n                  JOIN m_client c ON c.id = l.client_id\n                  JOIN m_product_loan p ON p.id = l.product_id\n                  JOIN m_external_asset_owner_transfer_details dt\n                       ON dt.asset_owner_transfer_id = t.id\n         WHERE t.status in (\'ACTIVE\', \'ACTIVE_INTERMEDIATE\')\n           AND c.office_id = ${officeId}\n           AND t.settlement_date = \'${endDate}\'),\n     buyback_external_asset_owner_transfers AS (SELECT \'${endDate}\' AS transactiondate,\n                 t.id,\n                 p.name,\n                 dt.principal_outstanding_derived,\n                 dt.interest_outstanding_derived,\n                 dt.fee_charges_outstanding_derived,\n                 dt.penalty_charges_outstanding_derived,\n                 dt.total_overpaid_derived,\n                 l.charged_off_on_date,\n                 t.settlement_date,\n                 l.charge_off_reason_cv_id,\n                 t.owner_id,\n                 (SELECT GROUP_CONCAT(DISTINCT mlo.external_id ORDER BY mlo.external_id SEPARATOR \', \') FROM m_loan_originator_mapping mlom JOIN m_loan_originator mlo ON mlo.id = mlom.originator_id WHERE mlom.loan_id = t.loan_id) AS originator_external_ids\n          FROM m_external_asset_owner_transfer t\n                   JOIN m_loan l ON l.id = t.loan_id\n                   JOIN m_client c ON c.id = l.client_id\n                   JOIN m_product_loan p ON p.id = l.product_id\n                   JOIN m_external_asset_owner_transfer_details dt\n                        ON dt.asset_owner_transfer_id = t.id\n          WHERE t.status in (\'BUYBACK\', \'BUYBACK_INTERMEDIATE\')\n            AND c.office_id = ${officeId}\n            AND t.settlement_date = \'${endDate}\')\nSELECT \'${endDate}\' AS TransactionDate,\n       a.product AS Product,\n       CASE\n           WHEN a.transaction_type = 9999 THEN \'Asset Transfer\'\n           WHEN a.transaction_type = 99999 THEN \'Asset Buyback\'\n           ELSE (SELECT enum_message_property\n                 FROM r_enum_value\n                 WHERE enum_name = \'transaction_type_enum\'\n                   AND enum_id = a.transaction_type) END AS TransactionType_Name,\n       COALESCE((SELECT value FROM m_payment_type WHERE id = a.payment_type_id),\n                a.classification_name) AS PaymentType_Name,\n       a.chargetype AS chargetype,\n       a.reversal_indicator AS Reversed,\n       a.Allocation_Type AS Allocation_Type,\n       (SELECT code_value FROM m_code_value WHERE id = a.charge_off_reason_id) AS Chargeoff_ReasonCode,\n       CASE\n           WHEN a.transaction_type = 9999 THEN sum(a.amount) * + 1\n           WHEN a.transaction_type = 99999 THEN sum(a.amount) * - 1\n           WHEN a.transaction_type IN (2, 23, 21, 22, 24, 4, 5, 8, 6, 27, 9, 26, 28, 31, 33, 34, 37, 39, 41, 43) AND\n                a.reversal_indicator = false THEN sum(a.amount) * -1\n           WHEN a.transaction_type IN (2, 23, 21, 22, 24, 4, 5, 8, 6, 27, 9, 26, 28, 31, 33, 34, 37, 39, 41, 43) AND\n                a.reversal_indicator = true THEN sum(a.amount) * + 1\n           WHEN a.transaction_type IN (1, 10, 25, 20, 35, 36, 40, 42) AND a.reversal_indicator = false THEN sum(a.amount) * + 1\n           WHEN a.transaction_type IN (1, 10, 25, 20, 35, 36, 40, 42) AND a.reversal_indicator = true\n               THEN sum(a.amount) * -1 END AS Transaction_Amount,\n       (SELECT external_id\n        FROM m_external_asset_owner\n        WHERE id = a.asset_owner_id) AS Asset_owner_id,\n       (SELECT external_id\n        FROM m_external_asset_owner\n        WHERE id = a.from_asset_owner_id) AS From_asset_owner_id,\n       a.originator_external_ids AS Originator_External_Ids\nFROM (SELECT t.transactiondate,\n             t.id,\n             t.name AS product,\n             t.transaction_type_enum AS transaction_type,\n             t.payment_type_id,\n             t.classification_name,\n             \'\' AS chargetype,\n             false AS reversal_indicator,\n             \'Principal\' AS Allocation_Type,\n             CASE\n                 WHEN t.transaction_type_enum in (1) THEN (CASE\n      WHEN t.amount is null THEN 0\n      WHEN t.overpayment_portion_derived is null THEN t.amount\n      WHEN t.overpayment_portion_derived is not null\n          THEN t.amount - t.overpayment_portion_derived\n      ELSE t.amount END)\n                 ELSE (CASE\n        WHEN t.principal_portion_derived is null THEN 0\n        ELSE t.principal_portion_derived end) END amount,\n             CASE\n                 WHEN t.status in (\'ACTIVE\', \'ACTIVE_INTERMEDIATE\') AND t.settlement_date < \'${endDate}\'\n  THEN t.owner_id END AS asset_owner_id,\n             CASE\n                 WHEN t.transaction_type_enum = 27 OR (t.charged_off_on_date <= t.transaction_date)\n  THEN t.charge_off_reason_cv_id END AS charge_off_reason_id,\n             null AS from_asset_owner_id,\n             t.originator_external_ids\n      FROM slt_except_charge_adj_and_accrual AS t\n      UNION ALL\n      SELECT t.transactiondate,\n             t.id,\n             t.name AS product,\n             t.transaction_type_enum AS transaction_type,\n             t.payment_type_id,\n             t.classification_name,\n             \'\' AS chargetype,\n             false AS reversal_indicator,\n             \'Interest\' AS Allocation_Type,\n             CASE WHEN t.interest_portion_derived is null THEN 0 ELSE t.interest_portion_derived END AS amount,\n             CASE\n                 WHEN t.status in (\'ACTIVE\', \'ACTIVE_INTERMEDIATE\') AND t.settlement_date < \'${endDate}\'\n  THEN t.owner_id END AS asset_owner_id,\n             CASE\n                 WHEN t.transaction_type_enum = 27 OR (t.charged_off_on_date <= t.transaction_date)\n  THEN t.charge_off_reason_cv_id END AS charge_off_reason_id,\n             null AS from_asset_owner_id,\n             t.originator_external_ids\n      FROM slt_except_charge_adj_and_accrual AS t\n      UNION ALL\n      SELECT t.transactiondate,\n             t.id,\n             t.name AS product,\n             t.transaction_type_enum AS transaction_type,\n             t.payment_type_id,\n             t.classification_name,\n             \'\' AS chargetype,\n             false AS reversal_indicator,\n             \'Fees\' AS Allocation_Type,\n             CASE WHEN t.fee_charges_portion_derived is null THEN 0 ELSE t.fee_charges_portion_derived END AS amount,\n             CASE\n                 WHEN t.status in (\'ACTIVE\', \'ACTIVE_INTERMEDIATE\') AND t.settlement_date < \'${endDate}\'\n  THEN t.owner_id END AS asset_owner_id,\n             CASE\n                 WHEN t.transaction_type_enum = 27 OR (t.charged_off_on_date <= t.transaction_date)\n  THEN t.charge_off_reason_cv_id END AS charge_off_reason_id,\n             null AS from_asset_owner_id,\n             t.originator_external_ids\n      FROM slt_except_charge_adj_and_accrual AS t\n      UNION ALL\n      SELECT t.transactiondate,\n             t.id,\n             t.name AS product,\n             t.transaction_type_enum AS transaction_type,\n             t.payment_type_id,\n             t.classification_name,\n             \'\' AS chargetype,\n             false AS reversal_indicator,\n             \'Penalty\' AS Allocation_Type,\n             CASE\n                 WHEN t.penalty_charges_portion_derived is null THEN 0\n                 ELSE t.penalty_charges_portion_derived END AS amount,\n             CASE\n                 WHEN t.status in (\'ACTIVE\', \'ACTIVE_INTERMEDIATE\') AND t.settlement_date < \'${endDate}\'\n  THEN t.owner_id END AS asset_owner_id,\n             CASE\n                 WHEN t.transaction_type_enum = 27 OR (t.charged_off_on_date <= t.transaction_date)\n  THEN t.charge_off_reason_cv_id END AS charge_off_reason_id,\n             null AS from_asset_owner_id,\n             t.originator_external_ids\n      FROM slt_except_charge_adj_and_accrual AS t\n      UNION ALL\n      SELECT t.transactiondate,\n             t.id,\n             t.name AS product,\n             t.transaction_type_enum AS transaction_type,\n             t.payment_type_id,\n             t.classification_name,\n             \'\' AS chargetype,\n             false AS reversal_indicator,\n             \'Unallocated Credit (UNC)\' AS Allocation_Type,\n             CASE WHEN t.overpayment_portion_derived is null THEN 0 ELSE t.overpayment_portion_derived END AS amount,\n             CASE\n                 WHEN t.status in (\'ACTIVE\', \'ACTIVE_INTERMEDIATE\') AND t.settlement_date < \'${endDate}\'\n  THEN t.owner_id END AS asset_owner_id,\n             CASE\n                 WHEN t.transaction_type_enum = 27 OR (t.charged_off_on_date <= t.transaction_date)\n  THEN t.charge_off_reason_cv_id END AS charge_off_reason_id,\n             null AS from_asset_owner_id,\n             t.originator_external_ids\n      FROM slt_except_charge_adj_and_accrual AS t\n      UNION ALL\n      SELECT \'${endDate}\' AS transactiondate,\n             t.id,\n             t.name AS product,\n             t.transaction_type_enum AS transaction_type,\n             t.payment_type_id,\n             t.classification_name,\n             \'\' AS chargetype,\n             false AS reversal_indicator,\n             \'Fees\' AS Allocation_Type,\n             CASE WHEN t.fee_charges_portion_derived is null THEN 0 ELSE t.fee_charges_portion_derived END AS amount,\n             CASE\n                 WHEN t.status in (\'ACTIVE\', \'ACTIVE_INTERMEDIATE\') AND t.settlement_date < \'${endDate}\'\n  THEN t.owner_id END AS asset_owner_id,\n             CASE\n                 WHEN t.charged_off_on_date <= t.transaction_date\n  THEN t.charge_off_reason_cv_id END AS charge_off_reason_id,\n             null AS from_asse